import React, { useEffect } from 'react';
import { useTetris } from './hooks/useTetris';
import BoardView from './components/BoardView';
import Controls from './components/Controls';
import GameUI from './components/GameUI';
import AISuggestions from './components/AISuggestions';
import { Direction, Position, Board, Difficulty } from './types';

const App: React.FC = () => {
  const { 
    board, 
    activePiece, 
    nextPiece, 
    score, 
    highScore,
    level, 
    lines, 
    gameOver, 
    paused, 
    difficulty,
    isGameStarted,
    setPaused, 
    move, 
    rotate, 
    hardDrop, 
    resetGame,
    startGame
  } = useTetris();

  // Handle Keyboard Controls
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (gameOver || !isGameStarted) return;

      switch (e.key) {
        case 'ArrowLeft': move(Direction.Left); break;
        case 'ArrowRight': move(Direction.Right); break;
        case 'ArrowDown': move(Direction.Down); break;
        case 'ArrowUp': rotate(); break;
        case ' ': hardDrop(); break;
        case 'p': setPaused(!paused); break;
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [move, rotate, hardDrop, paused, setPaused, gameOver, isGameStarted]);

  // Collisions helper for BoardView (Ghost piece calc)
  const checkCollisionHelper = (shape: number[][], pos: Position, b: Board) => {
    for (let y = 0; y < shape.length; y++) {
      for (let x = 0; x < shape[y].length; x++) {
        if (shape[y][x] !== 0) {
          const newX = pos.x + x;
          const newY = pos.y + y;
          if (newX < 0 || newX >= 10 || newY >= 20 || (newY >= 0 && b[newY][newX] !== null)) {
            return true;
          }
        }
      }
    }
    return false;
  };

  return (
    <div className="min-h-screen bg-slate-950 flex flex-col items-center justify-start py-6 px-2 overflow-hidden relative">
      {/* Background decoration */}
      <div className="absolute top-0 left-0 w-full h-full opacity-10 pointer-events-none">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-indigo-600 blur-[120px] rounded-full"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-cyan-600 blur-[120px] rounded-full"></div>
      </div>

      <header className="mb-4 sm:mb-6 flex items-center justify-between w-full max-w-md px-4 z-10">
        <h1 className="text-xl sm:text-2xl font-orbitron font-bold tracking-tighter text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 to-indigo-400">
          NEON TETRIS <span className="text-[10px] bg-indigo-500 text-white px-1.5 py-0.5 rounded ml-1 align-top">AI</span>
        </h1>
        {isGameStarted && (
          <button 
            onClick={() => setPaused(!paused)}
            className="bg-slate-800 hover:bg-slate-700 w-10 h-10 rounded-full flex items-center justify-center transition-all shadow-lg"
          >
            <i className={`fa-solid ${paused ? 'fa-play pl-1' : 'fa-pause'}`}></i>
          </button>
        )}
      </header>

      <div className="flex gap-4 items-start z-10">
        <BoardView 
          board={board} 
          activePiece={activePiece} 
          checkCollision={checkCollisionHelper}
        />
        <GameUI 
          score={score} 
          highScore={highScore}
          level={level} 
          lines={lines} 
          nextPiece={nextPiece}
        />
      </div>

      <AISuggestions 
        board={board} 
        nextPiece={nextPiece} 
        score={score} 
        level={level} 
      />

      <Controls 
        onMove={move} 
        onRotate={rotate} 
        onHardDrop={hardDrop} 
      />

      {/* Start / Difficulty Selection Overlay */}
      {!isGameStarted && (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-md flex items-center justify-center z-50 p-6">
          <div className="bg-slate-900 border-2 border-indigo-500/30 p-8 rounded-[2rem] text-center shadow-2xl max-w-sm w-full">
            <div className="w-20 h-20 bg-indigo-600 rounded-2xl mx-auto mb-6 flex items-center justify-center text-4xl shadow-indigo-500/50 shadow-xl">
               <i className="fa-solid fa-gamepad"></i>
            </div>
            <h2 className="text-3xl font-orbitron font-bold text-white mb-2 tracking-tight">READY?</h2>
            <p className="text-slate-400 text-sm mb-8 italic">Choose your challenge level</p>

            <div className="flex flex-col gap-3">
              {(Object.keys(Difficulty) as Array<keyof typeof Difficulty>).map((diff) => (
                <button
                  key={diff}
                  onClick={() => startGame(Difficulty[diff])}
                  className={`py-4 rounded-2xl font-bold uppercase tracking-widest transition-all active:scale-95 shadow-lg border-b-4 ${
                    diff === 'Easy' ? 'bg-green-600 border-green-800 hover:bg-green-500' :
                    diff === 'Medium' ? 'bg-indigo-600 border-indigo-800 hover:bg-indigo-500' :
                    'bg-red-600 border-red-800 hover:bg-red-500'
                  }`}
                >
                  {diff}
                </button>
              ))}
            </div>
            <div className="mt-8 text-xs text-slate-500">
               Best Score: <span className="text-yellow-500 font-bold">{highScore.toLocaleString()}</span>
            </div>
          </div>
        </div>
      )}

      {/* Game Over Overlay */}
      {gameOver && (
        <div className="fixed inset-0 bg-black/85 backdrop-blur-sm flex items-center justify-center z-50 p-6">
          <div className="bg-slate-900 border-2 border-red-500/50 p-8 rounded-[2rem] text-center shadow-2xl max-w-xs w-full">
            <h2 className="text-4xl font-orbitron font-bold text-red-500 mb-2">GAME OVER</h2>
            <p className="text-slate-400 mb-6">Level {level} reached!</p>
            <div className="mb-8 space-y-4">
              <div>
                <div className="text-[10px] text-slate-500 uppercase tracking-widest mb-1">Final Score</div>
                <div className="text-3xl font-orbitron font-bold text-white">{score.toLocaleString()}</div>
              </div>
              {score >= highScore && score > 0 && (
                <div className="text-yellow-400 font-bold text-xs uppercase animate-bounce">
                  New High Score!
                </div>
              )}
            </div>
            <button 
              onClick={resetGame}
              className="w-full py-4 bg-slate-100 text-slate-900 hover:bg-white rounded-2xl font-bold uppercase tracking-widest shadow-lg transition-transform active:scale-95"
            >
              Main Menu
            </button>
          </div>
        </div>
      )}

      {/* Pause Overlay */}
      {paused && !gameOver && isGameStarted && (
        <div className="fixed inset-0 bg-black/40 backdrop-blur-sm flex items-center justify-center z-40 p-6">
          <div className="bg-slate-900 border-2 border-indigo-500/50 p-8 rounded-[2rem] text-center shadow-2xl w-full max-w-xs">
            <h2 className="text-3xl font-orbitron font-bold text-indigo-400 mb-6 uppercase">Paused</h2>
            <div className="flex flex-col gap-3">
              <button 
                onClick={() => setPaused(false)}
                className="w-full py-4 bg-indigo-600 hover:bg-indigo-500 rounded-2xl font-bold uppercase tracking-widest shadow-lg transition-transform active:scale-95"
              >
                Resume
              </button>
              <button 
                onClick={resetGame}
                className="w-full py-4 bg-slate-800 hover:bg-slate-700 rounded-2xl font-bold uppercase tracking-widest shadow-lg transition-transform active:scale-95 text-slate-400"
              >
                Quit Game
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

