import React from 'react';
import { Board, ActivePiece, Position } from '../types';
import { ROWS, COLS } from '../constants';

interface BoardViewProps {
  board: Board;
  activePiece: ActivePiece | null;
  checkCollision: (shape: number[][], pos: Position, board: Board) => boolean;
}

const BoardView: React.FC<BoardViewProps> = ({ board, activePiece, checkCollision }) => {
  // Calculate ghost position
  let ghostY = activePiece?.position.y || 0;
  if (activePiece) {
    while (!checkCollision(activePiece.tetromino.shape, { x: activePiece.position.x, y: ghostY + 1 }, board)) {
      ghostY++;
    }
  }

  const renderCell = (y: number, x: number) => {
    let color = board[y][x];
    let isGhost = false;
    let isActive = false;

    if (activePiece) {
      // Check active piece
      const shape = activePiece.tetromino.shape;
      const py = y - activePiece.position.y;
      const px = x - activePiece.position.x;
      if (py >= 0 && py < shape.length && px >= 0 && px < shape[0].length && shape[py][px]) {
        color = activePiece.tetromino.color;
        isActive = true;
      }

      // Check ghost piece
      const gy = y - ghostY;
      if (!isActive && gy >= 0 && gy < shape.length && px >= 0 && px < shape[0].length && shape[gy][px]) {
        color = activePiece.tetromino.color;
        isGhost = true;
      }
    }

    return (
      <div
        key={`${y}-${x}`}
        className={`
          w-full h-full border-[0.5px] border-slate-800/30 
          ${color || 'bg-slate-900/40'} 
          ${isGhost ? 'opacity-20 brightness-75' : 'opacity-100'}
          ${isActive ? 'neon-shadow ring-1 ring-white/20 z-10' : ''}
          rounded-sm transition-all duration-75
        `}
      />
    );
  };

  return (
    <div className="h-full aspect-[1/2] grid grid-cols-10 grid-rows-20 gap-px bg-slate-950 p-0.5 rounded-lg border-2 border-slate-700 shadow-2xl relative overflow-hidden">
      {board.map((row, y) => row.map((_, x) => renderCell(y, x)))}
    </div>
  );
};

export default BoardView;

