import React, { useState, useEffect, useCallback } from 'react';
import { useTetris } from './hooks/useTetris';
import BoardView from './components/BoardView';
import Controls from './components/Controls';
import GameUI from './components/GameUI';
import AISuggestions from './components/AISuggestions';
import { Direction, Position, Board, Difficulty, UserProfile } from './types';

const STORAGE_KEY = 'tetris_prime_profiles';

const App: React.FC = () => {
  const [profiles, setProfiles] = useState<UserProfile[]>([]);
  const [activeProfile, setActiveProfile] = useState<UserProfile | null>(null);
  const [showProfileSelector, setShowProfileSelector] = useState(true);
  const [newProfileName, setNewProfileName] = useState('');

  const { 
    board, activePiece, nextPiece, score, highScore, level, lines, bombs, useBomb,
    gameOver, paused, difficulty, isGameStarted, setPaused, 
    move, rotate, hardDrop, resetGame, startGame 
  } = useTetris(activeProfile);

  // Load profiles on mount
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      setProfiles(JSON.parse(saved));
    }
  }, []);

  // Persist profiles on change
  useEffect(() => {
    if (profiles.length > 0) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(profiles));
    }
  }, [profiles]);

  // Handle Game Over - Update Profile Stats
  useEffect(() => {
    if (gameOver && activeProfile) {
      const updatedProfiles = profiles.map(p => {
        if (p.id === activeProfile.id) {
          const newBest = Math.max(p.bestScore, score);
          return {
            ...p,
            bestScore: newBest,
            totalLines: p.totalLines + lines,
            gamesPlayed: p.gamesPlayed + 1
          };
        }
        return p;
      });
      setProfiles(updatedProfiles);
      // Sync active profile
      const current = updatedProfiles.find(p => p.id === activeProfile.id);
      if (current) setActiveProfile(current);
    }
  }, [gameOver]);

  const handleCreateProfile = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newProfileName.trim()) return;
    const newProfile: UserProfile = {
      id: Date.now().toString(),
      name: newProfileName.trim(),
      bestScore: 0,
      totalLines: 0,
      gamesPlayed: 0
    };
    setProfiles(prev => [...prev, newProfile]);
    setActiveProfile(newProfile);
    setNewProfileName('');
    setShowProfileSelector(false);
  };

  const selectProfile = (p: UserProfile) => {
    setActiveProfile(p);
    setShowProfileSelector(false);
  };

  const logout = () => {
    setActiveProfile(null);
    setShowProfileSelector(true);
    resetGame();
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (gameOver || !isGameStarted) return;
      switch (e.key) {
        case 'ArrowLeft': move(Direction.Left); break;
        case 'ArrowRight': move(Direction.Right); break;
        case 'ArrowDown': move(Direction.Down); break;
        case 'ArrowUp': rotate(); break;
        case ' ': hardDrop(); break;
        case 'b': useBomb(); break;
        case 'p': setPaused(!paused); break;
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [move, rotate, hardDrop, useBomb, paused, setPaused, gameOver, isGameStarted]);

  const checkCollisionHelper = (shape: number[][], pos: Position, b: Board) => {
    for (let y = 0; y < shape.length; y++) {
      for (let x = 0; x < shape[y].length; x++) {
        if (shape[y][x] !== 0) {
          const newX = pos.x + x;
          const newY = pos.y + y;
          if (newX < 0 || newX >= 10 || newY >= 20 || (newY >= 0 && b[newY][newX] !== null)) return true;
        }
      }
    }
    return false;
  };

  // Home Page / Profile Selector Component
  if (showProfileSelector) {
    return (
      <div className="h-screen bg-[#050505] text-slate-200 flex flex-col items-center justify-center p-6 font-sans">
        <div className="w-full max-w-sm space-y-12">
          <div className="text-center space-y-1">
            <h1 className="text-4xl font-bold tracking-tighter text-white uppercase">Tetris Prime</h1>
            <p className="text-[10px] text-slate-500 uppercase tracking-[0.4em]">Neural Network Gameplay</p>
          </div>

          <div className="space-y-6">
            <div className="space-y-3">
              <h2 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest px-1">Select Operator</h2>
              <div className="max-h-60 overflow-y-auto space-y-2 custom-scrollbar pr-1">
                {profiles.map(p => (
                  <button
                    key={p.id}
                    onClick={() => selectProfile(p)}
                    className="w-full p-4 border border-slate-800 hover:border-slate-400 hover:bg-white/5 flex items-center justify-between group transition-all"
                  >
                    <div className="text-left">
                      <div className="text-sm font-bold group-hover:text-white">{p.name}</div>
                      <div className="text-[8px] text-slate-500 uppercase tracking-widest mt-0.5">Rank: {Math.floor(p.totalLines/10) + 1}</div>
                    </div>
                    <div className="text-right">
                      <div className="text-xs font-mono text-slate-400">{p.bestScore.toLocaleString()}</div>
                      <div className="text-[7px] text-slate-600 uppercase tracking-widest">Best Pts</div>
                    </div>
                  </button>
                ))}
                {profiles.length === 0 && (
                  <div className="text-center py-8 border border-dashed border-slate-800 text-[9px] text-slate-600 uppercase tracking-widest">
                    No Operators Detected
                  </div>
                )}
              </div>
            </div>

            <form onSubmit={handleCreateProfile} className="space-y-3 pt-4 border-t border-slate-900">
              <h2 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest px-1">Register New Operator</h2>
              <div className="flex gap-2">
                <input
                  type="text"
                  placeholder="DESIGNATION NAME"
                  value={newProfileName}
                  onChange={(e) => setNewProfileName(e.target.value.toUpperCase())}
                  maxLength={12}
                  className="flex-1 bg-transparent border border-slate-800 px-4 py-3 text-xs focus:border-white focus:outline-none transition-all placeholder:text-slate-700"
                />
                <button
                  type="submit"
                  className="bg-white text-black px-4 py-3 text-xs font-bold uppercase tracking-widest hover:bg-slate-200 transition-colors"
                >
                  Add
                </button>
              </div>
            </form>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="h-screen bg-[#050505] text-slate-200 flex flex-col items-center justify-between py-2 px-3 overflow-hidden font-sans">
      <header className="w-full max-w-md flex items-center justify-between px-1 z-10 shrink-0 mb-1">
        <div className="flex flex-col">
          <div className="flex items-center gap-2">
            <h1 className="text-xs font-bold tracking-widest text-white uppercase">Tetris Prime</h1>
            <span className="text-[8px] text-slate-500 uppercase tracking-widest border border-slate-800 px-1.5 py-0.5">OP: {activeProfile?.name}</span>
          </div>
          <span className="text-[6px] text-slate-600 uppercase tracking-widest -mt-1">Active AI Assistance</span>
        </div>
        <div className="flex items-center gap-2">
          {isGameStarted && (
            <button 
              onClick={() => setPaused(!paused)}
              className="w-6 h-6 flex items-center justify-center text-slate-500 hover:text-white transition-colors"
            >
              <i className={`fa-solid ${paused ? 'fa-play' : 'fa-pause'} text-[10px]`}></i>
            </button>
          )}
          <button 
            onClick={logout}
            className="text-[8px] font-bold text-slate-500 hover:text-red-500 uppercase tracking-widest border border-slate-800 px-2 py-1 transition-all"
          >
            Logout
          </button>
        </div>
      </header>

      <div className="flex gap-2 items-stretch justify-center w-full max-w-md h-[78vh] z-10">
        <div className="flex-1 flex justify-center">
          <BoardView board={board} activePiece={activePiece} checkCollision={checkCollisionHelper} />
        </div>
        <GameUI score={score} highScore={highScore} level={level} lines={lines} bombs={bombs} nextPiece={nextPiece} />
      </div>

      <div className="w-full flex flex-col items-center gap-1.5 z-10 shrink-0 mt-1">
        <AISuggestions board={board} nextPiece={nextPiece} score={score} level={level} />
        <Controls onMove={move} onRotate={rotate} onHardDrop={hardDrop} onBomb={useBomb} bombs={bombs} />
      </div>

      {!isGameStarted && (
        <div className="fixed inset-0 bg-black/95 flex items-center justify-center z-50 p-6 backdrop-blur-sm">
          <div className="w-full max-w-xs space-y-8 text-center">
            <div className="space-y-1">
              <h2 className="text-3xl font-bold tracking-tighter text-white uppercase">Initialize</h2>
              <p className="text-[9px] text-slate-500 uppercase tracking-[0.3em]">Operator: {activeProfile?.name}</p>
            </div>
            <div className="flex flex-col gap-2">
              {(Object.keys(Difficulty) as Array<keyof typeof Difficulty>).map((diff) => (
                <button
                  key={diff}
                  onClick={() => startGame(Difficulty[diff])}
                  className="py-3 border border-slate-800 hover:bg-white hover:text-black transition-all text-xs font-bold uppercase tracking-widest"
                >
                  {diff}
                </button>
              ))}
            </div>
          </div>
        </div>
      )}

      {gameOver && (
        <div className="fixed inset-0 bg-black/90 flex items-center justify-center z-50 p-6 backdrop-blur-md">
          <div className="w-full max-w-xs text-center space-y-6">
            <h2 className="text-3xl font-bold tracking-tighter text-white uppercase">Mission Failed</h2>
            <div className="py-4 border-y border-slate-800">
              <div className="text-[8px] text-slate-500 uppercase tracking-widest mb-1">Final Score</div>
              <div className="text-2xl font-bold text-white">{score.toLocaleString()}</div>
              {score >= (activeProfile?.bestScore || 0) && score > 0 && (
                <div className="text-yellow-500 text-[8px] uppercase tracking-widest mt-2">New Career Best</div>
              )}
            </div>
            <button 
              onClick={resetGame}
              className="w-full py-4 bg-white text-black text-xs font-bold uppercase tracking-widest"
            >
              Retry Mission
            </button>
          </div>
        </div>
      )}

      {paused && !gameOver && isGameStarted && (
        <div className="fixed inset-0 bg-black/70 flex items-center justify-center z-40 backdrop-blur-sm">
          <div className="w-full max-w-xs text-center space-y-4">
            <h2 className="text-xl font-bold uppercase tracking-widest">Suspended</h2>
            <button 
              onClick={() => setPaused(false)}
              className="w-full py-3 bg-white text-black text-xs font-bold uppercase"
            >
              Resume
            </button>
            <button 
              onClick={resetGame}
              className="w-full py-3 border border-slate-800 text-slate-400 text-xs font-bold uppercase"
            >
              Abort
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

