import React, { useState, useEffect, useCallback, useRef } from 'react';

interface SnakeGameProps {
  onExit: () => void;
  onGameOver: (score: number) => void;
  highScore: number;
}

type Point = { x: number, y: number };

const GRID_SIZE = 20;
const INITIAL_SNAKE = [{ x: 10, y: 10 }, { x: 10, y: 11 }, { x: 10, y: 12 }];
const INITIAL_DIR = { x: 0, y: -1 };

const SnakeGame: React.FC<SnakeGameProps> = ({ onExit, onGameOver, highScore }) => {
  const [snake, setSnake] = useState<Point[]>(INITIAL_SNAKE);
  const [food, setFood] = useState<Point>({ x: 5, y: 5 });
  const [dir, setDir] = useState<Point>(INITIAL_DIR);
  const [score, setScore] = useState(0);
  const [gameOver, setGameOver] = useState(false);
  const [paused, setPaused] = useState(false);
  const gameLoopRef = useRef<number | null>(null);

  const generateFood = useCallback((currentSnake: Point[]) => {
    let newFood;
    while (true) {
      newFood = {
        x: Math.floor(Math.random() * GRID_SIZE),
        y: Math.floor(Math.random() * GRID_SIZE)
      };
      const collision = currentSnake.some(p => p.x === newFood.x && p.y === newFood.y);
      if (!collision) break;
    }
    return newFood;
  }, []);

  const moveSnake = useCallback(() => {
    if (gameOver || paused) return;

    setSnake(prev => {
      const head = prev[0];
      const newHead = { x: head.x + dir.x, y: head.y + dir.y };

      // Wall collision
      if (newHead.x < 0 || newHead.x >= GRID_SIZE || newHead.y < 0 || newHead.y >= GRID_SIZE) {
        setGameOver(true);
        onGameOver(score);
        return prev;
      }

      // Self collision
      if (prev.some(p => p.x === newHead.x && p.y === newHead.y)) {
        setGameOver(true);
        onGameOver(score);
        return prev;
      }

      const newSnake = [newHead, ...prev];

      // Food collision
      if (newHead.x === food.x && newHead.y === food.y) {
        setScore(s => s + 10);
        setFood(generateFood(newSnake));
      } else {
        newSnake.pop();
      }

      return newSnake;
    });
  }, [dir, food, gameOver, paused, score, generateFood, onGameOver]);

  useEffect(() => {
    const speed = Math.max(80, 200 - Math.floor(score / 50) * 10);
    gameLoopRef.current = window.setInterval(moveSnake, speed);
    return () => { if (gameLoopRef.current) clearInterval(gameLoopRef.current); };
  }, [moveSnake, score]);

  useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
      switch (e.key) {
        case 'ArrowUp': if (dir.y === 0) setDir({ x: 0, y: -1 }); break;
        case 'ArrowDown': if (dir.y === 0) setDir({ x: 0, y: 1 }); break;
        case 'ArrowLeft': if (dir.x === 0) setDir({ x: -1, y: 0 }); break;
        case 'ArrowRight': if (dir.x === 0) setDir({ x: 1, y: 0 }); break;
      }
    };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, [dir]);

  return (
    <div className="flex flex-col items-center gap-4 w-full max-w-md animate-in fade-in zoom-in duration-300">
      <div className="w-full flex justify-between items-center px-2">
        <div className="flex flex-col">
          <h2 className="text-xl font-bold tracking-tighter text-white uppercase font-orbitron">SNAKE PRIME</h2>
          <span className="text-[8px] text-slate-500 uppercase tracking-widest">
            Best: {highScore} | Score: {score}
          </span>
        </div>
        <button onClick={onExit} className="px-3 py-1 border border-slate-800 text-[10px] uppercase font-bold text-slate-400 hover:text-white">
          Exit Room
        </button>
      </div>

      <div 
        className="relative w-full aspect-square bg-slate-950 border-2 border-slate-900 rounded-sm overflow-hidden"
        style={{ display: 'grid', gridTemplateColumns: `repeat(${GRID_SIZE}, 1fr)` }}
      >
        {Array.from({ length: GRID_SIZE * GRID_SIZE }).map((_, i) => {
          const x = i % GRID_SIZE;
          const y = Math.floor(i / GRID_SIZE);
          const isSnakeHead = snake[0].x === x && snake[0].y === y;
          const isSnakeBody = snake.slice(1).some(p => p.x === x && p.y === y);
          const isFood = food.x === x && food.y === y;

          return (
            <div 
              key={i} 
              className={`w-full h-full border-[0.5px] border-slate-900/30 
                ${isSnakeHead ? 'bg-green-400 shadow-[0_0_10px_rgba(74,222,128,0.5)] z-10' : ''}
                ${isSnakeBody ? 'bg-green-900/60' : ''}
                ${isFood ? 'bg-red-500 animate-pulse rounded-full scale-75' : ''}
              `}
            />
          );
        })}

        {gameOver && (
          <div className="absolute inset-0 bg-black/80 flex flex-col items-center justify-center z-50 backdrop-blur-sm">
            <h3 className="text-2xl font-bold text-red-500 uppercase font-orbitron mb-2">Impact Detected</h3>
            <p className="text-xs text-slate-400 uppercase tracking-widest mb-6">Final Length: {snake.length}</p>
            <button 
              onClick={() => {
                setSnake(INITIAL_SNAKE);
                setDir(INITIAL_DIR);
                setScore(0);
                setGameOver(false);
              }}
              className="bg-white text-black px-8 py-3 font-bold text-[10px] uppercase tracking-widest hover:bg-slate-200"
            >
              Reboot System
            </button>
          </div>
        )}
      </div>

      {/* Large Controls for Mobile */}
      <div className="grid grid-cols-3 gap-2 w-full mt-4">
        <div />
        <button 
          onClick={() => { if (dir.y === 0) setDir({ x: 0, y: -1 }); }}
          className="h-16 border border-slate-800 flex items-center justify-center rounded-lg active:bg-slate-800"
        >
          <i className="fa-solid fa-chevron-up text-xl"></i>
        </button>
        <div />

        <button 
          onClick={() => { if (dir.x === 0) setDir({ x: -1, y: 0 }); }}
          className="h-16 border border-slate-800 flex items-center justify-center rounded-lg active:bg-slate-800"
        >
          <i className="fa-solid fa-chevron-left text-xl"></i>
        </button>
        <button 
          onClick={() => { if (dir.y === 0) setDir({ x: 0, y: 1 }); }}
          className="h-16 border border-slate-800 flex items-center justify-center rounded-lg active:bg-slate-800"
        >
          <i className="fa-solid fa-chevron-down text-xl"></i>
        </button>
        <button 
          onClick={() => { if (dir.x === 0) setDir({ x: 1, y: 0 }); }}
          className="h-16 border border-slate-800 flex items-center justify-center rounded-lg active:bg-slate-800"
        >
          <i className="fa-solid fa-chevron-right text-xl"></i>
        </button>
      </div>
    </div>
  );
};

