            <p className="text-[10px] text-slate-500 uppercase tracking-[0.4em]">Integrated Intelligence System</p>
          </div>

          <div className="space-y-6">
            <div className="space-y-3">
              <h2 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest px-1">Select Operator</h2>
