                      <div className="text-[8px] text-slate-600 uppercase tracking-widest mt-0.5">Experience Locked</div>
                    </div>
                    <i className="fa-solid fa-chevron-right text-[10px] text-slate-700 group-hover:text-blue-500"></i>
                  </button>
                ))}
