      </div>

      {!isGameStarted && (
        <div className="fixed inset-0 bg-black/95 flex items-center justify-center z-50 p-6 backdrop-blur-sm">
          <div className="w-full max-w-xs space-y-8 text-center">
            <div className="space-y-1">
              <h2 className="text-3xl font-bold tracking-tighter text-white uppercase">Initialize</h2>
              <p className="text-[9px] text-slate-500 uppercase tracking-[0.3em]">Operator: {activeProfile?.name}</p>
            </div>
            <div className="flex flex-col gap-2">
              {(Object.keys(Difficulty) as Array<keyof typeof Difficulty>).map((diff) => (
                <button
                  key={diff}
                  onClick={() => startGame(Difficulty[diff])}
                  className="py-3 border border-slate-800 hover:bg-white hover:text-black transition-all text-xs font-bold uppercase tracking-widest"
                >
                  {diff}
                </button>
              ))}
            </div>
            <button onClick={() => setCurrentView('hub')} className="text-[10px] text-slate-600 uppercase font-bold tracking-widest hover:text-slate-400">Cancel</button>
          </div>
        </div>
      )}

      {gameOver && (
        <div className="fixed inset-0 bg-black/90 flex items-center justify-center z-50 p-6 backdrop-blur-md">
          <div className="w-full max-w-xs text-center space-y-6">
            <h2 className="text-3xl font-bold tracking-tighter text-white uppercase">Mission Failed</h2>
            <div className="py-4 border-y border-slate-800">
              <div className="text-[8px] text-slate-500 uppercase tracking-widest mb-1">Final Score</div>
              <div className="text-2xl font-bold text-white">{score.toLocaleString()}</div>
              {score >= (activeProfile?.tetrisStats.bestScore || 0) && score > 0 && (
                <div className="text-yellow-500 text-[8px] uppercase tracking-widest mt-2">New Career Best</div>
              )}
            </div>
            <button 
              onClick={resetGame}
              className="w-full py-4 bg-white text-black text-xs font-bold uppercase tracking-widest"
            >
              Retry Mission
            </button>
            <button 
              onClick={() => setCurrentView('hub')}
              className="w-full py-2 text-slate-500 text-[10px] uppercase font-bold tracking-widest"
            >
              Back to Hub
            </button>
          </div>
        </div>
      )}

      {paused && !gameOver && isGameStarted && (
        <div className="fixed inset-0 bg-black/70 flex items-center justify-center z-40 backdrop-blur-sm">
          <div className="w-full max-w-xs text-center space-y-4">
            <h2 className="text-xl font-bold uppercase tracking-widest">Suspended</h2>
            <button onClick={() => setPaused(false)} className="w-full py-3 bg-white text-black text-xs font-bold uppercase">Resume</button>
            <button onClick={() => { resetGame(); setCurrentView('hub'); }} className="w-full py-3 border border-slate-800 text-slate-400 text-xs font-bold uppercase">Abort</button>
          </div>
        </div>
      )}
    </div>
  );
};

