import { useState, useEffect, useCallback, useRef } from 'react';
import { 
  Board, 
  Position, 
  Tetromino, 
  Direction, 
  Shape,
  Difficulty,
  UserProfile
} from '../types';
import { 
  COLS, 
  ROWS, 
  getRandomTetromino, 
  MIN_DROP_SPEED 
} from '../constants';
import { useSound } from './useSound';

const createEmptyBoard = (): Board => 
  Array.from({ length: ROWS }, () => Array(COLS).fill(null));

const DIFFICULTY_SPEEDS: Record<Difficulty, number> = {
  [Difficulty.Easy]: 1000,
  [Difficulty.Medium]: 700,
  [Difficulty.Hard]: 400,
};

const SCORING = [0, 100, 300, 500, 1200];
const T_SPIN_BONUS = [400, 800, 1200, 1600]; // Bonus for 0, 1, 2, 3 lines cleared with T-Spin

export const useTetris = (activeProfile: UserProfile | null) => {
  const { playMove, playRotate, playClear, playDrop, playGameOver, playBomb } = useSound();
  const [board, setBoard] = useState<Board>(createEmptyBoard());
  const [activePiece, setActivePiece] = useState<{ tetromino: Tetromino; position: Position } | null>(null);
  const [nextPiece, setNextPiece] = useState<Tetromino>(getRandomTetromino());
  const [score, setScore] = useState(0);
  const [highScore, setHighScore] = useState(0);
  const [level, setLevel] = useState(1);
  const [lines, setLines] = useState(0);
  const [bombs, setBombs] = useState(0);
  const [gameOver, setGameOver] = useState(false);
  const [paused, setPaused] = useState(false);
  const [difficulty, setDifficulty] = useState<Difficulty>(Difficulty.Medium);
  const [isGameStarted, setIsGameStarted] = useState(false);

  const timerRef = useRef<number | null>(null);
  const isLastMoveRotation = useRef(false);

  useEffect(() => {
    if (activeProfile) {
      setHighScore(activeProfile.tetrisStats.bestScore);
    }
  }, [activeProfile]);

  const checkCollision = useCallback((shape: Shape, pos: Position, currentBoard: Board): boolean => {
    for (let y = 0; y < shape.length; y++) {
      for (let x = 0; x < shape[y].length; x++) {
        if (shape[y][x] !== 0) {
          const newX = pos.x + x;
          const newY = pos.y + y;
          if (newX < 0 || newX >= COLS || newY >= ROWS || (newY >= 0 && currentBoard[newY][newX] !== null)) {
            return true;
          }
        }
      }
    }
    return false;
  }, []);

  const isTSpinMove = (piece: { tetromino: Tetromino; position: Position }, currentBoard: Board): boolean => {
    if (piece.tetromino.id !== 'T' || !isLastMoveRotation.current) return false;

    // Check corners of the 3x3 T-piece grid
    // Corners are [0,0], [0,2], [2,0], [2,2] relative to piece position
    const corners = [
      { x: 0, y: 0 },
      { x: 2, y: 0 },
      { x: 0, y: 2 },
      { x: 2, y: 2 }
    ];

    let occupiedCorners = 0;
    for (const corner of corners) {
      const boardX = piece.position.x + corner.x;
      const boardY = piece.position.y + corner.y;

      if (boardX < 0 || boardX >= COLS || boardY >= ROWS || (boardY >= 0 && currentBoard[boardY][boardX] !== null)) {
        occupiedCorners++;
      }
    }

    return occupiedCorners >= 3;
  };

  const finalizePiece = useCallback((pieceToLock: { tetromino: Tetromino; position: Position }) => {
    setBoard(prevBoard => {
      const newBoard = prevBoard.map(row => [...row]);
      pieceToLock.tetromino.shape.forEach((row, y) => {
        row.forEach((value, x) => {
          if (value !== 0) {
            const boardY = pieceToLock.position.y + y;
            const boardX = pieceToLock.position.x + x;
            if (boardY >= 0 && boardY < ROWS && boardX >= 0 && boardX < COLS) {
              newBoard[boardY][boardX] = pieceToLock.tetromino.color;
            }
          }
        });
      });

      const tSpin = isTSpinMove(pieceToLock, prevBoard);
      let clearedCount = 0;
      const filteredBoard = newBoard.filter(row => {
        const isFull = row.every(cell => cell !== null);
        if (isFull) clearedCount++;
        return !isFull;
      });

      while (filteredBoard.length < ROWS) filteredBoard.unshift(Array(COLS).fill(null));

      let points = SCORING[clearedCount] * level;
      if (tSpin) {
        points += T_SPIN_BONUS[Math.min(clearedCount, 3)] * level;
        console.log(`T-SPIN DETECTED! Lines: ${clearedCount}. Bonus Points Awarded.`);
      }

      if (clearedCount > 0 || tSpin) {
        if (clearedCount > 0) playClear(clearedCount);

        setScore(s => {
          const newScore = s + points;
          if (newScore > highScore) setHighScore(newScore);
          const newLevel = Math.floor(newScore / 1000) + 1;
          if (newLevel > level) setLevel(newLevel);
          return newScore;
        });

        if (clearedCount > 0) {
          setLines(l => {
            const newTotal = l + clearedCount;
            if (Math.floor(newTotal / 10) > Math.floor(l / 10)) {
              setBombs(b => b + 1);
            }
            return newTotal;
          });
        }
      } else {
        playDrop();
      }

      return filteredBoard;
    });
    setActivePiece(null);
    isLastMoveRotation.current = false;
  }, [level, highScore, playClear, playDrop]);

  const useBomb = useCallback(() => {
    if (bombs <= 0 || !isGameStarted || paused || gameOver) return;
    setBombs(prev => prev - 1);
    playBomb();
    setBoard(prev => {
      const newBoard = [...prev];
      for (let i = 0; i < 4; i++) {
        newBoard.pop();
        newBoard.unshift(Array(COLS).fill(null));
      }
      return newBoard;
    });
  }, [bombs, isGameStarted, paused, gameOver, playBomb]);

  const spawnPiece = useCallback(() => {
    const piece = nextPiece;
    const spawnPos = { x: Math.floor(COLS / 2) - 1, y: 0 };
    if (checkCollision(piece.shape, spawnPos, board)) {
      setGameOver(true);
      playGameOver();
      return;
    }
    setActivePiece({ tetromino: piece, position: spawnPos });
    setNextPiece(getRandomTetromino());
    isLastMoveRotation.current = false;
  }, [nextPiece, board, checkCollision, playGameOver]);

  const move = useCallback((dir: Direction) => {
    if (!activePiece || paused || gameOver || !isGameStarted) return false;
    const newPos = {
      x: activePiece.position.x + (dir === Direction.Down ? 0 : dir),
      y: activePiece.position.y + (dir === Direction.Down ? 1 : 0)
    };
    if (!checkCollision(activePiece.tetromino.shape, newPos, board)) {
      setActivePiece(prev => prev ? { ...prev, position: newPos } : null);
      if (dir !== Direction.Down) {
        playMove();
        isLastMoveRotation.current = false;
      }
      return true;
    }
    if (dir === Direction.Down) finalizePiece(activePiece);
    return false;
  }, [activePiece, board, checkCollision, paused, gameOver, finalizePiece, isGameStarted, playMove]);

  const rotate = useCallback(() => {
    if (!activePiece || paused || gameOver || !isGameStarted) return;
    const rotatedShape = activePiece.tetromino.shape[0].map((_, index) =>
      activePiece.tetromino.shape.map(col => col[index]).reverse()
    );
    if (!checkCollision(rotatedShape, activePiece.position, board)) {
      setActivePiece(prev => prev ? { ...prev, tetromino: { ...prev.tetromino, shape: rotatedShape } } : null);
      playRotate();
      isLastMoveRotation.current = true;
    }
  }, [activePiece, board, checkCollision, paused, gameOver, isGameStarted, playRotate]);

  const hardDrop = useCallback(() => {
    if (!activePiece || paused || gameOver || !isGameStarted) return;
    let newY = activePiece.position.y;
    while (!checkCollision(activePiece.tetromino.shape, { x: activePiece.position.x, y: newY + 1 }, board)) {
      newY++;
    }
    const finalPiece = { ...activePiece, position: { ...activePiece.position, y: newY } };
    finalizePiece(finalPiece);
  }, [activePiece, board, checkCollision, paused, gameOver, isGameStarted, finalizePiece]);

  const startGame = useCallback((selectedDifficulty: Difficulty) => {
    setDifficulty(selectedDifficulty);
    setIsGameStarted(true);
    setGameOver(false);
    setPaused(false);
    setBoard(createEmptyBoard());
    setScore(0);
    setLevel(1);
    setLines(0);
    setBombs(0);
    setActivePiece(null);
    setNextPiece(getRandomTetromino());
    isLastMoveRotation.current = false;
  }, []);

  const resetGame = useCallback(() => {
    setIsGameStarted(false);
    setGameOver(false);
    setPaused(false);
    isLastMoveRotation.current = false;
  }, []);

  useEffect(() => {
    if (isGameStarted && !activePiece && !gameOver && !paused) {
      spawnPiece();
    }
  }, [activePiece, gameOver, paused, spawnPiece, isGameStarted]);

  useEffect(() => {
    if (gameOver || paused || !isGameStarted) return;
    const baseSpeed = DIFFICULTY_SPEEDS[difficulty];
    const speed = Math.max(MIN_DROP_SPEED, baseSpeed - (level - 1) * 60);
    timerRef.current = window.setInterval(() => move(Direction.Down), speed);
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [move, level, gameOver, paused, difficulty, isGameStarted]);

  return { board, activePiece, nextPiece, score, highScore, level, lines, bombs, useBomb, gameOver, paused, difficulty, isGameStarted, setPaused, move, rotate, hardDrop, resetGame, startGame };
};

export type Shape = number[][];

export interface Tetromino {
  shape: Shape;
  color: string;
  id: string;
}

export interface Position {
  x: number;
  y: number;
}

export type Board = (string | null)[][];

export enum Difficulty {
  Easy = 'Easy',
  Medium = 'Medium',
  Hard = 'Hard'
}

export interface UserProfile {
  id: string;
  name: string;
  tetrisStats: {
    bestScore: number;
    totalLines: number;
    gamesPlayed: number;
  };
  chessStats: {
    wins: number;
    losses: number;
    draws: number;
  };
  snakeStats: {
    bestScore: number;
    gamesPlayed: number;
  };
}

export enum GameType {
  None = 'None',
  Tetris = 'Tetris',
  Chess = 'Chess',
  Snake = 'Snake',
  Chat = 'Chat'
}

export interface GameState {
  board: Board;
  activePiece: ActivePiece | null;
  nextPiece: Tetromino;
  score: number;
  level: number;
  lines: number;
  gameOver: boolean;
  paused: boolean;
  difficulty: Difficulty;
  highScore: number;
  bombs: number;
}

export interface ActivePiece {
  tetromino: Tetromino;
  position: Position;
}

export enum Direction {
  Left = -1,
  Right = 1,
  Down = 0
}

import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

interface Message {
  role: 'user' | 'model';
  text: string;
  id: string;
}

interface ChatRoomProps {
  userName: string;
  onExit: () => void;
}

const ChatRoom: React.FC<ChatRoomProps> = ({ userName, onExit }) => {
  const [messages, setMessages] = useState<Message[]>([
    { role: 'model', text: `Greetings, Operator ${userName}. Neural connection established. How can I assist your gaming session today?`, id: 'init' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  const chatRef = useRef(ai.chats.create({
    model: 'gemini-3-flash-preview',
    config: {
      systemInstruction: `You are the Prime Arcade AI, a high-tech gaming assistant and strategist. 
      You speak with a professional, slightly cybernetic, and encouraging tone. 
      You know about Tetris, Chess, and Snake. 
      Refer to the user as "Operator ${userName}". 
      Keep responses relatively concise but helpful.`
    }
  }));

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isTyping) return;

    const userMsg: Message = { role: 'user', text: input.trim(), id: Date.now().toString() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    try {
      const modelMsgId = (Date.now() + 1).toString();
      let accumulatedText = "";

      setMessages(prev => [...prev, { role: 'model', text: "", id: modelMsgId }]);

      const streamResponse = await chatRef.current.sendMessageStream({ message: userMsg.text });

      for await (const chunk of streamResponse) {
        accumulatedText += chunk.text;
        setMessages(prev => prev.map(m => 
          m.id === modelMsgId ? { ...m, text: accumulatedText } : m
        ));
      }
    } catch (error) {
      console.error("Chat error:", error);
      setMessages(prev => [...prev, { 
        role: 'model', 
        text: "System Error: Neural link interrupted. Please retry communication.", 
        id: 'err-' + Date.now() 
      }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="flex flex-col h-full w-full max-w-md bg-slate-950 border border-slate-800 shadow-2xl animate-in fade-in zoom-in duration-300">
      <header className="p-4 border-b border-slate-800 flex justify-between items-center bg-black/40">
        <div className="flex flex-col">
          <h2 className="text-sm font-bold tracking-tighter text-cyan-400 uppercase font-orbitron flex items-center gap-2">
            <span className="w-2 h-2 bg-cyan-500 rounded-full animate-pulse"></span>
            AI COMMS LINK
          </h2>
          <span className="text-[8px] text-slate-500 uppercase tracking-widest">Secure Channel Active</span>
        </div>
        <button 
          onClick={onExit}
          className="px-3 py-1 border border-slate-800 text-[9px] font-bold text-slate-500 hover:text-white uppercase transition-colors"
        >
          Exit Link
        </button>
      </header>

      <div 
        ref={scrollRef}
        className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar"
      >
        {messages.map((msg) => (
          <div 
            key={msg.id} 
            className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div className={`max-w-[85%] p-3 rounded-sm text-[11px] leading-relaxed shadow-lg transition-all
              ${msg.role === 'user' 
                ? 'bg-slate-800 text-white border-l-2 border-blue-500' 
                : 'bg-black/60 text-cyan-50 border-l-2 border-cyan-500 font-medium'
              }`}
            >
              <div className="text-[7px] uppercase font-bold tracking-widest mb-1 opacity-40">
                {msg.role === 'user' ? userName : 'AI ASSISTANT'}
              </div>
              <p className="whitespace-pre-wrap">{msg.text || (msg.role === 'model' && isTyping ? '...' : '')}</p>
            </div>
          </div>
        ))}
        {isTyping && messages[messages.length-1].text === "" && (
          <div className="flex justify-start">
             <div className="bg-black/60 p-3 border-l-2 border-cyan-500 text-cyan-400 animate-pulse text-[10px]">
               Analyzing...
             </div>
          </div>
        )}
      </div>

      <form 
        onSubmit={handleSend}
        className="p-4 bg-black/60 border-t border-slate-800 flex gap-2"
      >
        <input 
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder="TYPE MESSAGE..."
          className="flex-1 bg-slate-900 border border-slate-800 px-4 py-2 text-[10px] uppercase font-bold tracking-wider text-white focus:outline-none focus:border-cyan-500 transition-colors"
        />
        <button 
          type="submit"
          disabled={isTyping}
          className={`px-4 py-2 text-[10px] font-bold uppercase tracking-widest transition-all
            ${isTyping 
              ? 'bg-slate-800 text-slate-600' 
              : 'bg-cyan-600 text-white hover:bg-cyan-500 active:scale-95 shadow-[0_0_15px_rgba(8,145,178,0.3)]'}
          `}
        >
          Send
        </button>
      </form>
    </div>
  );
};

export default ChatRoom;

import React, { useState, useEffect, useCallback } from 'react';
import { useTetris } from './hooks/useTetris';
import BoardView from './components/BoardView';
import Controls from './components/Controls';
import GameUI from './components/GameUI';
import AISuggestions from './components/AISuggestions';
import ChessGame from './components/ChessGame';
import SnakeGame from './components/SnakeGame';
import ChatRoom from './components/ChatRoom';
import { Direction, Position, Board, Difficulty, UserProfile, GameType } from './types';

const STORAGE_KEY = 'tetris_prime_profiles_v3';

const App: React.FC = () => {
  const [profiles, setProfiles] = useState<UserProfile[]>([]);
  const [activeProfile, setActiveProfile] = useState<UserProfile | null>(null);
  const [currentView, setCurrentView] = useState<'profile-selector' | 'hub' | 'tetris' | 'chess' | 'snake' | 'chat'>('profile-selector');
  const [newProfileName, setNewProfileName] = useState('');
  const [isShaking, setIsShaking] = useState(false);

  const { 
    board, activePiece, nextPiece, score, highScore, level, lines, bombs, useBomb,
    gameOver, paused, difficulty, isGameStarted, setPaused, 
    move, rotate, hardDrop, resetGame, startGame 
  } = useTetris(activeProfile);

  // Load profiles on mount
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      setProfiles(JSON.parse(saved));
    }
  }, []);

  // Persist profiles on change
  useEffect(() => {
    if (profiles.length > 0) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(profiles));
    }
  }, [profiles]);

  // Handle Tetris Game Over
  useEffect(() => {
    if (gameOver && activeProfile) {
      const updatedProfiles = profiles.map(p => {
        if (p.id === activeProfile.id) {
          return {
            ...p,
            tetrisStats: {
              bestScore: Math.max(p.tetrisStats.bestScore, score),
              totalLines: p.tetrisStats.totalLines + lines,
              gamesPlayed: p.tetrisStats.gamesPlayed + 1
            }
          };
        }
        return p;
      });
      setProfiles(updatedProfiles);
      setActiveProfile(updatedProfiles.find(p => p.id === activeProfile.id) || null);
    }
  }, [gameOver]);

  const handleUpdateChessStats = (result: 'white' | 'black' | 'draw') => {
    if (!activeProfile) return;
    const updatedProfiles = profiles.map(p => {
      if (p.id === activeProfile.id) {
        const stats = { ...p.chessStats };
        if (result === 'white') stats.wins++;
        else if (result === 'black') stats.losses++;
        else stats.draws++;
        return { ...p, chessStats: stats };
      }
      return p;
    });
    setProfiles(updatedProfiles);
    setActiveProfile(updatedProfiles.find(p => p.id === activeProfile.id) || null);
  };

  const handleSnakeGameOver = (finalScore: number) => {
    if (!activeProfile) return;
    const updatedProfiles = profiles.map(p => {
      if (p.id === activeProfile.id) {
        return {
          ...p,
          snakeStats: {
            bestScore: Math.max(p.snakeStats.bestScore, finalScore),
            gamesPlayed: p.snakeStats.gamesPlayed + 1
          }
        };
      }
      return p;
    });
    setProfiles(updatedProfiles);
    setActiveProfile(updatedProfiles.find(p => p.id === activeProfile.id) || null);
  };

  const handleBombAction = useCallback(() => {
    if (bombs > 0 && isGameStarted && !paused && !gameOver) {
      useBomb();
      setIsShaking(true);
      setTimeout(() => setIsShaking(false), 500);
    }
  }, [bombs, isGameStarted, paused, gameOver, useBomb]);

  const handleCreateProfile = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newProfileName.trim()) return;
    const newProfile: UserProfile = {
      id: Date.now().toString(),
      name: newProfileName.trim(),
      tetrisStats: { bestScore: 0, totalLines: 0, gamesPlayed: 0 },
      chessStats: { wins: 0, losses: 0, draws: 0 },
      snakeStats: { bestScore: 0, gamesPlayed: 0 }
    };
    setProfiles(prev => [...prev, newProfile]);
    setActiveProfile(newProfile);
    setNewProfileName('');
    setCurrentView('hub');
  };

  const selectProfile = (p: UserProfile) => {
    setActiveProfile(p);
    setCurrentView('hub');
  };

  const logout = () => {
    setActiveProfile(null);
    setCurrentView('profile-selector');
    resetGame();
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (currentView !== 'tetris' || gameOver || !isGameStarted) return;
      switch (e.key) {
        case 'ArrowLeft': move(Direction.Left); break;
        case 'ArrowRight': move(Direction.Right); break;
        case 'ArrowDown': move(Direction.Down); break;
        case 'ArrowUp': rotate(); break;
        case ' ': hardDrop(); break;
        case 'b': handleBombAction(); break;
        case 'p': setPaused(!paused); break;
      }
    };
