import React, { useState, useEffect, useCallback, useRef } from 'react';

interface DiamondRushProps {
  onExit: () => void;
  onGameOver: (score: number, diamonds: number) => void;
  highScore: number;
}

type Point = { x: number; y: number };

const GRID_SIZE = 12;
const INITIAL_SPEED = 250;

const DiamondRush: React.FC<DiamondRushProps> = ({ onExit, onGameOver, highScore }) => {
  const [player, setPlayer] = useState<Point>({ x: 5, y: 11 });
  const [diamonds, setDiamonds] = useState<Point[]>([]);
  const [obstacles, setObstacles] = useState<Point[]>([]);
  const [score, setScore] = useState(0);
  const [level, setLevel] = useState(1);
  const [gameOver, setGameOver] = useState(false);
  const [isReady, setIsReady] = useState(false);

  const timerRef = useRef<number | null>(null);

  const generateSpawn = useCallback((existing: Point[]) => {
    let p;
    while (true) {
      p = {
        x: Math.floor(Math.random() * GRID_SIZE),
        y: Math.floor(Math.random() * (GRID_SIZE - 2)) // Spawn in upper 80%
      };
      if (!existing.some(e => e.x === p.x && e.y === p.y) && (p.x !== player.x || p.y !== player.y)) {
        break;
      }
    }
    return p;
  }, [player]);

  const initLevel = useCallback(() => {
    const newDiamonds = Array.from({ length: 3 + level }, () => generateSpawn([]));
    const newObstacles = Array.from({ length: 5 + level * 2 }, () => generateSpawn(newDiamonds));
    setDiamonds(newDiamonds);
    setObstacles(newObstacles);
    setIsReady(true);
  }, [level, generateSpawn]);

  useEffect(() => {
    initLevel();
  }, [level]);

  const handleGameOver = () => {
    setGameOver(true);
    onGameOver(score, Math.floor(score / 50));
  };

  const movePlayer = (dx: number, dy: number) => {
    if (gameOver) return;
    setPlayer(prev => {
      const next = { x: prev.x + dx, y: prev.y + dy };

      // Boundary check
      if (next.x < 0 || next.x >= GRID_SIZE || next.y < 0 || next.y >= GRID_SIZE) return prev;

      // Obstacle check
      if (obstacles.some(o => o.x === next.x && o.y === next.y)) {
        handleGameOver();
        return prev;
      }

      // Diamond check
      if (diamonds.some(d => d.x === next.x && d.y === next.y)) {
        setScore(s => s + 50);
        setDiamonds(ds => {
          const filtered = ds.filter(d => d.x !== next.x || d.y !== next.y);
          if (filtered.length === 0) {
            setLevel(l => l + 1);
          }
          return filtered;
        });
      }

      return next;
    });
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      switch (e.key) {
        case 'ArrowUp': movePlayer(0, -1); break;
        case 'ArrowDown': movePlayer(0, 1); break;
        case 'ArrowLeft': movePlayer(-1, 0); break;
        case 'ArrowRight': movePlayer(1, 0); break;
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [gameOver, obstacles, diamonds]);

  // Falling obstacles logic (optional advanced feature)
  useEffect(() => {
    if (gameOver) return;
    const interval = Math.max(500, 2000 - level * 200);
    const id = window.setInterval(() => {
       // Randomly spawn a falling hazard or move existing ones
       // For simplicity, let's stick to the maze collection for now 
       // but add a "Sentinel" that moves.
    }, interval);
    return () => clearInterval(id);
  }, [gameOver, level]);

  return (
    <div className="flex flex-col items-center gap-4 w-full max-w-md animate-in fade-in zoom-in duration-300">
      <div className="w-full flex justify-between items-center px-2">
        <div className="flex flex-col">
          <h2 className="text-xl font-black italic tracking-tighter text-cyan-400 font-orbitron uppercase">DIAMOND RUSH</h2>
          <div className="flex gap-3">
             <span className="text-[8px] text-slate-500 font-retro uppercase">Best: {highScore}</span>
             <span className="text-[8px] text-cyan-500 font-retro uppercase tracking-widest">Score: {score}</span>
             <span className="text-[8px] text-yellow-500 font-retro uppercase tracking-widest">LVL: {level}</span>
          </div>
        </div>
        <button onClick={onExit} className="px-3 py-1 border border-slate-800 text-[10px] font-black font-orbitron uppercase text-slate-400 hover:text-white transition-all">
          EXIT
        </button>
      </div>

      <div className="relative w-full aspect-square bg-slate-950 border-4 border-slate-900 rounded-lg overflow-hidden grid shadow-2xl"
           style={{ gridTemplateColumns: `repeat(${GRID_SIZE}, 1fr)` }}>
        {Array.from({ length: GRID_SIZE * GRID_SIZE }).map((_, i) => {
          const x = i % GRID_SIZE;
          const y = Math.floor(i / GRID_SIZE);
          const isPlayer = player.x === x && player.y === y;
          const isDiamond = diamonds.some(d => d.x === x && d.y === y);
          const isObstacle = obstacles.some(o => o.x === x && o.y === y);

          return (
            <div key={i} className={`relative w-full h-full border-[0.5px] border-slate-900/20 flex items-center justify-center transition-all duration-200`}>
              {isPlayer && (
                <div className="w-4/5 h-4/5 bg-white shadow-[0_0_15px_white] rounded-sm animate-pulse z-10" />
              )}
              {isDiamond && (
                <div className="w-3/5 h-3/5 rotate-45 bg-cyan-400 shadow-[0_0_15px_rgba(34,211,238,0.8)] border border-white/40 animate-bounce" />
              )}
              {isObstacle && (
                <div className="w-full h-full bg-red-950/40 border border-red-500/30 flex items-center justify-center">
                   <div className="w-1/2 h-1/2 bg-red-500 shadow-[0_0_10px_red]" />
                </div>
              )}
            </div>
          );
        })}

        {gameOver && (
          <div className="absolute inset-0 bg-black/90 flex flex-col items-center justify-center z-50 backdrop-blur-md p-6 text-center">
            <h3 className="text-3xl font-black text-red-500 font-orbitron italic uppercase mb-2">SYSTEM BREACH</h3>
            <p className="text-[10px] text-slate-400 font-retro uppercase tracking-widest mb-8">Final Score: {score}</p>
            <button 
              onClick={() => {
                setPlayer({ x: 5, y: 11 });
                setScore(0);
                setLevel(1);
                setGameOver(false);
                initLevel();
              }}
              className="w-full py-4 bg-white text-black font-black font-orbitron uppercase italic tracking-widest hover:bg-cyan-400 transition-all"
            >
              RESTART MODULE
            </button>
          </div>
        )}
      </div>

      {/* Mobile Controls */}
      <div className="grid grid-cols-3 gap-2 w-full mt-4 max-w-[240px]">
        <div />
        <button onClick={() => movePlayer(0, -1)} className="h-14 border border-slate-800 bg-slate-900/50 flex items-center justify-center rounded-lg active:bg-cyan-500 active:text-black">
          <i className="fa-solid fa-chevron-up text-xl"></i>
        </button>
        <div />

        <button onClick={() => movePlayer(-1, 0)} className="h-14 border border-slate-800 bg-slate-900/50 flex items-center justify-center rounded-lg active:bg-cyan-500 active:text-black">
          <i className="fa-solid fa-chevron-left text-xl"></i>
        </button>
        <button onClick={() => movePlayer(0, 1)} className="h-14 border border-slate-800 bg-slate-900/50 flex items-center justify-center rounded-lg active:bg-cyan-500 active:text-black">
          <i className="fa-solid fa-chevron-down text-xl"></i>
        </button>
        <button onClick={() => movePlayer(1, 0)} className="h-14 border border-slate-800 bg-slate-900/50 flex items-center justify-center rounded-lg active:bg-cyan-500 active:text-black">
          <i className="fa-solid fa-chevron-right text-xl"></i>
        </button>
      </div>
    </div>
  );
};

export default DiamondRush;

