              </div>
            </button>
          </div>

          <footer className="pt-8 pb-4 border-t border-slate-900 flex justify-between items-center opacity-60 shrink-0">
             <div className="text-[8px] text-slate-500 font-retro uppercase">SYSTEM: V3.4.0_PRIME</div>
             <div className="text-[8px] text-green-500 font-retro uppercase animate-pulse">ALL MODULES ACTIVE</div>
          </footer>
        </div>
      </div>
