  if (currentView === 'chat') {
    return (
      <div className="h-screen bg-[#020202] flex items-center justify-center p-4 relative overflow-hidden">
        <div className="animated-grid opacity-30"></div>
        <ChatRoom 
          userName={activeProfile?.name || 'GUEST'} 
          onExit={() => setCurrentView('hub')} 
        />
      </div>
    );
  }

  // Tetris View
  return (
    <div className={`h-screen bg-[#020202] text-slate-200 flex flex-col items-center justify-between py-2 px-3 overflow-hidden font-sans relative ${isShaking ? 'animate-shake' : ''}`}>
