    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';

interface DiamondRushProps {
  onExit: () => void;
  onGameOver: (score: number, diamonds: number) => void;
  highScore: number;
}

enum TileType {
  Empty = 0,
  Dirt = 1,
  Rock = 2,
  Diamond = 3,
  Wall = 4,
  Exit = 5,
  Player = 6
}

const GRID_COLS = 12;
const GRID_ROWS = 15;

const DiamondRush: React.FC<DiamondRushProps> = ({ onExit, onGameOver, highScore }) => {
  const [grid, setGrid] = useState<TileType[][]>([]);
  const [playerPos, setPlayerPos] = useState({ x: 1, y: 1 });
  const [score, setScore] = useState(0);
  const [diamondsCollected, setDiamondsCollected] = useState(0);
  const [requiredDiamonds, setRequiredDiamonds] = useState(5);
  const [isGameOver, setIsGameOver] = useState(false);
  const [isVictory, setIsVictory] = useState(false);
  const [level, setLevel] = useState(1);
  const [shake, setShake] = useState(false);

  const physicsTimerRef = useRef<number | null>(null);

  // Initialize Level
  const initLevel = useCallback((lvl: number) => {
    const newGrid: TileType[][] = [];
    const quota = 4 + lvl;
    setRequiredDiamonds(quota);
    setDiamondsCollected(0);
    setIsGameOver(false);
    setIsVictory(false);

    for (let y = 0; y < GRID_ROWS; y++) {
      const row: TileType[] = [];
      for (let x = 0; x < GRID_COLS; x++) {
        if (y === 0 || y === GRID_ROWS - 1 || x === 0 || x === GRID_COLS - 1) {
          row.push(TileType.Wall);
        } else if (x === 1 && y === 1) {
          row.push(TileType.Empty); // Player start
        } else {
          const rand = Math.random();
          if (rand < 0.15) row.push(TileType.Rock);
          else if (rand < 0.22) row.push(TileType.Diamond);
          else if (rand < 0.8) row.push(TileType.Dirt);
          else row.push(TileType.Empty);
        }
      }
      newGrid.push(row);
    }
    setGrid(newGrid);
    setPlayerPos({ x: 1, y: 1 });
  }, []);

  useEffect(() => {
    initLevel(level);
  }, [level, initLevel]);

  // Physics Engine: Falling Rocks and Diamonds
  const updatePhysics = useCallback(() => {
    setGrid(prevGrid => {
      const newGrid = prevGrid.map(row => [...row]);
      let changed = false;

      // Iterate from bottom up to handle falling correctly
      for (let y = GRID_ROWS - 2; y >= 0; y--) {
        for (let x = 1; x < GRID_COLS - 1; x++) {
          const current = newGrid[y][x];

          if (current === TileType.Rock || current === TileType.Diamond) {
            const below = newGrid[y + 1][x];
            const left = newGrid[y][x - 1];
            const right = newGrid[y][x + 1];
            const belowLeft = newGrid[y + 1][x - 1];
            const belowRight = newGrid[y + 1][x + 1];

            // 1. Straight Fall
            if (below === TileType.Empty) {
              newGrid[y + 1][x] = current;
              newGrid[y][x] = TileType.Empty;
              changed = true;

              // Check if crushed player
              if (playerPos.x === x && playerPos.y === y + 1) {
                setIsGameOver(true);
              }
            } 
            // 2. Sliding off rounded objects (Rocks/Diamonds)
            else if (below === TileType.Rock || below === TileType.Diamond || below === TileType.Wall) {
              // Try slide left
              if (left === TileType.Empty && belowLeft === TileType.Empty) {
                newGrid[y + 1][x - 1] = current;
                newGrid[y][x] = TileType.Empty;
                changed = true;
              }
              // Try slide right
              else if (right === TileType.Empty && belowRight === TileType.Empty) {
                newGrid[y + 1][x + 1] = current;
                newGrid[y][x] = TileType.Empty;
                changed = true;
              }
            }
          }
        }
      }

      if (changed) setShake(true);
      else setShake(false);

      return newGrid;
    });
  }, [playerPos]);

  useEffect(() => {
    physicsTimerRef.current = window.setInterval(updatePhysics, 150);
    return () => { if (physicsTimerRef.current) clearInterval(physicsTimerRef.current); };
  }, [updatePhysics]);

  const movePlayer = (dx: number, dy: number) => {
    if (isGameOver || isVictory) return;

    const newX = playerPos.x + dx;
    const newY = playerPos.y + dy;

    if (newX < 0 || newX >= GRID_COLS || newY < 0 || newY >= GRID_ROWS) return;

    const targetTile = grid[newY][newX];

    // Interaction Rules
    if (targetTile === TileType.Wall) return;

    // Push Rock horizontally
    if (targetTile === TileType.Rock && dy === 0) {
      const behindRockX = newX + dx;
      if (grid[newY][behindRockX] === TileType.Empty) {
        const nextGrid = [...grid];
        nextGrid[newY][behindRockX] = TileType.Rock;
        nextGrid[newY][newX] = TileType.Empty;
        setGrid(nextGrid);
        setPlayerPos({ x: newX, y: newY });
      }
      return;
    }

    if (targetTile === TileType.Rock) return; // Cannot push vertically

    // Collect Diamond
    if (targetTile === TileType.Diamond) {
      setScore(s => s + 100);
      setDiamondsCollected(d => {
        const next = d + 1;
        if (next === requiredDiamonds) {
           // Spawn exit portal somewhere random
           setGrid(g => {
             const newG = g.map(r => [...r]);
             newG[GRID_ROWS - 2][GRID_COLS - 2] = TileType.Exit;
             return newG;
           });
        }
        return next;
      });
    }

    // Exit Room
    if (targetTile === TileType.Exit) {
      setIsVictory(true);
      return;
    }

    // Move (Empty or Dirt)
    setPlayerPos({ x: newX, y: newY });
    setGrid(prev => {
      const next = prev.map(row => [...row]);
      next[newY][newX] = TileType.Empty;
      return next;
    });
  };

  useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
      if (e.key === 'ArrowUp') movePlayer(0, -1);
      if (e.key === 'ArrowDown') movePlayer(0, 1);
      if (e.key === 'ArrowLeft') movePlayer(-1, 0);
      if (e.key === 'ArrowRight') movePlayer(1, 0);
    };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, [playerPos, grid, isGameOver, isVictory]);

  const progressLevel = () => {
    setLevel(l => l + 1);
  };

  return (
    <div className={`flex flex-col items-center gap-4 w-full max-w-md animate-in fade-in zoom-in duration-300 ${shake ? 'animate-shake' : ''}`}>
      <div className="w-full flex justify-between items-center px-2">
        <div className="flex flex-col">
          <h2 className="text-xl font-black italic tracking-tighter text-cyan-400 font-orbitron uppercase">DIAMOND RUSH</h2>
          <div className="flex gap-3">
             <span className="text-[8px] text-slate-500 font-retro uppercase">Best: {highScore}</span>
             <span className="text-[8px] text-cyan-500 font-retro uppercase tracking-widest">Score: {score}</span>
             <span className="text-[8px] text-yellow-500 font-retro uppercase tracking-widest">Gems: {diamondsCollected}/{requiredDiamonds}</span>
          </div>
        </div>
        <button onClick={onExit} className="px-3 py-1 border border-slate-800 text-[10px] font-black font-orbitron uppercase text-slate-400 hover:text-white transition-all">
          EXIT
        </button>
      </div>

      <div className="relative w-full aspect-[12/15] bg-slate-950 border-4 border-slate-900 rounded-lg overflow-hidden grid shadow-2xl"
           style={{ gridTemplateColumns: `repeat(${GRID_COLS}, 1fr)` }}>
        {grid.map((row, y) => row.map((tile, x) => {
          const isPlayer = playerPos.x === x && playerPos.y === y;

          return (
            <div key={`${x}-${y}`} className={`relative w-full h-full flex items-center justify-center`}>
              {/* Tile Backgrounds */}
              {tile === TileType.Dirt && (
                <div className="w-full h-full bg-[#3d2b1f] border-[0.5px] border-slate-900/50 flex items-center justify-center">
                   <div className="w-full h-full opacity-10 bg-[radial-gradient(circle,white_1px,transparent_1px)] bg-[size:4px_4px]"></div>
                </div>
              )}
              {tile === TileType.Wall && <div className="w-full h-full bg-slate-800 border-2 border-slate-700 shadow-inner" />}
              {tile === TileType.Rock && (
                <div className="w-4/5 h-4/5 bg-slate-500 rounded-full border-2 border-slate-400 shadow-xl flex items-center justify-center">
                   <div className="w-1/2 h-1/2 bg-slate-600 rounded-full opacity-50 -mt-1 ml-1" />
                </div>
              )}
              {tile === TileType.Diamond && (
                <div className="w-3/5 h-3/5 rotate-45 bg-cyan-400 shadow-[0_0_15px_rgba(34,211,238,0.8)] border border-white/40 animate-pulse" />
              )}
              {tile === TileType.Exit && (
                <div className="w-4/5 h-4/5 bg-purple-600 border-2 border-white rounded-full animate-ping" />
              )}

              {/* Player Overlay */}
              {isPlayer && (
                <div className="absolute inset-0 flex items-center justify-center z-10">
                   <div className="w-4/5 h-4/5 bg-white shadow-[0_0_20px_white] rounded-sm flex items-center justify-center">
                      <div className="w-1/2 h-1/2 bg-cyan-500 rounded-full animate-pulse" />
                   </div>
                </div>
              )}
            </div>
          );
        }))}

        {(isGameOver || isVictory) && (
          <div className="absolute inset-0 bg-black/90 flex flex-col items-center justify-center z-50 backdrop-blur-md p-6 text-center">
            {isGameOver ? (
              <>
                <h3 className="text-3xl font-black text-red-500 font-orbitron italic uppercase mb-2">CRUSHED</h3>
                <p className="text-[10px] text-slate-400 font-retro uppercase tracking-widest mb-8">Mission Failed</p>
                <button 
                  onClick={() => initLevel(level)}
                  className="w-full py-4 bg-white text-black font-black font-orbitron uppercase italic tracking-widest hover:bg-cyan-400 transition-all"
                >
                  RESTART MODULE
                </button>
              </>
            ) : (
              <>
                <h3 className="text-3xl font-black text-green-500 font-orbitron italic uppercase mb-2">QUOTA MET</h3>
                <p className="text-[10px] text-slate-400 font-retro uppercase tracking-widest mb-8">Advancing to Next Sector...</p>
                <button 
                  onClick={progressLevel}
                  className="w-full py-4 bg-cyan-500 text-white font-black font-orbitron uppercase italic tracking-widest hover:bg-cyan-400 transition-all"
                >
                  NEXT LEVEL
                </button>
              </>
            )}
          </div>
        )}
      </div>

      {/* Mobile Controls */}
      <div className="grid grid-cols-3 gap-2 w-full mt-4 max-w-[240px] z-20">
        <div />
        <button onClick={() => movePlayer(0, -1)} className="h-14 border border-slate-800 bg-slate-900/50 flex items-center justify-center rounded-lg active:bg-cyan-500 active:text-black">
          <i className="fa-solid fa-chevron-up text-xl"></i>
        </button>
        <div />

        <button onClick={() => movePlayer(-1, 0)} className="h-14 border border-slate-800 bg-slate-900/50 flex items-center justify-center rounded-lg active:bg-cyan-500 active:text-black">
          <i className="fa-solid fa-chevron-left text-xl"></i>
        </button>
        <button onClick={() => movePlayer(0, 1)} className="h-14 border border-slate-800 bg-slate-900/50 flex items-center justify-center rounded-lg active:bg-cyan-500 active:text-black">
          <i className="fa-solid fa-chevron-down text-xl"></i>
        </button>
        <button onClick={() => movePlayer(1, 0)} className="h-14 border border-slate-800 bg-slate-900/50 flex items-center justify-center rounded-lg active:bg-cyan-500 active:text-black">
          <i className="fa-solid fa-chevron-right text-xl"></i>
        </button>
      </div>
    </div>
  );
};

