import { useState, useEffect, useCallback, useRef } from 'react';
import { 
  Board, 
  Position, 
  Tetromino, 
  Direction, 
  Shape,
  Difficulty,
  UserProfile
} from '../types';
import { 
  COLS, 
  ROWS, 
  getRandomTetromino, 
  MIN_DROP_SPEED 
} from '../constants';
import { useSound } from './useSound';

const createEmptyBoard = (): Board => 
  Array.from({ length: ROWS }, () => Array(COLS).fill(null));

const DIFFICULTY_SPEEDS: Record<Difficulty, number> = {
  [Difficulty.Easy]: 1000,
  [Difficulty.Medium]: 700,
  [Difficulty.Hard]: 400,
};

const SCORING = [0, 100, 300, 500, 1200];
const T_SPIN_BONUS = [400, 800, 1200, 1600]; // Bonus for 0, 1, 2, 3 lines cleared with T-Spin

export const useTetris = (activeProfile: UserProfile | null) => {
  const { playMove, playRotate, playClear, playDrop, playGameOver, playBomb } = useSound();
  const [board, setBoard] = useState<Board>(createEmptyBoard());
  const [activePiece, setActivePiece] = useState<{ tetromino: Tetromino; position: Position } | null>(null);
  const [nextPiece, setNextPiece] = useState<Tetromino>(getRandomTetromino());
  const [score, setScore] = useState(0);
  const [highScore, setHighScore] = useState(0);
  const [level, setLevel] = useState(1);
  const [lines, setLines] = useState(0);
  const [bombs, setBombs] = useState(0);
  const [gameOver, setGameOver] = useState(false);
  const [paused, setPaused] = useState(false);
  const [difficulty, setDifficulty] = useState<Difficulty>(Difficulty.Medium);
  const [isGameStarted, setIsGameStarted] = useState(false);
  const [hasSave, setHasSave] = useState(false);

  const timerRef = useRef<number | null>(null);
  const isLastMoveRotation = useRef(false);

  const getSaveKey = useCallback(() => {
    return activeProfile ? `tetris_save_${activeProfile.id}` : null;
  }, [activeProfile]);

  // Check for existing save on mount or profile change
  useEffect(() => {
    const key = getSaveKey();
    if (key) {
      const saved = localStorage.getItem(key);
      setHasSave(!!saved);
    } else {
      setHasSave(false);
    }
  }, [activeProfile, getSaveKey]);

  useEffect(() => {
    if (activeProfile) {
      setHighScore(activeProfile.tetrisStats.bestScore);
    }
  }, [activeProfile]);

  // Auto-save effect
  useEffect(() => {
    const key = getSaveKey();
    if (key && isGameStarted && !gameOver) {
      const state = {
        board,
        activePiece,
        nextPiece,
        score,
        level,
        lines,
        bombs,
        difficulty,
        isGameStarted
      };
      localStorage.setItem(key, JSON.stringify(state));
      setHasSave(true);
    }
  }, [board, activePiece, nextPiece, score, level, lines, bombs, difficulty, isGameStarted, gameOver, getSaveKey]);

  const checkCollision = useCallback((shape: Shape, pos: Position, currentBoard: Board): boolean => {
    for (let y = 0; y < shape.length; y++) {
      for (let x = 0; x < shape[y].length; x++) {
        if (shape[y][x] !== 0) {
          const newX = pos.x + x;
          const newY = pos.y + y;
          if (newX < 0 || newX >= COLS || newY >= ROWS || (newY >= 0 && currentBoard[newY][newX] !== null)) {
            return true;
          }
        }
      }
    }
    return false;
  }, []);

  const isTSpinMove = (piece: { tetromino: Tetromino; position: Position }, currentBoard: Board): boolean => {
    if (piece.tetromino.id !== 'T' || !isLastMoveRotation.current) return false;

    const corners = [
      { x: 0, y: 0 },
      { x: 2, y: 0 },
      { x: 0, y: 2 },
      { x: 2, y: 2 }
    ];

    let occupiedCorners = 0;
    for (const corner of corners) {
      const boardX = piece.position.x + corner.x;
      const boardY = piece.position.y + corner.y;

      if (boardX < 0 || boardX >= COLS || boardY >= ROWS || (boardY >= 0 && currentBoard[boardY][boardX] !== null)) {
        occupiedCorners++;
      }
    }

    return occupiedCorners >= 3;
  };

  const finalizePiece = useCallback((pieceToLock: { tetromino: Tetromino; position: Position }) => {
    setBoard(prevBoard => {
      const newBoard = prevBoard.map(row => [...row]);
      pieceToLock.tetromino.shape.forEach((row, y) => {
        row.forEach((value, x) => {
          if (value !== 0) {
            const boardY = pieceToLock.position.y + y;
            const boardX = pieceToLock.position.x + x;
            if (boardY >= 0 && boardY < ROWS && boardX >= 0 && boardX < COLS) {
              newBoard[boardY][boardX] = pieceToLock.tetromino.color;
            }
          }
        });
      });

      const tSpin = isTSpinMove(pieceToLock, prevBoard);
      let clearedCount = 0;
      const filteredBoard = newBoard.filter(row => {
        const isFull = row.every(cell => cell !== null);
        if (isFull) clearedCount++;
        return !isFull;
      });

      while (filteredBoard.length < ROWS) filteredBoard.unshift(Array(COLS).fill(null));

      let points = SCORING[clearedCount] * level;
      if (tSpin) {
        points += T_SPIN_BONUS[Math.min(clearedCount, 3)] * level;
      }

      if (clearedCount > 0 || tSpin) {
        if (clearedCount > 0) playClear(clearedCount);

        setScore(s => {
          const newScore = s + points;
          if (newScore > highScore) setHighScore(newScore);
          const newLevel = Math.floor(newScore / 1000) + 1;
          if (newLevel > level) setLevel(newLevel);
          return newScore;
        });

        if (clearedCount > 0) {
          setLines(l => {
            const newTotal = l + clearedCount;
            if (Math.floor(newTotal / 10) > Math.floor(l / 10)) {
              setBombs(b => b + 1);
            }
            return newTotal;
          });
        }
      } else {
        playDrop();
      }

      return filteredBoard;
    });
    setActivePiece(null);
    isLastMoveRotation.current = false;
  }, [level, highScore, playClear, playDrop]);

  const useBomb = useCallback(() => {
    if (bombs <= 0 || !isGameStarted || paused || gameOver) return;
    setBombs(prev => prev - 1);
    playBomb();
    setBoard(prev => {
      const newBoard = [...prev];
      for (let i = 0; i < 4; i++) {
        newBoard.pop();
        newBoard.unshift(Array(COLS).fill(null));
      }
      return newBoard;
    });
  }, [bombs, isGameStarted, paused, gameOver, playBomb]);

  const spawnPiece = useCallback(() => {
    const piece = nextPiece;
    const spawnPos = { x: Math.floor(COLS / 2) - 1, y: 0 };
    if (checkCollision(piece.shape, spawnPos, board)) {
      setGameOver(true);
      playGameOver();
      const key = getSaveKey();
      if (key) localStorage.removeItem(key);
      setHasSave(false);
      return;
    }
    setActivePiece({ tetromino: piece, position: spawnPos });
    setNextPiece(getRandomTetromino());
    isLastMoveRotation.current = false;
  }, [nextPiece, board, checkCollision, playGameOver, getSaveKey]);

  const move = useCallback((dir: Direction) => {
    if (!activePiece || paused || gameOver || !isGameStarted) return false;
    const newPos = {
      x: activePiece.position.x + (dir === Direction.Down ? 0 : dir),
      y: activePiece.position.y + (dir === Direction.Down ? 1 : 0)
    };
    if (!checkCollision(activePiece.tetromino.shape, newPos, board)) {
      setActivePiece(prev => prev ? { ...prev, position: newPos } : null);
      if (dir !== Direction.Down) {
        playMove();
        isLastMoveRotation.current = false;
      }
      return true;
    }
    if (dir === Direction.Down) finalizePiece(activePiece);
    return false;
  }, [activePiece, board, checkCollision, paused, gameOver, finalizePiece, isGameStarted, playMove]);

  const rotate = useCallback(() => {
    if (!activePiece || paused || gameOver || !isGameStarted) return;
    const rotatedShape = activePiece.tetromino.shape[0].map((_, index) =>
      activePiece.tetromino.shape.map(col => col[index]).reverse()
    );
    if (!checkCollision(rotatedShape, activePiece.position, board)) {
      setActivePiece(prev => prev ? { ...prev, tetromino: { ...prev.tetromino, shape: rotatedShape } } : null);
      playRotate();
      isLastMoveRotation.current = true;
    }
  }, [activePiece, board, checkCollision, paused, gameOver, isGameStarted, playRotate]);

  const hardDrop = useCallback(() => {
    if (!activePiece || paused || gameOver || !isGameStarted) return;
    let newY = activePiece.position.y;
    while (!checkCollision(activePiece.tetromino.shape, { x: activePiece.position.x, y: newY + 1 }, board)) {
      newY++;
    }
    const finalPiece = { ...activePiece, position: { ...activePiece.position, y: newY } };
    finalizePiece(finalPiece);
  }, [activePiece, board, checkCollision, paused, gameOver, isGameStarted, finalizePiece]);

  const startGame = useCallback((selectedDifficulty: Difficulty) => {
    setDifficulty(selectedDifficulty);
    setIsGameStarted(true);
    setGameOver(false);
    setPaused(false);
    setBoard(createEmptyBoard());
    setScore(0);
    setLevel(1);
    setLines(0);
    setBombs(0);
    setActivePiece(null);
    setNextPiece(getRandomTetromino());
    isLastMoveRotation.current = false;

    // Clear save if starting fresh
    const key = getSaveKey();
    if (key) localStorage.removeItem(key);
    setHasSave(false);
  }, [getSaveKey]);

  const resumeGame = useCallback(() => {
    const key = getSaveKey();
    if (!key) return;
    const saved = localStorage.getItem(key);
    if (saved) {
      const state = JSON.parse(saved);
      setBoard(state.board);
      setActivePiece(state.activePiece);
      setNextPiece(state.nextPiece);
      setScore(state.score);
      setLevel(state.level);
      setLines(state.lines);
      setBombs(state.bombs);
      setDifficulty(state.difficulty);
      setIsGameStarted(true);
      setGameOver(false);
      setPaused(false);
    }
  }, [getSaveKey]);

  const resetGame = useCallback(() => {
    setIsGameStarted(false);
    setGameOver(false);
    setPaused(false);
    isLastMoveRotation.current = false;
  }, []);

  useEffect(() => {
    if (isGameStarted && !activePiece && !gameOver && !paused) {
      spawnPiece();
    }
  }, [activePiece, gameOver, paused, spawnPiece, isGameStarted]);

  useEffect(() => {
    if (gameOver || paused || !isGameStarted) return;
    const baseSpeed = DIFFICULTY_SPEEDS[difficulty];
    const speed = Math.max(MIN_DROP_SPEED, baseSpeed - (level - 1) * 60);
    timerRef.current = window.setInterval(() => move(Direction.Down), speed);
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [move, level, gameOver, paused, difficulty, isGameStarted]);

  return { 
    board, activePiece, nextPiece, score, highScore, level, lines, bombs, useBomb, 
    gameOver, paused, difficulty, isGameStarted, setPaused, move, rotate, 
    hardDrop, resetGame, startGame, resumeGame, hasSave 
  };
};

import React, { useState, useEffect, useCallback } from 'react';
import { useTetris } from './hooks/useTetris';
import BoardView from './components/BoardView';
import Controls from './components/Controls';
import GameUI from './components/GameUI';
import AISuggestions from './components/AISuggestions';
import ChessGame from './components/ChessGame';
import SnakeGame from './components/SnakeGame';
import ChatRoom from './components/ChatRoom';
import DiamondRush from './components/DiamondRush';
import { Direction, Position, Board, Difficulty, UserProfile, GameType } from './types';

const STORAGE_KEY = 'tetris_prime_profiles_v3';

const App: React.FC = () => {
  const [profiles, setProfiles] = useState<UserProfile[]>([]);
  const [activeProfile, setActiveProfile] = useState<UserProfile | null>(null);
  const [currentView, setCurrentView] = useState<'profile-selector' | 'hub' | 'tetris' | 'chess' | 'snake' | 'chat' | 'diamond-rush'>('profile-selector');
  const [newProfileName, setNewProfileName] = useState('');
  const [isShaking, setIsShaking] = useState(false);

  const { 
    board, activePiece, nextPiece, score, highScore, level, lines, bombs, useBomb,
    gameOver, paused, difficulty, isGameStarted, setPaused, 
    move, rotate, hardDrop, resetGame, startGame, resumeGame, hasSave 
  } = useTetris(activeProfile);

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      setProfiles(JSON.parse(saved));
    }
  }, []);

  useEffect(() => {
    if (profiles.length > 0) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(profiles));
    }
  }, [profiles]);

  useEffect(() => {
    if (gameOver && activeProfile) {
      const updatedProfiles = profiles.map(p => {
        if (p.id === activeProfile.id) {
          return {
            ...p,
            tetrisStats: {
              bestScore: Math.max(p.tetrisStats.bestScore, score),
              totalLines: p.tetrisStats.totalLines + lines,
              gamesPlayed: p.tetrisStats.gamesPlayed + 1
            }
          };
        }
        return p;
      });
      setProfiles(updatedProfiles);
      setActiveProfile(updatedProfiles.find(p => p.id === activeProfile.id) || null);
    }
  }, [gameOver]);

  const handleUpdateChessStats = (result: 'white' | 'black' | 'draw') => {
    if (!activeProfile) return;
    const updatedProfiles = profiles.map(p => {
      if (p.id === activeProfile.id) {
        const stats = { ...p.chessStats };
        if (result === 'white') stats.wins++;
        else if (result === 'black') stats.losses++;
        else stats.draws++;
        return { ...p, chessStats: stats };
      }
      return p;
    });
    setProfiles(updatedProfiles);
    setActiveProfile(updatedProfiles.find(p => p.id === activeProfile.id) || null);
  };

  const handleSnakeGameOver = (finalScore: number) => {
    if (!activeProfile) return;
    const updatedProfiles = profiles.map(p => {
      if (p.id === activeProfile.id) {
        return {
          ...p,
          snakeStats: {
            bestScore: Math.max(p.snakeStats.bestScore, finalScore),
            gamesPlayed: p.snakeStats.gamesPlayed + 1
          }
        };
      }
      return p;
    });
    setProfiles(updatedProfiles);
    setActiveProfile(updatedProfiles.find(p => p.id === activeProfile.id) || null);
  };

  const handleDiamondRushGameOver = (finalScore: number, finalDiamonds: number) => {
    if (!activeProfile) return;
    const updatedProfiles = profiles.map(p => {
      if (p.id === activeProfile.id) {
        return {
          ...p,
          diamondRushStats: {
            bestScore: Math.max(p.diamondRushStats?.bestScore || 0, finalScore),
            totalDiamonds: (p.diamondRushStats?.totalDiamonds || 0) + finalDiamonds,
            gamesPlayed: (p.diamondRushStats?.gamesPlayed || 0) + 1
          }
        };
      }
      return p;
    });
    setProfiles(updatedProfiles);
    setActiveProfile(updatedProfiles.find(p => p.id === activeProfile.id) || null);
  };

  const handleBombAction = useCallback(() => {
    if (bombs > 0 && isGameStarted && !paused && !gameOver) {
      useBomb();
      setIsShaking(true);
      setTimeout(() => setIsShaking(false), 500);
    }
  }, [bombs, isGameStarted, paused, gameOver, useBomb]);

  const handleCreateProfile = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newProfileName.trim()) return;
    const newProfile: UserProfile = {
      id: Date.now().toString(),
      name: newProfileName.trim(),
      tetrisStats: { bestScore: 0, totalLines: 0, gamesPlayed: 0 },
      chessStats: { wins: 0, losses: 0, draws: 0 },
      snakeStats: { bestScore: 0, gamesPlayed: 0 },
      diamondRushStats: { bestScore: 0, totalDiamonds: 0, gamesPlayed: 0 }
    };
    setProfiles(prev => [...prev, newProfile]);
    setActiveProfile(newProfile);
    setNewProfileName('');
    setCurrentView('hub');
  };

  const selectProfile = (p: UserProfile) => {
    setActiveProfile(p);
    setCurrentView('hub');
  };

  const logout = () => {
    setActiveProfile(null);
    setCurrentView('profile-selector');
    resetGame();
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (currentView !== 'tetris' || gameOver || !isGameStarted) return;
      switch (e.key) {
        case 'ArrowLeft': move(Direction.Left); break;
        case 'ArrowRight': move(Direction.Right); break;
        case 'ArrowDown': move(Direction.Down); break;
        case 'ArrowUp': rotate(); break;
        case ' ': hardDrop(); break;
        case 'b': handleBombAction(); break;
        case 'p': setPaused(!paused); break;
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [move, rotate, hardDrop, handleBombAction, paused, setPaused, gameOver, isGameStarted, currentView]);

  const checkCollisionHelper = (shape: number[][], pos: Position, b: Board) => {
    for (let y = 0; y < shape.length; y++) {
      for (let x = 0; x < shape[y].length; x++) {
        if (shape[y][x] !== 0) {
          const newX = pos.x + x;
          const newY = pos.y + y;
          if (newX < 0 || newX >= 10 || newY >= 20 || (newY >= 0 && b[newY][newX] !== null)) return true;
        }
      }
    }
    return false;
  };

  // Profile Selector
  if (currentView === 'profile-selector') {
    return (
      <div className="h-screen bg-[#020202] text-slate-200 flex flex-col items-center justify-center p-6 relative overflow-hidden">
        <div className="animated-grid"></div>

        <div className="w-full max-md space-y-10 z-10">
          <div className="text-center space-y-4">
            <h1 className="text-5xl font-black tracking-tighter text-transparent bg-clip-text bg-gradient-to-b from-white to-cyan-500 font-orbitron italic">PRIME ARCADE</h1>
            <div className="flex items-center justify-center gap-4">
               <div className="h-[1px] flex-1 bg-gradient-to-r from-transparent to-cyan-500"></div>
               <p className="text-[10px] text-cyan-400 font-retro tracking-widest uppercase">System Initialization</p>
               <div className="h-[1px] flex-1 bg-gradient-to-l from-transparent to-cyan-500"></div>
            </div>
          </div>

          <div className="bg-slate-900/40 backdrop-blur-md border border-cyan-500/20 p-6 rounded-lg shadow-2xl">
            <h2 className="text-[11px] font-bold text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2">
              <i className="fa-solid fa-users-gear text-cyan-500"></i> Active Operators
            </h2>

            <div className="max-h-64 overflow-y-auto space-y-3 custom-scrollbar pr-1">
              {profiles.map(p => (
                <button
                  key={p.id}
                  onClick={() => selectProfile(p)}
                  className="w-full p-4 bg-black/40 border border-slate-800 hover:border-cyan-400/60 hover:bg-cyan-500/10 group transition-all flex items-center justify-between"
                >
                  <div className="text-left">
                    <div className="text-base font-black group-hover:text-cyan-400 font-orbitron uppercase">{p.name}</div>
                    <div className="text-[9px] text-slate-500 uppercase tracking-widest mt-1">
                      EXP: {p.tetrisStats.gamesPlayed + p.chessStats.wins + p.snakeStats.gamesPlayed + (p.diamondRushStats?.gamesPlayed || 0)} Units
                    </div>
                  </div>
                  <i className="fa-solid fa-play text-[12px] text-slate-700 group-hover:text-cyan-400 animate-pulse"></i>
                </button>
              ))}
              {profiles.length === 0 && (
                <div className="text-center py-10 border border-dashed border-slate-800 rounded text-[10px] text-slate-600 font-retro">
                  NO USERS DETECTED
                </div>
              )}
            </div>

            <form onSubmit={handleCreateProfile} className="mt-8 pt-6 border-t border-slate-800 space-y-4">
              <h2 className="text-[11px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2">
                <i className="fa-solid fa-plus text-cyan-500"></i> Register New Pilot
              </h2>
              <div className="flex gap-2">
                <input
                  type="text"
                  placeholder="INPUT CALLSIGN"
                  value={newProfileName}
                  onChange={(e) => setNewProfileName(e.target.value.toUpperCase())}
                  maxLength={12}
                  className="flex-1 bg-black/60 border border-slate-800 px-4 py-3 text-sm font-orbitron font-bold tracking-widest focus:border-cyan-500 focus:outline-none placeholder:text-slate-700 text-cyan-400"
                />
                <button type="submit" className="bg-cyan-600 text-white px-6 py-3 text-xs font-black uppercase tracking-widest hover:bg-cyan-500 active:scale-95 shadow-[0_0_20px_rgba(8,145,178,0.4)]">
                  LINK
                </button>
              </div>
            </form>
          </div>
        </div>
      </div>
    );
  }

  // Hub Screen
  if (currentView === 'hub') {
    return (
      <div className="h-screen bg-[#020202] text-slate-200 flex flex-col items-center justify-start p-6 relative overflow-hidden">
        <div className="animated-grid"></div>

        <div className="w-full max-w-lg space-y-8 z-10 pt-4 overflow-y-auto custom-scrollbar">
          <header className="flex justify-between items-center bg-slate-900/40 backdrop-blur-md p-4 border-l-4 border-cyan-500 rounded-r-lg shadow-xl shrink-0">
            <div className="space-y-1">
              <h1 className="text-2xl font-black italic tracking-tighter text-white font-orbitron">COMMAND CENTER</h1>
              <div className="flex items-center gap-3">
                <div className="flex gap-1">
                  <span className="w-2 h-2 bg-green-500 rounded-full animate-ping"></span>
                  <span className="w-2 h-2 bg-green-500 rounded-full"></span>
                </div>
                <span className="text-[10px] text-cyan-400 font-retro uppercase">USER: {activeProfile?.name}</span>
              </div>
            </div>
            <button onClick={logout} className="text-[10px] font-black text-slate-500 hover:text-red-500 font-orbitron uppercase tracking-widest px-4 py-2 border border-slate-800 hover:border-red-500/40 transition-all">TERMINATE</button>
          </header>

          <div className="grid grid-cols-2 gap-4 pb-10">
            {/* Tetris Card */}
            <button 
              onClick={() => setCurrentView('tetris')}
              className="group relative overflow-hidden aspect-square border border-slate-800 hover:neon-border-cyan transition-all flex flex-col p-6 bg-slate-950/80 hover:bg-cyan-500/5 rounded-xl"
            >
              <div className="absolute top-4 right-4 text-[8px] font-retro text-cyan-500/40">THREAT: HIGH</div>
              <i className="fa-solid fa-shapes text-5xl mb-auto text-cyan-500/20 group-hover:text-cyan-500 transition-all group-hover:scale-110"></i>
              <div className="text-left">
                <h3 className="text-xl font-black tracking-tighter text-white font-orbitron uppercase italic">TETRIS PRIME</h3>
                <div className="mt-2 text-[9px] font-bold text-cyan-400 font-retro">BEST: {activeProfile?.tetrisStats.bestScore}</div>
              </div>
            </button>

            {/* Chess Card */}
            <button 
              onClick={() => setCurrentView('chess')}
              className="group relative overflow-hidden aspect-square border border-slate-800 hover:neon-border-blue transition-all flex flex-col p-6 bg-slate-950/80 hover:bg-blue-500/5 rounded-xl"
            >
              <div className="absolute top-4 right-4 text-[8px] font-retro text-blue-500/40">THREAT: EXTREME</div>
              <i className="fa-solid fa-chess-knight text-5xl mb-auto text-blue-500/20 group-hover:text-blue-500 transition-all group-hover:scale-110"></i>
              <div className="text-left">
                <h3 className="text-xl font-black tracking-tighter text-white font-orbitron uppercase italic">CHESS PRIME</h3>
                <div className="mt-2 text-[9px] font-bold text-blue-400 font-retro">WINS: {activeProfile?.chessStats.wins}</div>
              </div>
            </button>

            {/* Snake Card */}
            <button 
              onClick={() => setCurrentView('snake')}
              className="group relative overflow-hidden aspect-square border border-slate-800 hover:neon-border-green transition-all flex flex-col p-6 bg-slate-950/80 hover:bg-green-500/5 rounded-xl"
            >
               <div className="absolute top-4 right-4 text-[8px] font-retro text-green-500/40">THREAT: MED</div>
              <i className="fa-solid fa-worm text-5xl mb-auto text-green-500/20 group-hover:text-green-500 transition-all group-hover:scale-110"></i>
              <div className="text-left">
                <h3 className="text-xl font-black tracking-tighter text-white font-orbitron uppercase italic">SNAKE PRIME</h3>
                <div className="mt-2 text-[9px] font-bold text-green-400 font-retro">BEST: {activeProfile?.snakeStats.bestScore}</div>
              </div>
            </button>

            {/* Diamond Rush Card */}
            <button 
              onClick={() => setCurrentView('diamond-rush')}
              className="group relative overflow-hidden aspect-square border border-slate-800 hover:neon-border-cyan transition-all flex flex-col p-6 bg-slate-950/80 hover:bg-cyan-500/5 rounded-xl"
            >
               <div className="absolute top-4 right-4 text-[8px] font-retro text-cyan-500/40">STATUS: FAST</div>
              <i className="fa-solid fa-gem text-5xl mb-auto text-cyan-500/20 group-hover:text-cyan-400 transition-all group-hover:scale-110"></i>
              <div className="text-left">
                <h3 className="text-xl font-black tracking-tighter text-white font-orbitron uppercase italic">DIAMOND RUSH</h3>
                <div className="mt-2 text-[9px] font-bold text-cyan-400 font-retro">BEST: {activeProfile?.diamondRushStats?.bestScore || 0}</div>
              </div>
            </button>

            {/* Chat Card */}
            <button 
              onClick={() => setCurrentView('chat')}
              className="group relative overflow-hidden aspect-square border border-slate-800 hover:neon-border-purple transition-all flex flex-col p-6 bg-slate-950/80 hover:bg-purple-500/5 rounded-xl"
            >
               <div className="absolute top-4 right-4 text-[8px] font-retro text-purple-500/40">STATUS: ONLINE</div>
              <i className="fa-solid fa-brain text-5xl mb-auto text-purple-500/20 group-hover:text-purple-500 transition-all group-hover:scale-110"></i>
              <div className="text-left">
                <h3 className="text-xl font-black tracking-tighter text-white font-orbitron uppercase italic">AI NEURAL</h3>
                <div className="mt-2 text-[9px] font-bold text-purple-400 font-retro">COMMS LINK</div>
              </div>
            </button>
          </div>

          <footer className="pt-8 pb-4 border-t border-slate-900 flex justify-between items-center opacity-60 shrink-0">
             <div className="text-[8px] text-slate-500 font-retro uppercase">SYSTEM: V3.4.0_PRIME</div>
             <div className="text-[8px] text-green-500 font-retro uppercase animate-pulse">ALL MODULES ACTIVE</div>
          </footer>
        </div>
      </div>
    );
  }

  // Specific Game Views
  if (currentView === 'chess') {
    return (
      <div className="h-screen bg-[#020202] flex items-center justify-center p-4 relative overflow-hidden">
        <div className="animated-grid opacity-30"></div>
        <ChessGame onExit={() => setCurrentView('hub')} onUpdateStats={handleUpdateChessStats} />
      </div>
    );
  }

  if (currentView === 'snake') {
    return (
      <div className="h-screen bg-[#020202] flex items-center justify-center p-4 relative overflow-hidden">
        <div className="animated-grid opacity-30"></div>
        <SnakeGame 
          onExit={() => setCurrentView('hub')} 
          onGameOver={handleSnakeGameOver} 
          highScore={activeProfile?.snakeStats.bestScore || 0}
        />
      </div>
    );
  }

  if (currentView === 'diamond-rush') {
    return (
      <div className="h-screen bg-[#020202] flex items-center justify-center p-4 relative overflow-hidden">
        <div className="animated-grid opacity-30"></div>
        <DiamondRush 
          onExit={() => setCurrentView('hub')} 
          onGameOver={handleDiamondRushGameOver} 
          highScore={activeProfile?.diamondRushStats?.bestScore || 0}
        />
      </div>
    );
  }

  if (currentView === 'chat') {
    return (
      <div className="h-screen bg-[#020202] flex items-center justify-center p-4 relative overflow-hidden">
        <div className="animated-grid opacity-30"></div>
        <ChatRoom 
          userName={activeProfile?.name || 'GUEST'} 
          onExit={() => setCurrentView('hub')} 
        />
      </div>
    );
  }

  // Tetris View
  return (
    <div className={`h-screen bg-[#020202] text-slate-200 flex flex-col items-center justify-between py-2 px-3 overflow-hidden font-sans relative ${isShaking ? 'animate-shake' : ''}`}>
      <div className="animated-grid opacity-20"></div>

      <header className="w-full max-w-md flex items-center justify-between px-1 z-10 shrink-0 mb-1">
        <div className="flex flex-col">
          <div className="flex items-center gap-2">
            <h1 className="text-xs font-black tracking-widest text-white uppercase font-orbitron italic">Tetris Prime</h1>
            <span className="text-[8px] text-cyan-400 font-retro uppercase tracking-widest border border-cyan-900/50 bg-cyan-950/20 px-2 py-0.5">PILOT: {activeProfile?.name}</span>
          </div>
          <span className="text-[7px] text-slate-600 uppercase tracking-widest font-retro -mt-1">Neural Assist Enabled</span>
        </div>
        <div className="flex items-center gap-2">
          {isGameStarted && (
            <button onClick={() => setPaused(!paused)} className="w-8 h-8 flex items-center justify-center text-slate-500 hover:text-white transition-colors border border-slate-800 rounded">
              <i className={`fa-solid ${paused ? 'fa-play' : 'fa-pause'} text-[10px]`}></i>
            </button>
          )}
          <button onClick={() => setCurrentView('hub')} className="text-[9px] font-black text-slate-500 hover:text-red-400 font-orbitron uppercase tracking-widest border border-slate-800 px-3 py-1.5 transition-all">
            ABORT
          </button>
        </div>
      </header>

      <div className="flex gap-3 items-stretch justify-center w-full max-w-md h-[75vh] z-10">
        <div className="flex-1 flex justify-center">
          <BoardView board={board} activePiece={activePiece} checkCollision={checkCollisionHelper} bombsCount={bombs} />
        </div>
        <GameUI score={score} highScore={activeProfile?.tetrisStats.bestScore || 0} level={level} lines={lines} bombs={bombs} nextPiece={nextPiece} />
      </div>

      <div className="w-full flex flex-col items-center gap-2 z-10 shrink-0 mt-1">
        <AISuggestions board={board} nextPiece={nextPiece} score={score} level={level} />
        <Controls onMove={move} onRotate={rotate} onHardDrop={hardDrop} onBomb={handleBombAction} bombs={bombs} />
      </div>

      {!isGameStarted && (
        <div className="fixed inset-0 bg-black/95 flex items-center justify-center z-50 p-6 backdrop-blur-md">
          <div className="w-full max-w-xs space-y-10 text-center">
            <div className="space-y-4">
              <h2 className="text-4xl font-black italic tracking-tighter text-white font-orbitron">MISSION SELECT</h2>
              <div className="h-1 bg-gradient-to-r from-transparent via-cyan-500 to-transparent"></div>
              <p className="text-[10px] text-cyan-500 font-retro uppercase tracking-[0.2em]">Pilot: {activeProfile?.name}</p>
            </div>
            <div className="flex flex-col gap-3">
              {hasSave && (
                <button
                  onClick={resumeGame}
                  className="py-5 bg-cyan-600 text-white hover:bg-cyan-500 hover:neon-border-cyan transition-all text-sm font-black uppercase font-orbitron italic tracking-widest shadow-[0_0_20px_rgba(8,145,178,0.4)] border-2 border-white/20 mb-2"
                >
                  RESUME MISSION
                </button>
              )}

              <div className="text-[8px] font-retro text-slate-500 uppercase tracking-widest mb-1">Start New Sync</div>
              {(Object.keys(Difficulty) as Array<keyof typeof Difficulty>).map((diff) => (
                <button
                  key={diff}
                  onClick={() => startGame(Difficulty[diff])}
                  className="py-4 border border-cyan-900 bg-cyan-950/10 hover:bg-cyan-500 hover:text-black hover:neon-border-cyan transition-all text-xs font-black uppercase font-orbitron italic tracking-widest"
                >
                  {diff} DEPLOY
                </button>
              ))}
            </div>
            <button onClick={() => setCurrentView('hub')} className="text-[10px] text-slate-600 font-retro uppercase tracking-widest hover:text-slate-400">Cancel Request</button>
          </div>
        </div>
      )}

      {gameOver && (
        <div className="fixed inset-0 bg-black/90 flex items-center justify-center z-50 p-6 backdrop-blur-md">
          <div className="w-full max-w-xs text-center space-y-8">
            <h2 className="text-4xl font-black italic tracking-tighter text-red-500 font-orbitron animate-pulse">HULL COMPROMISED</h2>
            <div className="py-6 border-y border-red-900/50 bg-red-950/10">
              <div className="text-[10px] text-red-400 font-retro uppercase tracking-widest mb-2">Final Performance</div>
              <div className="text-4xl font-black text-white font-orbitron">{score.toLocaleString()}</div>
              {score >= (activeProfile?.tetrisStats.bestScore || 0) && score > 0 && (
                <div className="text-yellow-500 text-[10px] font-retro uppercase tracking-widest mt-4">NEW PEAK REACHED</div>
              )}
            </div>
            <button 
              onClick={resetGame}
              className="w-full py-5 bg-red-600 text-white text-sm font-black uppercase font-orbitron italic tracking-widest shadow-[0_0_30px_rgba(220,38,38,0.4)]"
            >
              REBOOT SYSTEM
            </button>
            <button 
              onClick={() => setCurrentView('hub')}
              className="w-full py-3 text-slate-500 text-[10px] font-retro uppercase tracking-widest"
            >
              RETURN TO HUB
            </button>
          </div>
        </div>
      )}

      {paused && !gameOver && isGameStarted && (
        <div className="fixed inset-0 bg-black/80 flex items-center justify-center z-40 backdrop-blur-md">
          <div className="w-full max-w-xs text-center space-y-6">
            <h2 className="text-3xl font-black italic uppercase font-orbitron text-white">SYNC SUSPENDED</h2>
            <button onClick={() => setPaused(false)} className="w-full py-4 bg-cyan-600 text-white text-xs font-black font-orbitron uppercase italic tracking-widest shadow-xl">RESUME SYNC</button>
            <button onClick={() => { resetGame(); setCurrentView('hub'); }} className="w-full py-4 border border-slate-800 text-slate-400 text-xs font-black font-orbitron uppercase italic tracking-widest">ABORT MISSION</button>
          </div>
        </div>
      )}
    </div>
  );
};

