export const getRandomTetromino = (level: number = 1): Tetromino => {
  const availableKeys = ['I', 'J', 'L', 'O', 'S', 'T', 'Z'];

  if (level >= 2) availableKeys.push('TRI', 'CORNER');
  if (level >= 3) availableKeys.push('PLUS');
  if (level >= 4) availableKeys.push('BIG_L');
  if (level >= 5) availableKeys.push('U_SHAPE');

  const key = availableKeys[Math.floor(Math.random() * availableKeys.length)];
  return TETROMINOES[key];
};

import { useState, useEffect, useCallback, useRef } from 'react';
import { 
  Board, 
  Position, 
  Tetromino, 
  Direction, 
  Shape,
  Difficulty,
  UserProfile
} from '../types';
import { 
  COLS, 
  ROWS, 
  getRandomTetromino, 
  MIN_DROP_SPEED 
} from '../constants';
import { useSound } from './useSound';

const createEmptyBoard = (): Board => 
  Array.from({ length: ROWS }, () => Array(COLS).fill(null));

const DIFFICULTY_SPEEDS: Record<Difficulty, number> = {
  [Difficulty.Easy]: 1000,
  [Difficulty.Medium]: 700,
  [Difficulty.Hard]: 400,
};

const SCORING = [0, 100, 300, 500, 1200];
const T_SPIN_BONUS = [400, 800, 1200, 1600]; // Bonus for 0, 1, 2, 3 lines cleared with T-Spin

export const useTetris = (activeProfile: UserProfile | null) => {
  const { playMove, playRotate, playClear, playDrop, playGameOver, playBomb } = useSound();
  const [board, setBoard] = useState<Board>(createEmptyBoard());
  const [activePiece, setActivePiece] = useState<{ tetromino: Tetromino; position: Position } | null>(null);
  const [nextPiece, setNextPiece] = useState<Tetromino>(getRandomTetromino(1));
  const [score, setScore] = useState(0);
  const [highScore, setHighScore] = useState(0);
  const [level, setLevel] = useState(1);
  const [lines, setLines] = useState(0);
  const [bombs, setBombs] = useState(0);
  const [gameOver, setGameOver] = useState(false);
  const [paused, setPaused] = useState(false);
  const [difficulty, setDifficulty] = useState<Difficulty>(Difficulty.Medium);
  const [isGameStarted, setIsGameStarted] = useState(false);
  const [hasSave, setHasSave] = useState(false);

  const timerRef = useRef<number | null>(null);
  const isLastMoveRotation = useRef(false);

  const getSaveKey = useCallback(() => {
    return activeProfile ? `tetris_save_${activeProfile.id}` : null;
  }, [activeProfile]);

  // Check for existing save on mount or profile change
  useEffect(() => {
    const key = getSaveKey();
    if (key) {
      const saved = localStorage.getItem(key);
      setHasSave(!!saved);
    } else {
      setHasSave(false);
    }
  }, [activeProfile, getSaveKey]);

  useEffect(() => {
    if (activeProfile) {
      setHighScore(activeProfile.tetrisStats.bestScore);
    }
  }, [activeProfile]);

  // Auto-save effect
  useEffect(() => {
    const key = getSaveKey();
    if (key && isGameStarted && !gameOver) {
      const state = {
        board,
        activePiece,
        nextPiece,
        score,
        level,
        lines,
        bombs,
        difficulty,
        isGameStarted
      };
      localStorage.setItem(key, JSON.stringify(state));
      setHasSave(true);
    }
  }, [board, activePiece, nextPiece, score, level, lines, bombs, difficulty, isGameStarted, gameOver, getSaveKey]);

  const checkCollision = useCallback((shape: Shape, pos: Position, currentBoard: Board): boolean => {
    for (let y = 0; y < shape.length; y++) {
      for (let x = 0; x < shape[y].length; x++) {
        if (shape[y][x] !== 0) {
          const newX = pos.x + x;
          const newY = pos.y + y;
          if (newX < 0 || newX >= COLS || newY >= ROWS || (newY >= 0 && currentBoard[newY][newX] !== null)) {
            return true;
          }
        }
      }
    }
    return false;
  }, []);

  const isTSpinMove = (piece: { tetromino: Tetromino; position: Position }, currentBoard: Board): boolean => {
    if (piece.tetromino.id !== 'T' || !isLastMoveRotation.current) return false;

    const corners = [
      { x: 0, y: 0 },
      { x: 2, y: 0 },
      { x: 0, y: 2 },
      { x: 2, y: 2 }
    ];

    let occupiedCorners = 0;
    for (const corner of corners) {
      const boardX = piece.position.x + corner.x;
      const boardY = piece.position.y + corner.y;

      if (boardX < 0 || boardX >= COLS || boardY >= ROWS || (boardY >= 0 && currentBoard[boardY][boardX] !== null)) {
        occupiedCorners++;
      }
    }

    return occupiedCorners >= 3;
  };

  const finalizePiece = useCallback((pieceToLock: { tetromino: Tetromino; position: Position }) => {
    setBoard(prevBoard => {
      const newBoard = prevBoard.map(row => [...row]);
      pieceToLock.tetromino.shape.forEach((row, y) => {
        row.forEach((value, x) => {
          if (value !== 0) {
            const boardY = pieceToLock.position.y + y;
            const boardX = pieceToLock.position.x + x;
            if (boardY >= 0 && boardY < ROWS && boardX >= 0 && boardX < COLS) {
              newBoard[boardY][boardX] = pieceToLock.tetromino.color;
            }
          }
        });
      });

      const tSpin = isTSpinMove(pieceToLock, prevBoard);
      let clearedCount = 0;
      const filteredBoard = newBoard.filter(row => {
        const isFull = row.every(cell => cell !== null);
        if (isFull) clearedCount++;
        return !isFull;
      });

      while (filteredBoard.length < ROWS) filteredBoard.unshift(Array(COLS).fill(null));

      let points = SCORING[clearedCount] * level;
      if (tSpin) {
        points += T_SPIN_BONUS[Math.min(clearedCount, 3)] * level;
      }

      if (clearedCount > 0 || tSpin) {
        if (clearedCount > 0) playClear(clearedCount);

        setScore(s => {
          const newScore = s + points;
          if (newScore > highScore) setHighScore(newScore);

          // Require 10,000 points per level milestone
          const newLevel = Math.floor(newScore / 10000) + 1;
          if (newLevel > level) setLevel(newLevel);
          return newScore;
        });

        if (clearedCount > 0) {
          setLines(l => {
            const newTotal = l + clearedCount;
            // Reward bomb every 10 lines
            if (Math.floor(newTotal / 10) > Math.floor(l / 10)) {
              setBombs(b => b + 1);
            }
            return newTotal;
          });
        }
      } else {
        playDrop();
      }

      return filteredBoard;
    });
    setActivePiece(null);
    isLastMoveRotation.current = false;
  }, [level, highScore, playClear, playDrop]);

  const useBomb = useCallback(() => {
    if (bombs <= 0 || !isGameStarted || paused || gameOver) return;
    setBombs(prev => prev - 1);
    playBomb();
    setBoard(prev => {
      const newBoard = [...prev];
      for (let i = 0; i < 4; i++) {
        newBoard.pop();
        newBoard.unshift(Array(COLS).fill(null));
      }
      return newBoard;
    });
  }, [bombs, isGameStarted, paused, gameOver, playBomb]);

  const spawnPiece = useCallback(() => {
    const piece = nextPiece;
    const spawnPos = { x: Math.floor(COLS / 2) - 1, y: 0 };
    if (checkCollision(piece.shape, spawnPos, board)) {
      setGameOver(true);
      playGameOver();
      const key = getSaveKey();
      if (key) localStorage.removeItem(key);
      setHasSave(false);
      return;
    }
    setActivePiece({ tetromino: piece, position: spawnPos });
    // Use level to determine available shapes
    setNextPiece(getRandomTetromino(level));
    isLastMoveRotation.current = false;
  }, [nextPiece, board, checkCollision, playGameOver, getSaveKey, level]);

  const move = useCallback((dir: Direction) => {
    if (!activePiece || paused || gameOver || !isGameStarted) return false;
    const newPos = {
      x: activePiece.position.x + (dir === Direction.Down ? 0 : dir),
      y: activePiece.position.y + (dir === Direction.Down ? 1 : 0)
    };
    if (!checkCollision(activePiece.tetromino.shape, newPos, board)) {
      setActivePiece(prev => prev ? { ...prev, position: newPos } : null);
      if (dir !== Direction.Down) {
        playMove();
        isLastMoveRotation.current = false;
      }
      return true;
    }
    if (dir === Direction.Down) finalizePiece(activePiece);
    return false;
  }, [activePiece, board, checkCollision, paused, gameOver, finalizePiece, isGameStarted, playMove]);

  const rotate = useCallback(() => {
    if (!activePiece || paused || gameOver || !isGameStarted) return;
    const rotatedShape = activePiece.tetromino.shape[0].map((_, index) =>
      activePiece.tetromino.shape.map(col => col[index]).reverse()
    );
    if (!checkCollision(rotatedShape, activePiece.position, board)) {
      setActivePiece(prev => prev ? { ...prev, tetromino: { ...prev.tetromino, shape: rotatedShape } } : null);
      playRotate();
      isLastMoveRotation.current = true;
    }
  }, [activePiece, board, checkCollision, paused, gameOver, isGameStarted, playRotate]);

  const hardDrop = useCallback(() => {
    if (!activePiece || paused || gameOver || !isGameStarted) return;
    let newY = activePiece.position.y;
    while (!checkCollision(activePiece.tetromino.shape, { x: activePiece.position.x, y: newY + 1 }, board)) {
      newY++;
    }
    const finalPiece = { ...activePiece, position: { ...activePiece.position, y: newY } };
    finalizePiece(finalPiece);
  }, [activePiece, board, checkCollision, paused, gameOver, isGameStarted, finalizePiece]);

  const startGame = useCallback((selectedDifficulty: Difficulty) => {
    setDifficulty(selectedDifficulty);
    setIsGameStarted(true);
    setGameOver(false);
    setPaused(false);
    setBoard(createEmptyBoard());
    setScore(0);
    setLevel(1);
    setLines(0);
    setBombs(0);
    setActivePiece(null);
    setNextPiece(getRandomTetromino(1));
    isLastMoveRotation.current = false;

    // Clear save if starting fresh
    const key = getSaveKey();
    if (key) localStorage.removeItem(key);
    setHasSave(false);
  }, [getSaveKey]);

  const resumeGame = useCallback(() => {
    const key = getSaveKey();
    if (!key) return;
    const saved = localStorage.getItem(key);
    if (saved) {
      const state = JSON.parse(saved);
      setBoard(state.board);
      setActivePiece(state.activePiece);
      setNextPiece(state.nextPiece);
      setScore(state.score);
      setLevel(state.level);
      setLines(state.lines);
      setBombs(state.bombs);
      setDifficulty(state.difficulty);
      setIsGameStarted(true);
      setGameOver(false);
      setPaused(false);
    }
  }, [getSaveKey]);

  const resetGame = useCallback(() => {
    setIsGameStarted(false);
    setGameOver(false);
    setPaused(false);
    isLastMoveRotation.current = false;
  }, []);

  useEffect(() => {
    if (isGameStarted && !activePiece && !gameOver && !paused) {
      spawnPiece();
    }
  }, [activePiece, gameOver, paused, spawnPiece, isGameStarted]);

  useEffect(() => {
    if (gameOver || paused || !isGameStarted) return;
    const baseSpeed = DIFFICULTY_SPEEDS[difficulty];
    // Scale speed by level - since levels are now 10,000 pts apart, 
    // we make speed increments slightly more impactful per level if needed, 
    // or just keep it based on the number.
    const speed = Math.max(MIN_DROP_SPEED, baseSpeed - (level - 1) * 100);
    timerRef.current = window.setInterval(() => move(Direction.Down), speed);
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [move, level, gameOver, paused, difficulty, isGameStarted]);

  return { 
    board, activePiece, nextPiece, score, highScore, level, lines, bombs, useBomb, 
    gameOver, paused, difficulty, isGameStarted, setPaused, move, rotate, 
    hardDrop, resetGame, startGame, resumeGame, hasSave 
  };
};

import React, { useState, useEffect, useCallback } from 'react';
import { useTetris } from './hooks/useTetris';
