                    <div className="text-[9px] text-slate-500 uppercase tracking-widest mt-1">
                      EXP: {p.tetrisStats.gamesPlayed + p.chessStats.wins + p.snakeStats.gamesPlayed + (p.diamondRushStats?.gamesPlayed || 0)} Units
                    </div>
                  </div>
                  <i className="fa-solid fa-play text-[12px] text-slate-700 group-hover:text-cyan-400 animate-pulse"></i>
                </button>
              ))}
              {profiles.length === 0 && (
                <div className="text-center py-10 border border-dashed border-slate-800 rounded text-[10px] text-slate-600 font-retro">
                  NO USERS DETECTED
                </div>
              )}
            </div>

            <form onSubmit={handleCreateProfile} className="mt-8 pt-6 border-t border-slate-800 space-y-4">
              <h2 className="text-[11px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2">
                <i className="fa-solid fa-plus text-cyan-500"></i> Register New Pilot
              </h2>
              <div className="flex gap-2">
                <input
                  type="text"
                  placeholder="INPUT CALLSIGN"
                  value={newProfileName}
                  onChange={(e) => setNewProfileName(e.target.value.toUpperCase())}
                  maxLength={12}
                  className="flex-1 bg-black/60 border border-slate-800 px-4 py-3 text-sm font-orbitron font-bold tracking-widest focus:border-cyan-500 focus:outline-none placeholder:text-slate-700 text-cyan-400"
                />
                <button type="submit" className="bg-cyan-600 text-white px-6 py-3 text-xs font-black uppercase tracking-widest hover:bg-cyan-500 active:scale-95 shadow-[0_0_20px_rgba(8,145,178,0.4)]">
                  LINK
                </button>
              </div>
            </form>
          </div>
        </div>
      </div>
    );
  }

  // Hub Screen
  if (currentView === 'hub') {
