              <i className="fa-solid fa-shapes text-5xl mb-auto text-cyan-500/20 group-hover:text-cyan-500 transition-all group-hover:scale-110"></i>
              <div className="text-left">
                <h3 className="text-xl font-black tracking-tighter text-white font-orbitron uppercase italic">TETRIS PRIME</h3>
                <div className="mt-2 text-[9px] font-bold text-cyan-400 font-retro">BEST: {activeProfile?.tetrisStats.bestScore}</div>
              </div>
