import React, { useState } from 'react';
import { getGameAdvice } from '../services/geminiService';
import { Board, Tetromino } from '../types';

interface AISuggestionsProps {
  board: Board;
  nextPiece: Tetromino;
  score: number;
  level: number;
}

const AISuggestions: React.FC<AISuggestionsProps> = ({ board, nextPiece, score, level }) => {
  const [loading, setLoading] = useState(false);
  const [advice, setAdvice] = useState<string[]>([]);
  const [risk, setRisk] = useState<string>('');

  const fetchAdvice = async () => {
    setLoading(true);
    const result = await getGameAdvice(board, nextPiece, score, level);
    if (result) {
      setAdvice(result.advice);
      setRisk(result.riskLevel);
    }
    setLoading(false);
  };

  return (
    <div className="w-full px-2 max-w-xs">
      <div className="bg-[#0a0a0a]/80 backdrop-blur-sm border border-slate-800/60 rounded-sm p-1 flex items-center gap-2">
        <button 
          onClick={fetchAdvice}
          disabled={loading}
          className="h-7 w-7 shrink-0 flex items-center justify-center border border-slate-800 hover:border-cyan-500 transition-colors disabled:opacity-20 bg-black/40"
        >
          <i className={`fa-solid ${loading ? 'fa-spinner fa-spin' : 'fa-bolt-lightning'} text-[9px] text-cyan-500`}></i>
        </button>

        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-0.5">
             <span className="text-[5px] font-bold uppercase text-slate-600 tracking-widest font-retro">AI INTEL</span>
             {risk && (
                <span className={`text-[5px] font-bold px-1 py-0.5 rounded-none uppercase border ${
                  risk === 'Low' ? 'border-green-900/50 text-green-500/80' : 
                  risk === 'Medium' ? 'border-yellow-900/50 text-yellow-500/80' : 'border-red-900/50 text-red-500/80'
                }`}>
                  {risk}
                </span>
              )}
          </div>
          <div className="truncate">
            {advice.length > 0 ? (
              <p className="text-[8px] text-slate-300 font-medium leading-none truncate italic">
                {advice[0]}
              </p>
            ) : (
              <p className="text-[7px] text-slate-600 leading-none uppercase tracking-tighter">Ready for link...</p>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

