import React, { useState, useEffect } from 'react';
import { Board, ActivePiece, Position } from '../types';

interface BoardViewProps {
  board: Board;
  activePiece: ActivePiece | null;
  checkCollision: (shape: number[][], pos: Position, board: Board) => boolean;
  bombsCount: number;
}

const BoardView: React.FC<BoardViewProps> = ({ board, activePiece, checkCollision, bombsCount }) => {
  const [showBlast, setShowBlast] = useState(false);
  const [lastBombsCount, setLastBombsCount] = useState(bombsCount);

  useEffect(() => {
    if (bombsCount < lastBombsCount) {
      setShowBlast(true);
      const timer = setTimeout(() => setShowBlast(false), 600);
      return () => clearTimeout(timer);
    }
    setLastBombsCount(bombsCount);
  }, [bombsCount, lastBombsCount]);

  let ghostY = activePiece?.position.y || 0;
  if (activePiece) {
    while (!checkCollision(activePiece.tetromino.shape, { x: activePiece.position.x, y: ghostY + 1 }, board)) {
      ghostY++;
    }
  }

  const renderCell = (y: number, x: number) => {
    let color = board[y][x];
    let isGhost = false;
    let isActive = false;

    if (activePiece) {
      const shape = activePiece.tetromino.shape;
      const py = y - activePiece.position.y;
      const px = x - activePiece.position.x;
      if (py >= 0 && py < shape.length && px >= 0 && px < shape[0].length && shape[py][px]) {
        color = activePiece.tetromino.color;
        isActive = true;
      }
      const gy = y - ghostY;
      if (!isActive && gy >= 0 && gy < shape.length && px >= 0 && px < shape[0].length && shape[gy][px]) {
        color = activePiece.tetromino.color;
        isGhost = true;
      }
    }

    return (
      <div
        key={`${y}-${x}`}
        className={`
          relative w-full h-full
          ${color || 'bg-white/5'} 
          ${isGhost ? 'opacity-20 border border-dashed border-white/20' : 'opacity-100'}
          ${isActive ? 'z-10 shadow-[0_0_12px_rgba(255,255,255,0.4)]' : ''}
          rounded-[2px] transition-all duration-75
        `}
      >
        {color && !isGhost && (
          <div className="absolute inset-0 block-gloss border border-white/20" />
        )}
      </div>
    );
  };

  return (
    <div className="h-full aspect-[1/2] grid grid-cols-10 grid-rows-20 gap-[2px] bg-black p-1.5 rounded-lg border-2 border-slate-800 shadow-[0_30px_60px_rgba(0,0,0,0.8),0_0_30px_rgba(168,85,247,0.1)] relative overflow-hidden transition-all scale-100 md:scale-105">
      {board.map((row, y) => row.map((_, x) => renderCell(y, x)))}

      {showBlast && (
        <div className="absolute inset-0 bg-white/20 animate-pulse pointer-events-none flex items-center justify-center z-50">
           <div className="w-32 h-32 bg-amber-500 rounded-full blur-3xl opacity-50 animate-ping"></div>
        </div>
      )}
    </div>
  );
};

