import React, { useState, useEffect, useCallback } from 'react';
import { useTetris } from './hooks/useTetris';
import BoardView from './components/BoardView';
import Controls from './components/Controls';
import GameUI from './components/GameUI';
import AISuggestions from './components/AISuggestions';
import ChessGame from './components/ChessGame';
import SnakeGame from './components/SnakeGame';
import ChatRoom from './components/ChatRoom';
import DiamondRush from './components/DiamondRush';
import { Direction, Position, Board, Difficulty, UserProfile, GameType } from './types';

const STORAGE_KEY = 'tetris_prime_profiles_v3';

const App: React.FC = () => {
  const [profiles, setProfiles] = useState<UserProfile[]>([]);
  const [activeProfile, setActiveProfile] = useState<UserProfile | null>(null);
  const [currentView, setCurrentView] = useState<'profile-selector' | 'hub' | 'tetris' | 'chess' | 'snake' | 'chat' | 'diamond-rush'>('profile-selector');
  const [newProfileName, setNewProfileName] = useState('');
  const [isShaking, setIsShaking] = useState(false);

  const { 
    board, activePiece, nextPiece, score, highScore, level, lines, bombs, useBomb,
    gameOver, paused, difficulty, isGameStarted, setPaused, 
    move, rotate, hardDrop, resetGame, startGame, resumeGame, hasSave 
  } = useTetris(activeProfile);

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      setProfiles(JSON.parse(saved));
    }
  }, []);

  useEffect(() => {
    if (profiles.length > 0) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(profiles));
    }
  }, [profiles]);

  useEffect(() => {
    if (gameOver && activeProfile) {
      const updatedProfiles = profiles.map(p => {
        if (p.id === activeProfile.id) {
          return {
            ...p,
            tetrisStats: {
              bestScore: Math.max(p.tetrisStats.bestScore, score),
              totalLines: p.tetrisStats.totalLines + lines,
              gamesPlayed: p.tetrisStats.gamesPlayed + 1
            }
          };
        }
        return p;
      });
      setProfiles(updatedProfiles);
      setActiveProfile(updatedProfiles.find(p => p.id === activeProfile.id) || null);
    }
  }, [gameOver]);

  const handleUpdateChessStats = (result: 'white' | 'black' | 'draw') => {
    if (!activeProfile) return;
    const updatedProfiles = profiles.map(p => {
      if (p.id === activeProfile.id) {
        const stats = { ...p.chessStats };
        if (result === 'white') stats.wins++;
        else if (result === 'black') stats.losses++;
        else stats.draws++;
        return { ...p, chessStats: stats };
      }
      return p;
    });
    setProfiles(updatedProfiles);
    setActiveProfile(updatedProfiles.find(p => p.id === activeProfile.id) || null);
  };

  const handleSnakeGameOver = (finalScore: number) => {
    if (!activeProfile) return;
    const updatedProfiles = profiles.map(p => {
      if (p.id === activeProfile.id) {
        return {
          ...p,
          snakeStats: {
            bestScore: Math.max(p.snakeStats.bestScore, finalScore),
            gamesPlayed: p.snakeStats.gamesPlayed + 1
          }
        };
      }
      return p;
    });
    setProfiles(updatedProfiles);
    setActiveProfile(updatedProfiles.find(p => p.id === activeProfile.id) || null);
  };

  const handleDiamondRushGameOver = (finalScore: number, finalDiamonds: number) => {
    if (!activeProfile) return;
    const updatedProfiles = profiles.map(p => {
      if (p.id === activeProfile.id) {
        return {
          ...p,
          diamondRushStats: {
            bestScore: Math.max(p.diamondRushStats?.bestScore || 0, finalScore),
            totalDiamonds: (p.diamondRushStats?.totalDiamonds || 0) + finalDiamonds,
            gamesPlayed: (p.diamondRushStats?.gamesPlayed || 0) + 1
          }
        };
      }
      return p;
    });
    setProfiles(updatedProfiles);
    setActiveProfile(updatedProfiles.find(p => p.id === activeProfile.id) || null);
  };

  const handleBombAction = useCallback(() => {
    if (bombs > 0 && isGameStarted && !paused && !gameOver) {
      useBomb();
      setIsShaking(true);
      setTimeout(() => setIsShaking(false), 500);
    }
  }, [bombs, isGameStarted, paused, gameOver, useBomb]);

  const handleCreateProfile = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newProfileName.trim()) return;
    const newProfile: UserProfile = {
