import React, { useState, useEffect, useCallback } from 'react';
import { useTetris } from './hooks/useTetris';
import BoardView from './components/BoardView';
import Controls from './components/Controls';
import GameUI from './components/GameUI';
import AISuggestions from './components/AISuggestions';
import ChessGame from './components/ChessGame';
import SnakeGame from './components/SnakeGame';
import ChatRoom from './components/ChatRoom';
import DiamondRush from './components/DiamondRush';
import { Direction, Position, Board, Difficulty, UserProfile, GameType } from './types';

const STORAGE_KEY = 'tetris_prime_profiles_v3';

const App: React.FC = () => {
  const [profiles, setProfiles] = useState<UserProfile[]>([]);
  const [activeProfile, setActiveProfile] = useState<UserProfile | null>(null);
  const [currentView, setCurrentView] = useState<'profile-selector' | 'hub' | 'tetris' | 'chess' | 'snake' | 'chat' | 'diamond-rush'>('profile-selector');
  const [newProfileName, setNewProfileName] = useState('');
  const [isShaking, setIsShaking] = useState(false);

  const { 
    board, activePiece, nextPiece, score, highScore, level, lines, bombs, useBomb,
    gameOver, paused, difficulty, isGameStarted, setPaused, 
    move, rotate, hardDrop, resetGame, startGame, resumeGame, hasSave 
  } = useTetris(activeProfile);

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      setProfiles(JSON.parse(saved));
    }
  }, []);

  useEffect(() => {
    if (profiles.length > 0) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(profiles));
    }
  }, [profiles]);

  useEffect(() => {
    if (gameOver && activeProfile) {
      const updatedProfiles = profiles.map(p => {
        if (p.id === activeProfile.id) {
          return {
            ...p,
            tetrisStats: {
              bestScore: Math.max(p.tetrisStats.bestScore, score),
              totalLines: p.tetrisStats.totalLines + lines,
              gamesPlayed: p.tetrisStats.gamesPlayed + 1
            }
          };
        }
        return p;
      });
      setProfiles(updatedProfiles);
      setActiveProfile(updatedProfiles.find(p => p.id === activeProfile.id) || null);
    }
  }, [gameOver]);

  const handleUpdateChessStats = (result: 'white' | 'black' | 'draw') => {
    if (!activeProfile) return;
    const updatedProfiles = profiles.map(p => {
      if (p.id === activeProfile.id) {
        const stats = { ...p.chessStats };
        if (result === 'white') stats.wins++;
        else if (result === 'black') stats.losses++;
        else stats.draws++;
        return { ...p, chessStats: stats };
      }
      return p;
    });
    setProfiles(updatedProfiles);
    setActiveProfile(updatedProfiles.find(p => p.id === activeProfile.id) || null);
  };

  const handleSnakeGameOver = (finalScore: number) => {
    if (!activeProfile) return;
    const updatedProfiles = profiles.map(p => {
      if (p.id === activeProfile.id) {
        return {
          ...p,
          snakeStats: {
            bestScore: Math.max(p.snakeStats.bestScore, finalScore),
            gamesPlayed: p.snakeStats.gamesPlayed + 1
          }
        };
      }
      return p;
    });
    setProfiles(updatedProfiles);
    setActiveProfile(updatedProfiles.find(p => p.id === activeProfile.id) || null);
  };

  const handleDiamondRushGameOver = (finalScore: number, finalDiamonds: number) => {
    if (!activeProfile) return;
    const updatedProfiles = profiles.map(p => {
      if (p.id === activeProfile.id) {
        return {
          ...p,
          diamondRushStats: {
            bestScore: Math.max(p.diamondRushStats?.bestScore || 0, finalScore),
            totalDiamonds: (p.diamondRushStats?.totalDiamonds || 0) + finalDiamonds,
            gamesPlayed: (p.diamondRushStats?.gamesPlayed || 0) + 1
          }
        };
      }
      return p;
    });
    setProfiles(updatedProfiles);
    setActiveProfile(updatedProfiles.find(p => p.id === activeProfile.id) || null);
  };

  const handleBombAction = useCallback(() => {
    if (bombs > 0 && isGameStarted && !paused && !gameOver) {
      useBomb();
      setIsShaking(true);
      setTimeout(() => setIsShaking(false), 500);
    }
  }, [bombs, isGameStarted, paused, gameOver, useBomb]);

  const handleCreateProfile = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newProfileName.trim()) return;
    const newProfile: UserProfile = {
      id: Date.now().toString(),
      name: newProfileName.trim(),
      tetrisStats: { bestScore: 0, totalLines: 0, gamesPlayed: 0 },
      chessStats: { wins: 0, losses: 0, draws: 0 },
      snakeStats: { bestScore: 0, gamesPlayed: 0 },
      diamondRushStats: { bestScore: 0, totalDiamonds: 0, gamesPlayed: 0 }
    };
    setProfiles(prev => [...prev, newProfile]);
    setActiveProfile(newProfile);
    setNewProfileName('');
    setCurrentView('hub');
  };

  const selectProfile = (p: UserProfile) => {
    setActiveProfile(p);
    setCurrentView('hub');
  };

  const logout = () => {
    setActiveProfile(null);
    setCurrentView('profile-selector');
    resetGame();
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (currentView !== 'tetris' || gameOver || !isGameStarted) return;
      switch (e.key) {
        case 'ArrowLeft': move(Direction.Left); break;
        case 'ArrowRight': move(Direction.Right); break;
        case 'ArrowDown': move(Direction.Down); break;
        case 'ArrowUp': rotate(); break;
        case ' ': hardDrop(); break;
        case 'b': handleBombAction(); break;
        case 'p': setPaused(!paused); break;
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [move, rotate, hardDrop, handleBombAction, paused, setPaused, gameOver, isGameStarted, currentView]);

  const checkCollisionHelper = (shape: number[][], pos: Position, b: Board) => {
    for (let y = 0; y < shape.length; y++) {
      for (let x = 0; x < shape[y].length; x++) {
        if (shape[y][x] !== 0) {
          const newX = pos.x + x;
          const newY = pos.y + y;
          if (newX < 0 || newX >= 10 || newY >= 20 || (newY >= 0 && b[newY][newX] !== null)) return true;
        }
      }
    }
    return false;
  };

  if (currentView === 'profile-selector') {
    return (
      <div className="h-screen bg-[#050505] text-slate-200 flex flex-col items-center justify-center p-6 relative overflow-hidden">
        <div className="animated-grid"></div>
        <div className="w-full max-md space-y-10 z-10">
          <div className="text-center space-y-4">
            <h1 className="text-5xl font-black tracking-tighter text-transparent bg-clip-text bg-gradient-to-b from-white to-amber-500 font-orbitron italic">PRIME ARCADE</h1>
            <div className="flex items-center justify-center gap-4">
               <div className="h-[1px] flex-1 bg-gradient-to-r from-transparent to-amber-500"></div>
               <p className="text-[10px] text-amber-400 font-retro tracking-widest uppercase">Initializing Core Systems</p>
               <div className="h-[1px] flex-1 bg-gradient-to-l from-transparent to-amber-500"></div>
            </div>
          </div>
          <div className="bg-slate-900/40 backdrop-blur-md border border-amber-500/20 p-6 rounded-lg shadow-2xl">
            <h2 className="text-[11px] font-bold text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2">
              <i className="fa-solid fa-users-gear text-amber-500"></i> Active Operators
            </h2>
            <div className="max-h-64 overflow-y-auto space-y-3 custom-scrollbar pr-1">
              {profiles.map(p => (
                <button key={p.id} onClick={() => selectProfile(p)} className="w-full p-4 bg-black/40 border border-slate-800 hover:border-amber-400/60 hover:bg-amber-500/10 group transition-all flex items-center justify-between">
                  <div className="text-left">
                    <div className="text-base font-black group-hover:text-amber-400 font-orbitron uppercase">{p.name}</div>
                    <div className="text-[9px] text-slate-500 uppercase tracking-widest mt-1">EXP: {p.tetrisStats.gamesPlayed + p.chessStats.wins + p.snakeStats.gamesPlayed + (p.diamondRushStats?.gamesPlayed || 0)} Units</div>
                  </div>
                  <i className="fa-solid fa-play text-[12px] text-slate-700 group-hover:text-amber-400 animate-pulse"></i>
                </button>
              ))}
              {profiles.length === 0 && <div className="text-center py-10 border border-dashed border-slate-800 rounded text-[10px] text-slate-600 font-retro">NO USERS DETECTED</div>}
            </div>
            <form onSubmit={handleCreateProfile} className="mt-8 pt-6 border-t border-slate-800 space-y-4">
              <h2 className="text-[11px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2">
                <i className="fa-solid fa-plus text-amber-500"></i> Register New Pilot
              </h2>
              <div className="flex gap-2">
                <input type="text" placeholder="INPUT CALLSIGN" value={newProfileName} onChange={(e) => setNewProfileName(e.target.value.toUpperCase())} maxLength={12} className="flex-1 bg-black/60 border border-slate-800 px-4 py-3 text-sm font-orbitron font-bold tracking-widest focus:border-amber-500 focus:outline-none placeholder:text-slate-700 text-amber-400" />
                <button type="submit" className="bg-amber-600 text-white px-6 py-3 text-xs font-black uppercase tracking-widest hover:bg-amber-500 active:scale-95 shadow-[0_0_20px_rgba(245,158,11,0.4)]">LINK</button>
              </div>
            </form>
          </div>
        </div>
      </div>
    );
  }

  if (currentView === 'hub') {
    return (
      <div className="h-screen bg-[#050505] text-slate-200 flex flex-col items-center justify-start p-6 relative overflow-hidden">
        <div className="animated-grid"></div>
        <div className="w-full max-w-lg space-y-8 z-10 pt-4 overflow-y-auto custom-scrollbar">
          <header className="flex justify-between items-center bg-slate-900/40 backdrop-blur-md p-4 border-l-4 border-amber-500 rounded-r-lg shadow-xl shrink-0">
            <div className="space-y-1">
              <h1 className="text-2xl font-black italic tracking-tighter text-white font-orbitron uppercase">COMMAND HUB</h1>
              <div className="flex items-center gap-3">
                <div className="flex gap-1"><span className="w-2 h-2 bg-green-500 rounded-full animate-ping"></span><span className="w-2 h-2 bg-green-500 rounded-full"></span></div>
                <span className="text-[10px] text-amber-400 font-retro uppercase">USER: {activeProfile?.name}</span>
              </div>
            </div>
            <button onClick={logout} className="text-[10px] font-black text-slate-500 hover:text-red-500 font-orbitron uppercase tracking-widest px-4 py-2 border border-slate-800 hover:border-red-500/40 transition-all">TERMINATE</button>
          </header>
          <div className="grid grid-cols-2 gap-4 pb-10">
