            <button onClick={() => setCurrentView('chess')} className="group relative overflow-hidden aspect-square border border-slate-800 hover:neon-border-purple transition-all flex flex-col p-6 bg-slate-950/80 hover:bg-purple-500/5 rounded-xl">
