              <div className="text-left"><h3 className="text-xl font-black tracking-tighter text-white font-orbitron uppercase italic">CHESS PRIME</h3><div className="mt-2 text-[9px] font-bold text-purple-400 font-retro">WINS: {activeProfile?.chessStats.wins}</div></div>
            </button>
            <button onClick={() => setCurrentView('snake')} className="group relative overflow-hidden aspect-square border border-slate-800 hover:neon-border-pink transition-all flex flex-col p-6 bg-slate-950/80 hover:bg-pink-500/5 rounded-xl">
              <div className="absolute top-4 right-4 text-[8px] font-retro text-pink-500/40">THREAT: MED</div>
              <i className="fa-solid fa-worm text-5xl mb-auto text-pink-500/20 group-hover:text-pink-500 transition-all group-hover:scale-110"></i>
              <div className="text-left"><h3 className="text-xl font-black tracking-tighter text-white font-orbitron uppercase italic">SNAKE PRIME</h3><div className="mt-2 text-[9px] font-bold text-pink-400 font-retro">BEST: {activeProfile?.snakeStats.bestScore}</div></div>
            </button>
            <button onClick={() => setCurrentView('diamond-rush')} className="group relative overflow-hidden aspect-square border border-slate-800 hover:neon-border-gold transition-all flex flex-col p-6 bg-slate-950/80 hover:bg-amber-500/5 rounded-xl">
               <div className="absolute top-4 right-4 text-[8px] font-retro text-amber-500/40">STATUS: FAST</div>
              <i className="fa-solid fa-gem text-5xl mb-auto text-amber-500/20 group-hover:text-amber-400 transition-all group-hover:scale-110"></i>
              <div className="text-left"><h3 className="text-xl font-black tracking-tighter text-white font-orbitron uppercase italic">DIAMOND RUSH</h3><div className="mt-2 text-[9px] font-bold text-amber-400 font-retro">BEST: {activeProfile?.diamondRushStats?.bestScore || 0}</div></div>
            </button>
          </div>
          <footer className="pt-8 pb-4 border-t border-slate-900 flex justify-between items-center opacity-60 shrink-0"><div className="text-[8px] text-slate-500 font-retro uppercase">SYSTEM: V3.5.0_GOLD</div><div className="text-[8px] text-amber-500 font-retro uppercase animate-pulse">CORE MODULES SYNCED</div></footer>
        </div>
      </div>
    );
  }

  // Tetris View
  if (currentView === 'tetris') {
    return (
      <div className={`h-screen bg-[#050505] text-slate-200 flex flex-col items-center justify-start py-1 px-2 overflow-hidden font-sans relative ${isShaking ? 'animate-shake' : ''}`}>
        <div className="animated-grid opacity-30"></div>

        <header className="w-full max-w-2xl flex items-center justify-between px-1 z-10 shrink-0 mb-1">
          <div className="flex flex-col">
            <div className="flex items-center gap-2">
              <h1 className="text-[10px] font-black tracking-wider text-white uppercase font-orbitron italic">Tetris Prime <span className="text-amber-500">Gold</span></h1>
              <span className="text-[7px] text-amber-400 font-retro uppercase border border-amber-900/50 bg-amber-950/30 px-1.5 py-0.5">PILOT: {activeProfile?.name}</span>
            </div>
          </div>
          <div className="flex items-center gap-2">
            {isGameStarted && (
              <button onClick={() => setPaused(!paused)} className="w-8 h-8 flex items-center justify-center text-slate-400 hover:text-white border border-slate-800 bg-slate-900/40 rounded">
                <i className={`fa-solid ${paused ? 'fa-play' : 'fa-pause'} text-[10px]`}></i>
              </button>
            )}
            <button onClick={() => setCurrentView('hub')} className="text-[8px] font-black text-slate-400 hover:text-red-400 font-orbitron uppercase tracking-tighter border border-slate-800 px-2 py-1 transition-all bg-slate-900/40">
              EXIT
            </button>
          </div>
        </header>

        <div className="flex gap-2 items-stretch justify-center w-full max-w-2xl h-[calc(100vh-140px)] z-10 mb-2 transition-all">
          <div className="flex-1 flex justify-center h-full max-w-[340px]">
            <BoardView board={board} activePiece={activePiece} checkCollision={checkCollisionHelper} bombsCount={bombs} />
          </div>
          <div className="flex flex-col gap-1.5 w-20 shrink-0">
            <GameUI score={score} highScore={activeProfile?.tetrisStats.bestScore || 0} level={level} lines={lines} bombs={bombs} nextPiece={nextPiece} />
            <div className="mt-auto">
               <AISuggestions board={board} nextPiece={nextPiece} score={score} level={level} />
            </div>
          </div>
        </div>

        <div className="w-full flex flex-col items-center gap-1 z-20 shrink-0 mt-auto pb-4">
          <Controls onMove={move} onRotate={rotate} onHardDrop={hardDrop} onBomb={handleBombAction} bombs={bombs} />
        </div>

        {!isGameStarted && (
          <div className="fixed inset-0 bg-black/95 flex items-center justify-center z-50 p-4 backdrop-blur-md">
            <div className="w-full max-w-sm space-y-8 text-center">
              <div className="space-y-4">
                <h2 className="text-4xl font-black italic tracking-tighter text-white font-orbitron">MISSION START</h2>
                <div className="h-0.5 bg-gradient-to-r from-transparent via-amber-500 to-transparent"></div>
                <p className="text-[10px] text-amber-500 font-retro uppercase tracking-[0.2em]">Pilot Authorization Required</p>
              </div>
              <div className="flex flex-col gap-2">
                {hasSave && (
                  <button onClick={resumeGame} className="py-5 bg-amber-600 text-white hover:bg-amber-500 hover:neon-border-gold transition-all text-sm font-black uppercase font-orbitron italic tracking-widest shadow-[0_0_20px_rgba(245,158,11,0.5)] border border-white/30 mb-2">
                    RESUME DEPLOY
                  </button>
                )}
                {(Object.keys(Difficulty) as Array<keyof typeof Difficulty>).map((diff) => (
                  <button key={diff} onClick={() => startGame(Difficulty[diff])} className="py-4 border border-amber-900 bg-amber-950/20 hover:bg-amber-500 hover:text-black hover:neon-border-gold transition-all text-xs font-black uppercase font-orbitron italic tracking-widest">
                    {diff} PROTOCOL
                  </button>
                ))}
              </div>
              <button onClick={() => setCurrentView('hub')} className="text-[10px] text-slate-600 font-retro uppercase tracking-widest hover:text-slate-400">Return to Hub</button>
            </div>
          </div>
        )}

        {gameOver && (
          <div className="fixed inset-0 bg-black/95 flex items-center justify-center z-50 p-4 backdrop-blur-md">
            <div className="w-full max-w-sm text-center space-y-6">
              <h2 className="text-4xl font-black italic tracking-tighter text-red-600 font-orbitron animate-pulse uppercase">Sync Terminated</h2>
              <div className="py-6 border-y border-red-900/40 bg-red-950/10 backdrop-blur-xl">
                <div className="text-[10px] text-red-400 font-retro uppercase tracking-widest mb-2">Final Performance</div>
                <div className="text-4xl font-black text-white font-orbitron tracking-tighter">{score.toLocaleString()}</div>
              </div>
              <div className="flex flex-col gap-2">
                <button onClick={resetGame} className="w-full py-5 bg-red-600 text-white text-sm font-black uppercase font-orbitron italic tracking-widest shadow-[0_0_20px_rgba(220,38,38,0.5)] border border-white/20">REBOOT SYNC</button>
                <button onClick={() => setCurrentView('hub')} className="w-full py-3 text-slate-500 text-[10px] font-retro uppercase tracking-widest">EXIT SYSTEM</button>
              </div>
            </div>
          </div>
        )}

        {paused && !gameOver && isGameStarted && (
          <div className="fixed inset-0 bg-black/80 flex items-center justify-center z-40 backdrop-blur-md">
            <div className="w-full max-w-sm text-center space-y-6">
              <h2 className="text-3xl font-black italic uppercase font-orbitron text-white">SYNC PAUSED</h2>
              <button onClick={() => setPaused(false)} className="w-full py-4 bg-amber-600 text-white text-xs font-black font-orbitron uppercase italic tracking-widest">RESUME MISSION</button>
              <button onClick={() => { resetGame(); setCurrentView('hub'); }} className="w-full py-4 border border-slate-800 text-slate-400 text-xs font-black font-orbitron uppercase italic tracking-widest">ABORT OP</button>
            </div>
          </div>
        )}
      </div>
    );
  }

  // Render Logic for other Games
  if (currentView === 'chess') {
    return (
      <ViewContainer>
        <ChessGame onExit={() => setCurrentView('hub')} onUpdateStats={handleUpdateChessStats} />
      </ViewContainer>
    );
  }

  if (currentView === 'snake') {
    return (
      <ViewContainer>
        <SnakeGame onExit={() => setCurrentView('hub')} onGameOver={handleSnakeGameOver} highScore={activeProfile?.snakeStats.bestScore || 0} />
      </ViewContainer>
    );
  }

  if (currentView === 'chat') {
    return (
      <ViewContainer>
        <ChatRoom userName={activeProfile?.name || 'Operator'} onExit={() => setCurrentView('hub')} />
      </ViewContainer>
    );
  }

  if (currentView === 'diamond-rush') {
    return (
      <ViewContainer>
        <DiamondRush onExit={() => setCurrentView('hub')} onGameOver={handleDiamondRushGameOver} highScore={activeProfile?.diamondRushStats?.bestScore || 0} />
      </ViewContainer>
    );
  }

  return null;
};

export default App;

import React, { useState, useEffect, useCallback } from 'react';
import { useTetris } from './hooks/useTetris';
import BoardView from './components/BoardView';
import Controls from './components/Controls';
import GameUI from './components/GameUI';
import AISuggestions from './components/AISuggestions';
import ChessGame from './components/ChessGame';
import SnakeGame from './components/SnakeGame';
import ChatRoom from './components/ChatRoom';
import DiamondRush from './components/DiamondRush';
import { Direction, Position, Board, Difficulty, UserProfile, GameType } from './types';

const STORAGE_KEY = 'tetris_prime_profiles_v3';

// [Fix] Moved ViewContainer outside of App to resolve TS error where children were reported as missing/required
interface ViewContainerProps {
  children: React.ReactNode;
}

const ViewContainer: React.FC<ViewContainerProps> = ({ children }) => (
  <div className="h-screen bg-[#050505] text-slate-200 flex flex-col items-center justify-center p-4 relative overflow-hidden">
    <div className="animated-grid opacity-30"></div>
    <div className="z-10 w-full flex flex-col items-center max-h-full">
      {children}
    </div>
  </div>
);

const App: React.FC = () => {
  const [profiles, setProfiles] = useState<UserProfile[]>([]);
  const [activeProfile, setActiveProfile] = useState<UserProfile | null>(null);
  const [currentView, setCurrentView] = useState<'profile-selector' | 'hub' | 'tetris' | 'chess' | 'snake' | 'chat' | 'diamond-rush'>('profile-selector');
  const [newProfileName, setNewProfileName] = useState('');
  const [isShaking, setIsShaking] = useState(false);

  const { 
    board, activePiece, nextPiece, score, highScore, level, lines, bombs, useBomb,
    gameOver, paused, difficulty, isGameStarted, setPaused, 
    move, rotate, hardDrop, resetGame, startGame, resumeGame, hasSave 
  } = useTetris(activeProfile);

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      setProfiles(JSON.parse(saved));
    }
  }, []);

  useEffect(() => {
    if (profiles.length > 0) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(profiles));
    }
  }, [profiles]);

  useEffect(() => {
    if (gameOver && activeProfile) {
      const updatedProfiles = profiles.map(p => {
        if (p.id === activeProfile.id) {
          return {
            ...p,
            tetrisStats: {
              bestScore: Math.max(p.tetrisStats.bestScore, score),
              totalLines: p.tetrisStats.totalLines + lines,
              gamesPlayed: p.tetrisStats.gamesPlayed + 1
            }
          };
        }
        return p;
      });
      setProfiles(updatedProfiles);
      setActiveProfile(updatedProfiles.find(p => p.id === activeProfile.id) || null);
    }
  }, [gameOver, score, lines, profiles, activeProfile]);

  const handleUpdateChessStats = (result: 'white' | 'black' | 'draw') => {
    if (!activeProfile) return;
    const updatedProfiles = profiles.map(p => {
      if (p.id === activeProfile.id) {
        const stats = { ...p.chessStats };
        if (result === 'white') stats.wins++;
        else if (result === 'black') stats.losses++;
        else stats.draws++;
        return { ...p, chessStats: stats };
      }
      return p;
    });
    setProfiles(updatedProfiles);
    setActiveProfile(updatedProfiles.find(p => p.id === activeProfile.id) || null);
  };

  const handleSnakeGameOver = (finalScore: number) => {
    if (!activeProfile) return;
    const updatedProfiles = profiles.map(p => {
      if (p.id === activeProfile.id) {
        return {
          ...p,
          snakeStats: {
            bestScore: Math.max(p.snakeStats.bestScore, finalScore),
            gamesPlayed: p.snakeStats.gamesPlayed + 1
          }
        };
      }
      return p;
    });
    setProfiles(updatedProfiles);
    setActiveProfile(updatedProfiles.find(p => p.id === activeProfile.id) || null);
  };

  const handleDiamondRushGameOver = (finalScore: number, finalDiamonds: number) => {
    if (!activeProfile) return;
    const updatedProfiles = profiles.map(p => {
      if (p.id === activeProfile.id) {
        return {
          ...p,
          diamondRushStats: {
            bestScore: Math.max(p.diamondRushStats?.bestScore || 0, finalScore),
            totalDiamonds: (p.diamondRushStats?.totalDiamonds || 0) + finalDiamonds,
            gamesPlayed: (p.diamondRushStats?.gamesPlayed || 0) + 1
          }
        };
      }
      return p;
    });
    setProfiles(updatedProfiles);
    setActiveProfile(updatedProfiles.find(p => p.id === activeProfile.id) || null);
  };

  const handleBombAction = useCallback(() => {
    if (bombs > 0 && isGameStarted && !paused && !gameOver) {
      useBomb();
      setIsShaking(true);
      setTimeout(() => setIsShaking(false), 500);
    }
  }, [bombs, isGameStarted, paused, gameOver, useBomb]);

  const handleCreateProfile = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newProfileName.trim()) return;
    const newProfile: UserProfile = {
      id: Date.now().toString(),
      name: newProfileName.trim(),
      tetrisStats: { bestScore: 0, totalLines: 0, gamesPlayed: 0 },
      chessStats: { wins: 0, losses: 0, draws: 0 },
      snakeStats: { bestScore: 0, gamesPlayed: 0 },
      diamondRushStats: { bestScore: 0, totalDiamonds: 0, gamesPlayed: 0 }
    };
    setProfiles(prev => [...prev, newProfile]);
    setActiveProfile(newProfile);
    setNewProfileName('');
    setCurrentView('hub');
  };

  const selectProfile = (p: UserProfile) => {
    setActiveProfile(p);
    setCurrentView('hub');
  };

  const logout = () => {
    setActiveProfile(null);
    setCurrentView('profile-selector');
    resetGame();
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (currentView !== 'tetris' || gameOver || !isGameStarted) return;
      switch (e.key) {
        case 'ArrowLeft': move(Direction.Left); break;
        case 'ArrowRight': move(Direction.Right); break;
        case 'ArrowDown': move(Direction.Down); break;
        case 'ArrowUp': rotate(); break;
        case ' ': hardDrop(); break;
        case 'b': handleBombAction(); break;
        case 'p': setPaused(!paused); break;
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [move, rotate, hardDrop, handleBombAction, paused, setPaused, gameOver, isGameStarted, currentView]);

  const checkCollisionHelper = (shape: number[][], pos: Position, b: Board) => {
    for (let y = 0; y < shape.length; y++) {
      for (let x = 0; x < shape[y].length; x++) {
        if (shape[y][x] !== 0) {
          const newX = pos.x + x;
          const newY = pos.y + y;
          if (newX < 0 || newX >= 10 || newY >= 20 || (newY >= 0 && b[newY][newX] !== null)) return true;
        }
      }
    }
    return false;
  };

  if (currentView === 'profile-selector') {
    return (
      <div className="h-screen bg-[#050505] text-slate-200 flex flex-col items-center justify-center p-6 relative overflow-hidden">
        <div className="animated-grid"></div>
        <div className="w-full max-md space-y-10 z-10">
          <div className="text-center space-y-4">
            <h1 className="text-5xl font-black tracking-tighter text-transparent bg-clip-text bg-gradient-to-b from-white to-amber-500 font-orbitron italic">PRIME ARCADE</h1>
            <div className="flex items-center justify-center gap-4">
               <div className="h-[1px] flex-1 bg-gradient-to-r from-transparent to-amber-500"></div>
               <p className="text-[10px] text-amber-400 font-retro tracking-widest uppercase">Initializing Core Systems</p>
               <div className="h-[1px] flex-1 bg-gradient-to-l from-transparent to-amber-500"></div>
            </div>
          </div>
          <div className="bg-slate-900/40 backdrop-blur-md border border-amber-500/20 p-6 rounded-lg shadow-2xl">
            <h2 className="text-[11px] font-bold text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2">
              <i className="fa-solid fa-users-gear text-amber-500"></i> Active Operators
            </h2>
            <div className="max-h-64 overflow-y-auto space-y-3 custom-scrollbar pr-1">
              {profiles.map(p => (
                <button key={p.id} onClick={() => selectProfile(p)} className="w-full p-4 bg-black/40 border border-slate-800 hover:border-amber-400/60 hover:bg-amber-500/10 group transition-all flex items-center justify-between">
                  <div className="text-left">
                    <div className="text-base font-black group-hover:text-amber-400 font-orbitron uppercase">{p.name}</div>
                    <div className="text-[9px] text-slate-500 uppercase tracking-widest mt-1">EXP: {p.tetrisStats.gamesPlayed + p.chessStats.wins + p.snakeStats.gamesPlayed + (p.diamondRushStats?.gamesPlayed || 0)} Units</div>
                  </div>
                  <i className="fa-solid fa-play text-[12px] text-slate-700 group-hover:text-amber-400 animate-pulse"></i>
                </button>
              ))}
              {profiles.length === 0 && <div className="text-center py-10 border border-dashed border-slate-800 rounded text-[10px] text-slate-600 font-retro">NO USERS DETECTED</div>}
            </div>
            <form onSubmit={handleCreateProfile} className="mt-8 pt-6 border-t border-slate-800 space-y-4">
              <h2 className="text-[11px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2">
                <i className="fa-solid fa-plus text-amber-500"></i> Register New Pilot
              </h2>
              <div className="flex gap-2">
                <input type="text" placeholder="INPUT CALLSIGN" value={newProfileName} onChange={(e) => setNewProfileName(e.target.value.toUpperCase())} maxLength={12} className="flex-1 bg-black/60 border border-slate-800 px-4 py-3 text-sm font-orbitron font-bold tracking-widest focus:border-amber-500 focus:outline-none placeholder:text-slate-700 text-amber-400" />
                <button type="submit" className="bg-amber-600 text-white px-6 py-3 text-xs font-black uppercase tracking-widest hover:bg-amber-500 active:scale-95 shadow-[0_0_20px_rgba(245,158,11,0.4)]">LINK</button>
              </div>
            </form>
          </div>
        </div>
      </div>
    );
  }

  if (currentView === 'hub') {
    return (
      <div className="h-screen bg-[#050505] text-slate-200 flex flex-col items-center justify-start p-6 relative overflow-hidden">
        <div className="animated-grid"></div>
        <div className="w-full max-w-lg space-y-8 z-10 pt-4 overflow-y-auto custom-scrollbar">
          <header className="flex justify-between items-center bg-slate-900/40 backdrop-blur-md p-4 border-l-4 border-amber-500 rounded-r-lg shadow-xl shrink-0">
            <div className="space-y-1">
              <h1 className="text-2xl font-black italic tracking-tighter text-white font-orbitron uppercase">COMMAND HUB</h1>
              <div className="flex items-center gap-3">
                <div className="flex gap-1"><span className="w-2 h-2 bg-green-500 rounded-full animate-ping"></span><span className="w-2 h-2 bg-green-500 rounded-full"></span></div>
                <span className="text-[10px] text-amber-400 font-retro uppercase">USER: {activeProfile?.name}</span>
              </div>
            </div>
            <button onClick={logout} className="text-[10px] font-black text-slate-500 hover:text-red-500 font-orbitron uppercase tracking-widest px-4 py-2 border border-slate-800 hover:border-red-500/40 transition-all">TERMINATE</button>
          </header>
          <div className="grid grid-cols-2 gap-4 pb-10">
            <button onClick={() => setCurrentView('tetris')} className="group relative overflow-hidden aspect-square border border-slate-800 hover:neon-border-gold transition-all flex flex-col p-6 bg-slate-950/80 hover:bg-amber-500/5 rounded-xl">
              <div className="absolute top-4 right-4 text-[8px] font-retro text-amber-500/40">THREAT: HIGH</div>
              <i className="fa-solid fa-shapes text-5xl mb-auto text-amber-500/20 group-hover:text-amber-500 transition-all group-hover:scale-110"></i>
              <div className="text-left"><h3 className="text-xl font-black tracking-tighter text-white font-orbitron uppercase italic">TETRIS PRIME</h3><div className="mt-2 text-[9px] font-bold text-amber-400 font-retro">BEST: {activeProfile?.tetrisStats.bestScore}</div></div>
            </button>
            <button onClick={() => setCurrentView('chess')} className="group relative overflow-hidden aspect-square border border-slate-800 hover:neon-border-purple transition-all flex flex-col p-6 bg-slate-950/80 hover:bg-purple-500/5 rounded-xl">
              <div className="absolute top-4 right-4 text-[8px] font-retro text-purple-500/40">THREAT: EXTREME</div>
              <i className="fa-solid fa-chess-knight text-5xl mb-auto text-purple-500/20 group-hover:text-purple-500 transition-all group-hover:scale-110"></i>
              <div className="text-left"><h3 className="text-xl font-black tracking-tighter text-white font-orbitron uppercase italic">CHESS PRIME</h3><div className="mt-2 text-[9px] font-bold text-purple-400 font-retro">WINS: {activeProfile?.chessStats.wins}</div></div>
            </button>
            <button onClick={() => setCurrentView('snake')} className="group relative overflow-hidden aspect-square border border-slate-800 hover:neon-border-pink transition-all flex flex-col p-6 bg-slate-950/80 hover:bg-pink-500/5 rounded-xl">
              <div className="absolute top-4 right-4 text-[8px] font-retro text-pink-500/40">THREAT: MED</div>
              <i className="fa-solid fa-worm text-5xl mb-auto text-pink-500/20 group-hover:text-pink-500 transition-all group-hover:scale-110"></i>
              <div className="text-left"><h3 className="text-xl font-black tracking-tighter text-white font-orbitron uppercase italic">SNAKE PRIME</h3><div className="mt-2 text-[9px] font-bold text-pink-400 font-retro">BEST: {activeProfile?.snakeStats.bestScore}</div></div>
            </button>
            <button onClick={() => setCurrentView('diamond-rush')} className="group relative overflow-hidden aspect-square border border-slate-800 hover:neon-border-gold transition-all flex flex-col p-6 bg-slate-950/80 hover:bg-amber-500/5 rounded-xl">
               <div className="absolute top-4 right-4 text-[8px] font-retro text-amber-500/40">STATUS: FAST</div>
              <i className="fa-solid fa-gem text-5xl mb-auto text-amber-500/20 group-hover:text-amber-400 transition-all group-hover:scale-110"></i>
              <div className="text-left"><h3 className="text-xl font-black tracking-tighter text-white font-orbitron uppercase italic">DIAMOND RUSH</h3><div className="mt-2 text-[9px] font-bold text-amber-400 font-retro">BEST: {activeProfile?.diamondRushStats?.bestScore || 0}</div></div>
            </button>
          </div>
          <footer className="pt-8 pb-4 border-t border-slate-900 flex justify-between items-center opacity-60 shrink-0"><div className="text-[8px] text-slate-500 font-retro uppercase">SYSTEM: V3.5.0_GOLD</div><div className="text-[8px] text-amber-500 font-retro uppercase animate-pulse">CORE MODULES SYNCED</div></footer>
        </div>
      </div>
    );
  }

  // Tetris View
  if (currentView === 'tetris') {
    return (
