              </div>
              <div className="flex flex-col gap-2">
                <button onClick={resetGame} className="w-full py-5 bg-red-600 text-white text-sm font-black uppercase font-orbitron italic tracking-widest shadow-[0_0_20px_rgba(220,38,38,0.5)] border border-white/20">REBOOT SYNC</button>
