import { GoogleGenAI, Type } from "@google/genai";
import { Board, Tetromino } from "../types";

export async function getGameAdvice(board: Board, nextPiece: Tetromino, score: number, level: number) {
  // [Fix] Instantiate GoogleGenAI right before making an API call to ensure use of correct configuration
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Convert board to a simple string representation for the AI
  const boardStr = board.map(row => 
    row.map(cell => cell ? 'X' : '.').join('')
  ).join('\n');

  const prompt = `
    You are a world-class Tetris Grandmaster. Analyze this board state and provide strategic advice.

    Current Board:
    ${boardStr}

    Next Piece: ${nextPiece.id}
    Current Score: ${score}
    Level: ${level}

    Provide 2-3 brief, actionable tips to improve my current position or score. Keep it encouraging and technical.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            advice: {
              type: Type.ARRAY,
              items: { type: Type.STRING },
              description: "A list of 2-3 strategic tips."
            },
            riskLevel: {
              type: Type.STRING,
              description: "Low, Medium, or High risk current state."
            }
          },
          required: ["advice", "riskLevel"]
        }
      },
    });

    if (response.text) {
      return JSON.parse(response.text);
    }
    return null;
  } catch (error) {
    console.error("Gemini AI error:", error);
    return null;
  }
}

import React, { useState, useEffect, useCallback } from 'react';
import { Chess, Square, Move } from 'chess.js';
import { GoogleGenAI } from "@google/genai";

interface ChessGameProps {
  onExit: () => void;
  onUpdateStats: (winner: 'white' | 'black' | 'draw') => void;
}

const ChessGame: React.FC<ChessGameProps> = ({ onExit, onUpdateStats }) => {
  const [game, setGame] = useState(new Chess());
  const [selectedSquare, setSelectedSquare] = useState<Square | null>(null);
  const [validMoves, setValidMoves] = useState<string[]>([]);
  const [isAiThinking, setIsAiThinking] = useState(false);
  const [status, setStatus] = useState<string>('Your Turn (White)');

  const makeMove = useCallback((move: string | { from: string; to: string; promotion?: string }) => {
    try {
      const result = game.move(move);
      if (result) {
        setGame(new Chess(game.fen()));
        return true;
      }
    } catch (e) {
      return false;
    }
    return false;
  }, [game]);

  const requestAiMove = async (currentFen: string) => {
    setIsAiThinking(true);
    setStatus('AI Grandmaster is thinking...');

    // [Fix] Instantiate GoogleGenAI right before making an API call to ensure fresh configuration
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `
      You are a Chess Grandmaster. Analyze this chess position (FEN) and provide the best move for Black.
      Current Position: ${currentFen}

      Respond ONLY in JSON format with two keys:
      - "move": The move in Standard Algebraic Notation (e.g., "Nf3") or UCI format (e.g., "e2e4").
      - "analysis": A very brief comment (max 10 words) on why this move is good.
    `;

    try {
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: prompt,
        config: { responseMimeType: "application/json" }
      });

      const data = JSON.parse(response.text || '{}');
      if (data.move) {
        const success = makeMove(data.move);
        if (!success) {
          // Fallback to a random legal move if AI hallucinates
          const moves = game.moves();
          if (moves.length > 0) {
            makeMove(moves[Math.floor(Math.random() * moves.length)]);
          }
        }
      }
    } catch (error) {
      console.error("AI Chess Error:", error);
      // Fallback
      const moves = game.moves();
      if (moves.length > 0) {
        makeMove(moves[Math.floor(Math.random() * moves.length)]);
      }
    } finally {
      setIsAiThinking(false);
      setStatus('Your Turn (White)');
    }
  };

  useEffect(() => {
    if (game.isGameOver()) {
      let winnerStatus = 'Game Over';
      if (game.isCheckmate()) {
        const winner = game.turn() === 'w' ? 'black' : 'white';
        winnerStatus = `Checkmate! ${winner.toUpperCase()} wins.`;
        onUpdateStats(winner);
      } else if (game.isDraw()) {
        winnerStatus = 'Draw!';
        onUpdateStats('draw');
      }
      setStatus(winnerStatus);
    } else if (game.turn() === 'b' && !isAiThinking) {
      requestAiMove(game.fen());
    }
  }, [game, isAiThinking, onUpdateStats]);

  const onSquareClick = (square: Square) => {
    if (game.turn() !== 'w' || game.isGameOver()) return;

    if (selectedSquare === square) {
      setSelectedSquare(null);
      setValidMoves([]);
      return;
    }

    // Check if clicked square is a valid destination for selected square
    if (selectedSquare) {
      const move = makeMove({ from: selectedSquare, to: square, promotion: 'q' });
      if (move) {
        setSelectedSquare(null);
        setValidMoves([]);
        return;
      }
    }

    // Otherwise, select the square if it's a piece of current turn
    const piece = game.get(square);
    if (piece && piece.color === 'w') {
      setSelectedSquare(square);
      setValidMoves(game.moves({ square, verbose: true }).map(m => m.to));
    } else {
      setSelectedSquare(null);
      setValidMoves([]);
    }
  };

  const board = [];
  const files = ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h'];
  const ranks = ['8', '7', '6', '5', '4', '3', '2', '1'];

  for (let r = 0; r < 8; r++) {
    for (let f = 0; f < 8; f++) {
      const square = (files[f] + ranks[r]) as Square;
      const piece = game.get(square);
      const isDark = (r + f) % 2 === 1;
      const isSelected = selectedSquare === square;
      const isValid = validMoves.includes(square);

      board.push(
        <div 
          key={square}
          onClick={() => onSquareClick(square)}
          className={`relative aspect-square flex items-center justify-center text-3xl cursor-pointer transition-colors
            ${isDark ? 'chess-square-dark' : 'chess-square-light'}
            ${isSelected ? 'chess-square-selected' : ''}
            ${isValid ? 'chess-square-valid' : ''}
          `}
        >
          {piece && (
            <span className={`${piece.color === 'w' ? 'text-white' : 'text-slate-500'} select-none drop-shadow-md`}>
              {getPieceIcon(piece.type, piece.color)}
            </span>
          )}
          {f === 0 && <span className="absolute top-0.5 left-0.5 text-[8px] text-slate-600 font-bold">{ranks[r]}</span>}
          {r === 7 && <span className="absolute bottom-0.5 right-0.5 text-[8px] text-slate-600 font-bold">{files[f]}</span>}
        </div>
      );
    }
  }

  function getPieceIcon(type: string, color: string) {
    const icons: Record<string, string> = {
      p: '♟', r: '♜', n: '♞', b: '♝', q: '♛', k: '♚'
    };
    return icons[type];
  }

  return (
    <div className="flex flex-col items-center gap-6 w-full max-w-md animate-in fade-in zoom-in duration-300">
      <div className="w-full flex justify-between items-center px-2">
        <div className="flex flex-col">
          <h2 className="text-xl font-bold tracking-tighter text-white uppercase">Chess Prime</h2>
          <span className="text-[8px] text-slate-500 uppercase tracking-widest">{status}</span>
        </div>
        <button onClick={onExit} className="px-3 py-1 border border-slate-800 text-[10px] uppercase font-bold text-slate-400 hover:text-white transition-colors">
          Exit Room
        </button>
      </div>

      <div className="w-full aspect-square grid grid-cols-8 border-4 border-slate-800 shadow-2xl rounded-sm overflow-hidden">
        {board}
      </div>

      <div className="w-full flex gap-2">
        <div className="flex-1 bg-slate-900/50 p-4 border border-slate-800 text-center">
          <div className="text-[8px] text-slate-500 uppercase tracking-widest mb-1">FEN State</div>
          <div className="text-[10px] font-mono text-slate-400 truncate">{game.fen()}</div>
        </div>
        <button 
          onClick={() => setGame(new Chess())}
          className="px-6 bg-white text-black font-bold text-[10px] uppercase tracking-widest hover:bg-slate-200 transition-colors"
        >
          Reset
        </button>
      </div>

      {isAiThinking && (
        <div className="fixed inset-0 bg-black/20 flex items-center justify-center z-50 pointer-events-none backdrop-blur-[1px]">
          <div className="bg-black/80 border border-slate-800 p-4 flex items-center gap-3">
            <i className="fa-solid fa-brain text-blue-400 animate-pulse"></i>
            <span className="text-xs uppercase tracking-widest font-bold">Neural Engine Analysis...</span>
          </div>
        </div>
      )}
    </div>
  );
};

export default ChessGame;

import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI, GenerateContentResponse } from "@google/genai";

interface Message {
  role: 'user' | 'model';
  text: string;
  id: string;
}

interface ChatRoomProps {
  userName: string;
  onExit: () => void;
}

const ChatRoom: React.FC<ChatRoomProps> = ({ userName, onExit }) => {
  const [messages, setMessages] = useState<Message[]>([
    { role: 'model', text: `Greetings, Operator ${userName}. Neural connection established. How can I assist your gaming session today?`, id: 'init' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  // [Fix] Maintain chat session via a lazy initializer to follow "no top-level/early instantiation" rule
  const chatInstanceRef = useRef<any>(null);

  const getChat = () => {
    if (!chatInstanceRef.current) {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      chatInstanceRef.current = ai.chats.create({
        model: 'gemini-3-flash-preview',
        config: {
          systemInstruction: `You are the Prime Arcade AI, a high-tech gaming assistant and strategist. 
          You speak with a professional, slightly cybernetic, and encouraging tone. 
          You know about Tetris, Chess, and Snake. 
          Refer to the user as "Operator ${userName}". 
          Keep responses relatively concise but helpful.`
        }
      });
    }
    return chatInstanceRef.current;
  };

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleSend = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isTyping) return;

    const userMsg: Message = { role: 'user', text: input.trim(), id: Date.now().toString() };
    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setIsTyping(true);

    try {
      const modelMsgId = (Date.now() + 1).toString();
      let accumulatedText = "";

      setMessages(prev => [...prev, { role: 'model', text: "", id: modelMsgId }]);

      const chat = getChat();
      const streamResponse = await chat.sendMessageStream({ message: userMsg.text });

      for await (const chunk of streamResponse) {
        // [Fix] Cast chunk to GenerateContentResponse and use property access
        const c = chunk as GenerateContentResponse;
        accumulatedText += c.text;
        setMessages(prev => prev.map(m => 
          m.id === modelMsgId ? { ...m, text: accumulatedText } : m
        ));
      }
    } catch (error) {
      console.error("Chat error:", error);
      setMessages(prev => [...prev, { 
        role: 'model', 
        text: "System Error: Neural link interrupted. Please retry communication.", 
        id: 'err-' + Date.now() 
      }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="flex flex-col h-full w-full max-w-md bg-slate-950 border border-slate-800 shadow-2xl animate-in fade-in zoom-in duration-300">
      <header className="p-4 border-b border-slate-800 flex justify-between items-center bg-black/40">
        <div className="flex flex-col">
          <h2 className="text-sm font-bold tracking-tighter text-cyan-400 uppercase font-orbitron flex items-center gap-2">
            <span className="w-2 h-2 bg-cyan-500 rounded-full animate-pulse"></span>
            AI COMMS LINK
          </h2>
          <span className="text-[8px] text-slate-500 uppercase tracking-widest">Secure Channel Active</span>
        </div>
        <button 
          onClick={onExit}
          className="px-3 py-1 border border-slate-800 text-[9px] font-bold text-slate-500 hover:text-white uppercase transition-colors"
        >
          Exit Link
        </button>
      </header>

      <div 
        ref={scrollRef}
        className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar"
      >
        {messages.map((msg) => (
          <div 
            key={msg.id} 
            className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div className={`max-w-[85%] p-3 rounded-sm text-[11px] leading-relaxed shadow-lg transition-all
              ${msg.role === 'user' 
                ? 'bg-slate-800 text-white border-l-2 border-blue-500' 
                : 'bg-black/60 text-cyan-50 border-l-2 border-cyan-500 font-medium'
              }`}
            >
              <div className="text-[7px] uppercase font-bold tracking-widest mb-1 opacity-40">
                {msg.role === 'user' ? userName : 'AI ASSISTANT'}
              </div>
              <p className="whitespace-pre-wrap">{msg.text || (msg.role === 'model' && isTyping ? '...' : '')}</p>
            </div>
          </div>
        ))}
        {isTyping && messages[messages.length-1].text === "" && (
          <div className="flex justify-start">
             <div className="bg-black/60 p-3 border-l-2 border-cyan-500 text-cyan-400 animate-pulse text-[10px]">
               Analyzing...
             </div>
          </div>
        )}
      </div>

      <form 
        onSubmit={handleSend}
        className="p-4 bg-black/60 border-t border-slate-800 flex gap-2"
      >
        <input 
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder="TYPE MESSAGE..."
          className="flex-1 bg-slate-900 border border-slate-800 px-4 py-2 text-[10px] uppercase font-bold tracking-wider text-white focus:outline-none focus:border-cyan-500 transition-colors"
        />
        <button 
          type="submit"
          disabled={isTyping}
          className={`px-4 py-2 text-[10px] font-bold uppercase tracking-widest transition-all
            ${isTyping 
              ? 'bg-slate-800 text-slate-600' 
              : 'bg-cyan-600 text-white hover:bg-cyan-500 active:scale-95 shadow-[0_0_15px_rgba(8,145,178,0.3)]'}
          `}
        >
          Send
        </button>
      </form>
    </div>
  );
};

