import React, { useState, useEffect, useCallback } from 'react';

interface MemoryMatchProps {
  onExit: () => void;
  onGameOver: (time: number) => void;
  bestTime: number;
}

interface Card {
  id: number;
  icon: string;
  color: string;
  isFlipped: boolean;
  isMatched: boolean;
}

const ICONS = [
  { icon: 'fa-microchip', color: 'text-cyan-400' },
  { icon: 'fa-bolt', color: 'text-yellow-400' },
  { icon: 'fa-atom', color: 'text-purple-400' },
  { icon: 'fa-dna', color: 'text-green-400' },
  { icon: 'fa-brain', color: 'text-pink-400' },
  { icon: 'fa-satellite', color: 'text-blue-400' },
  { icon: 'fa-user-secret', color: 'text-orange-400' },
  { icon: 'fa-vr-cardboard', color: 'text-red-400' },
];

const MemoryMatch: React.FC<MemoryMatchProps> = ({ onExit, onGameOver, bestTime }) => {
  const [cards, setCards] = useState<Card[]>([]);
  const [flipped, setFlipped] = useState<number[]>([]);
  const [moves, setMoves] = useState(0);
  const [timer, setTimer] = useState(0);
  const [isStarted, setIsStarted] = useState(false);
  const [isComplete, setIsComplete] = useState(false);

  const initGame = useCallback(() => {
    const deck: Card[] = [];
    [...ICONS, ...ICONS].sort(() => Math.random() - 0.5).forEach((item, index) => {
      deck.push({
        id: index,
        icon: item.icon,
        color: item.color,
        isFlipped: false,
        isMatched: false,
      });
    });
    setCards(deck);
    setFlipped([]);
    setMoves(0);
    setTimer(0);
    setIsStarted(false);
    setIsComplete(false);
  }, []);

  useEffect(() => {
    initGame();
  }, [initGame]);

  useEffect(() => {
    let interval: number;
    if (isStarted && !isComplete) {
      interval = window.setInterval(() => {
        setTimer(t => t + 1);
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isStarted, isComplete]);

  const handleCardClick = (id: number) => {
    if (flipped.length === 2 || cards[id].isFlipped || cards[id].isMatched || isComplete) return;

    if (!isStarted) setIsStarted(true);

    const newCards = [...cards];
    newCards[id].isFlipped = true;
    setCards(newCards);

    const newFlipped = [...flipped, id];
    setFlipped(newFlipped);

    if (newFlipped.length === 2) {
      setMoves(m => m + 1);
      const [first, second] = newFlipped;

      if (cards[first].icon === cards[second].icon) {
        // Match found
        setTimeout(() => {
          setCards(prev => prev.map((card, i) => 
            i === first || i === second ? { ...card, isMatched: true } : card
          ));
          setFlipped([]);

          // Check for completion
          setCards(prev => {
            const allMatched = prev.every(c => c.isMatched || c.id === first || c.id === second);
            if (allMatched) {
              setIsComplete(true);
              onGameOver(timer);
            }
            return prev;
          });
        }, 500);
      } else {
        // No match
        setTimeout(() => {
          setCards(prev => prev.map((card, i) => 
            i === first || i === second ? { ...card, isFlipped: false } : card
          ));
          setFlipped([]);
        }, 1000);
      }
    }
  };

  const formatTime = (s: number) => {
    const mins = Math.floor(s / 60);
    const secs = s % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="flex flex-col items-center gap-6 w-full max-w-md animate-in fade-in zoom-in duration-300">
      <div className="w-full flex justify-between items-center px-2">
        <div className="flex flex-col">
          <h2 className="text-xl font-black italic tracking-tighter text-purple-400 font-orbitron uppercase">MEMORY PRIME</h2>
          <div className="flex gap-3">
             <span className="text-[8px] text-slate-500 font-retro uppercase">Best: {bestTime === 0 ? '--' : formatTime(bestTime)}</span>
             <span className="text-[8px] text-purple-500 font-retro uppercase tracking-widest">Time: {formatTime(timer)}</span>
             <span className="text-[8px] text-purple-500 font-retro uppercase tracking-widest">Moves: {moves}</span>
          </div>
        </div>
        <button onClick={onExit} className="px-3 py-1 border border-slate-800 text-[10px] font-black font-orbitron uppercase text-slate-400 hover:text-white transition-all">
          EXIT
        </button>
      </div>

      <div className="grid grid-cols-4 gap-2 w-full aspect-square">
        {cards.map((card) => (
          <div 
            key={card.id}
            onClick={() => handleCardClick(card.id)}
            className={`relative perspective-1000 cursor-pointer transition-all duration-500 h-full w-full
              ${card.isFlipped || card.isMatched ? 'rotate-y-180' : ''}`}
          >
            <div className={`absolute inset-0 w-full h-full preserve-3d transition-transform duration-500 
              ${card.isFlipped || card.isMatched ? 'scale-100' : 'scale-95'}`}>

              {/* Card Back */}
              <div className={`absolute inset-0 backface-hidden bg-slate-900 border-2 border-slate-800 flex items-center justify-center rounded-lg shadow-xl
                ${!card.isFlipped && !card.isMatched ? 'opacity-100' : 'opacity-0'}`}>
                <div className="w-6 h-6 border-2 border-purple-500/30 rounded-full animate-pulse" />
              </div>

              {/* Card Front */}
              <div className={`absolute inset-0 backface-hidden rotate-y-180 bg-black border-2 flex items-center justify-center rounded-lg shadow-2xl
                ${card.isMatched ? 'border-green-500/50 opacity-60' : 'border-purple-500'}
                ${card.isFlipped || card.isMatched ? 'opacity-100' : 'opacity-0'}`}>
                <i className={`fa-solid ${card.icon} ${card.color} text-2xl drop-shadow-[0_0_8px_currentColor]`} />
              </div>
            </div>
          </div>
        ))}
      </div>

      {isComplete && (
        <div className="fixed inset-0 bg-black/90 flex flex-col items-center justify-center z-50 backdrop-blur-md p-6 text-center">
          <h3 className="text-3xl font-black text-purple-400 font-orbitron italic uppercase mb-2">NEURAL SYNC COMPLETE</h3>
          <p className="text-[10px] text-slate-400 font-retro uppercase tracking-widest mb-8">All patterns matched in {formatTime(timer)}</p>
          <div className="flex flex-col gap-2 w-full max-w-xs">
            <button 
              onClick={initGame}
              className="w-full py-4 bg-purple-600 text-white font-black font-orbitron uppercase italic tracking-widest hover:bg-purple-500 transition-all shadow-[0_0_20px_rgba(168,85,247,0.4)]"
            >
              RESET MODULE
            </button>
            <button 
              onClick={onExit}
              className="w-full py-2 text-slate-500 text-[8px] font-retro uppercase"
            >
              EXIT TO HUB
            </button>
          </div>
        </div>
      )}

      <style>{`
        .perspective-1000 { perspective: 1000px; }
        .preserve-3d { transform-style: preserve-3d; }
        .backface-hidden { backface-visibility: hidden; }
        .rotate-y-180 { transform: rotateY(180deg); }
      `}</style>
    </div>
  );
};

export default MemoryMatch;

import React, { useState, useEffect, useCallback, useRef } from 'react';

interface VoidShooterProps {
  onExit: () => void;
  onGameOver: (score: number) => void;
  highScore: number;
}

const VOID_HEIGHT = 500;
const VOID_WIDTH = 340;

interface Entity {
  id: number;
  x: number;
  y: number;
  width: number;
  height: number;
}

interface Bullet extends Entity {
  speed: number;
}

interface Enemy extends Entity {
  speed: number;
  color: string;
}

const VoidShooter: React.FC<VoidShooterProps> = ({ onExit, onGameOver, highScore }) => {
  const [playerX, setPlayerX] = useState(VOID_WIDTH / 2 - 15);
  const [bullets, setBullets] = useState<Bullet[]>([]);
  const [enemies, setEnemies] = useState<Enemy[]>([]);
  const [score, setScore] = useState(0);
  const [isGameOver, setIsGameOver] = useState(false);
  const [isPaused, setIsPaused] = useState(false);

  const requestRef = useRef<number | null>(null);
  const lastTimeRef = useRef<number>(0);
  const enemyTimerRef = useRef<number>(0);

  const movePlayer = (dir: 'left' | 'right') => {
    if (isGameOver || isPaused) return;
    setPlayerX(prev => {
      const step = 20;
      const next = dir === 'left' ? prev - step : prev + step;
      return Math.max(0, Math.min(VOID_WIDTH - 30, next));
    });
  };

  const shoot = useCallback(() => {
    if (isGameOver || isPaused) return;
    setBullets(prev => [
      ...prev,
      { id: Date.now(), x: playerX + 13, y: VOID_HEIGHT - 40, width: 4, height: 10, speed: 7 }
    ]);
  }, [playerX, isGameOver, isPaused]);

  const update = useCallback((time: number) => {
    if (isPaused || isGameOver) return;

    const deltaTime = time - lastTimeRef.current;
    lastTimeRef.current = time;

    // Bullet movement
    setBullets(prev => prev.map(b => ({ ...b, y: b.y - b.speed })).filter(b => b.y > -10));

    // Enemy spawning
    enemyTimerRef.current += deltaTime;
    if (enemyTimerRef.current > 800) {
      setEnemies(prev => [
        ...prev,
        { 
          id: Date.now() + Math.random(), 
          x: Math.random() * (VOID_WIDTH - 30), 
          y: -40, 
          width: 30, 
          height: 30, 
          speed: 2 + (score / 1000),
          color: ['bg-red-500', 'bg-orange-500', 'bg-blue-500'][Math.floor(Math.random() * 3)]
        }
      ]);
      enemyTimerRef.current = 0;
    }

    // Enemy movement
    setEnemies(prev => {
      const moved = prev.map(e => ({ ...e, y: e.y + e.speed }));

      // Collision check: Enemy vs Player
      if (moved.some(e => e.y + e.height > VOID_HEIGHT - 40 && e.x + e.width > playerX && e.x < playerX + 30)) {
        setIsGameOver(true);
        onGameOver(score);
        return moved;
      }

      // Check if enemy passed bottom
      if (moved.some(e => e.y > VOID_HEIGHT)) {
         setIsGameOver(true);
         onGameOver(score);
         return moved;
      }

      return moved;
    });

    // Collision check: Bullet vs Enemy
    setBullets(prevBullets => {
      let nextBullets = [...prevBullets];
      setEnemies(prevEnemies => {
        let nextEnemies = [...prevEnemies];

        nextBullets = nextBullets.filter(b => {
          const hitIdx = nextEnemies.findIndex(e => 
            b.x < e.x + e.width && 
            b.x + b.width > e.x && 
            b.y < e.y + e.height && 
            b.y + b.height > e.y
          );

          if (hitIdx > -1) {
            nextEnemies.splice(hitIdx, 1);
            setScore(s => s + 100);
            return false; // Remove bullet
          }
          return true;
        });

        nextEnemies = nextEnemies;
        return nextEnemies;
      });
      return nextBullets;
    });

    requestRef.current = requestAnimationFrame(update);
  }, [isPaused, isGameOver, playerX, score, onGameOver]);

  useEffect(() => {
    requestRef.current = requestAnimationFrame(update);
    return () => { if (requestRef.current) cancelAnimationFrame(requestRef.current); };
  }, [update]);

  // Global keys
  useEffect(() => {
    const handleKey = (e: KeyboardEvent) => {
      if (e.key === 'ArrowLeft') movePlayer('left');
      if (e.key === 'ArrowRight') movePlayer('right');
      if (e.key === ' ') shoot();
    };
    window.addEventListener('keydown', handleKey);
    return () => window.removeEventListener('keydown', handleKey);
  }, [playerX, isGameOver, isPaused, shoot]);

  return (
    <div className="flex flex-col items-center gap-4 w-full max-w-md animate-in fade-in zoom-in duration-300">
      <div className="w-full flex justify-between items-center px-2">
        <div className="flex flex-col">
          <h2 className="text-xl font-black italic tracking-tighter text-red-500 font-orbitron uppercase">VOID PRIME</h2>
          <div className="flex gap-3">
             <span className="text-[8px] text-slate-500 font-retro uppercase">Best: {highScore}</span>
             <span className="text-[8px] text-red-500 font-retro uppercase tracking-widest">Score: {score}</span>
          </div>
        </div>
        <button onClick={onExit} className="px-3 py-1 border border-slate-800 text-[10px] font-black font-orbitron uppercase text-slate-400 hover:text-white transition-all">
          EXIT
        </button>
      </div>

      <div 
        className="relative bg-black border-4 border-slate-900 rounded-lg overflow-hidden shadow-2xl"
        style={{ width: VOID_WIDTH, height: VOID_HEIGHT }}
      >
        {/* Background Stars */}
        <div className="absolute inset-0 opacity-20 bg-[radial-gradient(circle,white_1px,transparent_1px)] bg-[size:32px_32px]" />

        {/* Player */}
        <div 
          className="absolute bottom-4 bg-white shadow-[0_0_15px_white] transition-all duration-100"
          style={{ left: playerX, width: 30, height: 20, clipPath: 'polygon(50% 0%, 0% 100%, 100% 100%)' }}
        />

        {/* Bullets */}
        {bullets.map(b => (
          <div 
            key={b.id} 
            className="absolute bg-cyan-400 shadow-[0_0_10px_rgba(34,211,238,1)]"
            style={{ left: b.x, top: b.y, width: b.width, height: b.height }}
          />
        ))}

        {/* Enemies */}
        {enemies.map(e => (
          <div 
            key={e.id} 
            className={`absolute ${e.color} shadow-lg border border-white/20`}
            style={{ left: e.x, top: e.y, width: e.width, height: e.height, transform: 'rotate(45deg)' }}
          />
        ))}

        {isGameOver && (
          <div className="absolute inset-0 bg-black/90 flex flex-col items-center justify-center z-50 backdrop-blur-md p-6 text-center">
            <h3 className="text-3xl font-black text-red-600 font-orbitron italic uppercase mb-2">HULL BREACH</h3>
            <p className="text-[10px] text-slate-400 font-retro uppercase tracking-widest mb-8">Ship Destroyed at Score {score}</p>
            <button 
              onClick={() => {
                setEnemies([]);
                setBullets([]);
                setScore(0);
                setIsGameOver(false);
              }}
              className="w-full py-4 bg-red-600 text-white font-black font-orbitron uppercase italic tracking-widest hover:bg-red-500 transition-all shadow-[0_0_20px_rgba(220,38,38,0.4)]"
            >
              DEPLOY REPLACEMENT
            </button>
          </div>
        )}
      </div>

      {/* Touch Controls */}
      <div className="flex gap-4 w-full max-w-[280px] mt-2">
         <button 
           onMouseDown={() => movePlayer('left')}
           onTouchStart={() => movePlayer('left')}
           className="flex-1 h-14 border-2 border-slate-800 bg-slate-900/40 text-white flex items-center justify-center rounded-xl active:bg-red-600 transition-all"
         >
           <i className="fa-solid fa-arrow-left" />
         </button>
         <button 
           onClick={shoot}
           className="flex-1 h-14 border-2 border-red-500 bg-red-950/20 text-red-500 flex items-center justify-center rounded-xl active:bg-red-500 active:text-white transition-all shadow-[0_0_15px_rgba(220,38,38,0.2)]"
         >
           <i className="fa-solid fa-crosshairs text-xl" />
         </button>
         <button 
           onMouseDown={() => movePlayer('right')}
           onTouchStart={() => movePlayer('right')}
           className="flex-1 h-14 border-2 border-slate-800 bg-slate-900/40 text-white flex items-center justify-center rounded-xl active:bg-red-600 transition-all"
         >
           <i className="fa-solid fa-arrow-right" />
         </button>
      </div>
    </div>
  );
};

export default VoidShooter;

import React, { useState, useEffect, useCallback } from 'react';
import { useTetris } from './hooks/useTetris';
import BoardView from './components/BoardView';
import Controls from './components/Controls';
import GameUI from './components/GameUI';
import AISuggestions from './components/AISuggestions';
import ChessGame from './components/ChessGame';
import SnakeGame from './components/SnakeGame';
import ChatRoom from './components/ChatRoom';
import DiamondRush from './components/DiamondRush';
import MemoryMatch from './components/MemoryMatch';
import VoidShooter from './components/VoidShooter';
import { Direction, Position, Board, Difficulty, UserProfile } from './types';

const STORAGE_KEY = 'prime_arcade_profiles_v5';

interface ViewContainerProps {
  children: React.ReactNode;
}

const ViewContainer: React.FC<ViewContainerProps> = ({ children }) => (
  <div className="h-screen bg-[#050505] text-slate-200 flex flex-col items-center justify-center p-4 relative overflow-hidden">
    <div className="animated-grid opacity-30"></div>
    <div className="z-10 w-full flex flex-col items-center max-h-full">
      {children}
    </div>
  </div>
);

const App: React.FC = () => {
  const [profiles, setProfiles] = useState<UserProfile[]>([]);
  const [activeProfile, setActiveProfile] = useState<UserProfile | null>(null);
  const [currentView, setCurrentView] = useState<'profile-selector' | 'hub' | 'tetris' | 'chess' | 'snake' | 'chat' | 'diamond-rush' | 'memory' | 'void'>('profile-selector');
  const [newProfileName, setNewProfileName] = useState('');
  const [isShaking, setIsShaking] = useState(false);

  const { 
    board, activePiece, nextPiece, score, highScore, level, lines, bombs, useBomb,
    gameOver, paused, difficulty, isGameStarted, setPaused, 
    move, rotate, hardDrop, resetGame, startGame, resumeGame, hasSave 
  } = useTetris(activeProfile);

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      setProfiles(JSON.parse(saved));
    }
  }, []);

  useEffect(() => {
    if (profiles.length > 0) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(profiles));
    }
  }, [profiles]);

  const updateProfileStats = useCallback((statsUpdater: (p: UserProfile) => UserProfile) => {
    if (!activeProfile) return;
    const updatedProfiles = profiles.map(p => p.id === activeProfile.id ? statsUpdater(p) : p);
    setProfiles(updatedProfiles);
    setActiveProfile(updatedProfiles.find(p => p.id === activeProfile.id) || null);
  }, [profiles, activeProfile]);

  useEffect(() => {
    if (gameOver && activeProfile) {
      updateProfileStats(p => ({
        ...p,
        tetrisStats: {
          bestScore: Math.max(p.tetrisStats.bestScore, score),
          totalLines: p.tetrisStats.totalLines + lines,
          gamesPlayed: p.tetrisStats.gamesPlayed + 1
        }
      }));
    }
  }, [gameOver, score, lines, updateProfileStats, activeProfile]);

  const handleUpdateChessStats = (result: 'white' | 'black' | 'draw') => {
    updateProfileStats(p => {
      const stats = { ...p.chessStats };
      if (result === 'white') stats.wins++;
      else if (result === 'black') stats.losses++;
      else stats.draws++;
      return { ...p, chessStats: stats };
    });
  };

  const handleSnakeGameOver = (finalScore: number) => {
    updateProfileStats(p => ({
      ...p,
      snakeStats: {
        bestScore: Math.max(p.snakeStats.bestScore, finalScore),
        gamesPlayed: p.snakeStats.gamesPlayed + 1
      }
    }));
  };

  const handleDiamondRushGameOver = (finalScore: number, finalDiamonds: number) => {
    updateProfileStats(p => ({
      ...p,
      diamondRushStats: {
        bestScore: Math.max(p.diamondRushStats?.bestScore || 0, finalScore),
        totalDiamonds: (p.diamondRushStats?.totalDiamonds || 0) + finalDiamonds,
        gamesPlayed: (p.diamondRushStats?.gamesPlayed || 0) + 1
      }
    }));
  };

  const handleMemoryGameOver = (finalTime: number) => {
    updateProfileStats(p => ({
      ...p,
      memoryStats: {
        bestTime: p.memoryStats?.bestTime === 0 ? finalTime : Math.min(p.memoryStats?.bestTime || finalTime, finalTime),
        gamesPlayed: (p.memoryStats?.gamesPlayed || 0) + 1
      }
    }));
  };

  const handleVoidGameOver = (finalScore: number) => {
    updateProfileStats(p => ({
      ...p,
      voidStats: {
        bestScore: Math.max(p.voidStats?.bestScore || 0, finalScore),
        gamesPlayed: (p.voidStats?.gamesPlayed || 0) + 1
      }
    }));
  };

  const handleCreateProfile = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newProfileName.trim()) return;
    const newProfile: UserProfile = {
      id: Date.now().toString(),
      name: newProfileName.trim(),
      tetrisStats: { bestScore: 0, totalLines: 0, gamesPlayed: 0 },
      chessStats: { wins: 0, losses: 0, draws: 0 },
      snakeStats: { bestScore: 0, gamesPlayed: 0 },
      diamondRushStats: { bestScore: 0, totalDiamonds: 0, gamesPlayed: 0 },
      memoryStats: { bestTime: 0, gamesPlayed: 0 },
      voidStats: { bestScore: 0, gamesPlayed: 0 }
    };
    setProfiles(prev => [...prev, newProfile]);
    setActiveProfile(newProfile);
    setNewProfileName('');
    setCurrentView('hub');
  };

  const selectProfile = (p: UserProfile) => {
    setActiveProfile(p);
    setCurrentView('hub');
  };

  const logout = () => {
    setActiveProfile(null);
    setCurrentView('profile-selector');
    resetGame();
  };

  // Keyboard controls for Tetris
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (currentView !== 'tetris' || gameOver || !isGameStarted) return;
      switch (e.key) {
        case 'ArrowLeft': move(Direction.Left); break;
        case 'ArrowRight': move(Direction.Right); break;
        case 'ArrowDown': move(Direction.Down); break;
        case 'ArrowUp': rotate(); break;
        case ' ': hardDrop(); break;
        case 'b': if (bombs > 0) { useBomb(); setIsShaking(true); setTimeout(() => setIsShaking(false), 500); } break;
        case 'p': setPaused(!paused); break;
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [move, rotate, hardDrop, useBomb, paused, setPaused, gameOver, isGameStarted, currentView, bombs]);

  const checkCollisionHelper = (shape: number[][], pos: Position, b: Board) => {
    for (let y = 0; y < shape.length; y++) {
      for (let x = 0; x < shape[y].length; x++) {
        if (shape[y][x] !== 0) {
          const newX = pos.x + x;
          const newY = pos.y + y;
          if (newX < 0 || newX >= 10 || newY >= 20 || (newY >= 0 && b[newY][newX] !== null)) return true;
        }
      }
    }
    return false;
  };

  if (currentView === 'profile-selector') {
    return (
      <ViewContainer>
        <div className="w-full max-w-md space-y-10 z-10">
          <div className="text-center space-y-4">
            <h1 className="text-5xl font-black tracking-tighter text-transparent bg-clip-text bg-gradient-to-b from-white to-amber-500 font-orbitron italic">PRIME ARCADE</h1>
            <div className="flex items-center justify-center gap-4">
               <div className="h-[1px] flex-1 bg-gradient-to-r from-transparent to-amber-500"></div>
               <p className="text-[10px] text-amber-400 font-retro tracking-widest uppercase">Initializing Core Systems</p>
               <div className="h-[1px] flex-1 bg-gradient-to-l from-transparent to-amber-500"></div>
            </div>
          </div>
          <div className="bg-slate-900/40 backdrop-blur-md border border-amber-500/20 p-6 rounded-lg shadow-2xl">
            <h2 className="text-[11px] font-bold text-slate-400 uppercase tracking-widest mb-4 flex items-center gap-2">
              <i className="fa-solid fa-users-gear text-amber-500"></i> Active Operators
            </h2>
            <div className="max-h-64 overflow-y-auto space-y-3 custom-scrollbar pr-1">
              {profiles.map(p => (
                <button key={p.id} onClick={() => selectProfile(p)} className="w-full p-4 bg-black/40 border border-slate-800 hover:border-amber-400/60 hover:bg-amber-500/10 group transition-all flex items-center justify-between">
                  <div className="text-left">
                    <div className="text-base font-black group-hover:text-amber-400 font-orbitron uppercase">{p.name}</div>
                    <div className="text-[9px] text-slate-500 uppercase tracking-widest mt-1">EXP Units Verified</div>
                  </div>
                  <i className="fa-solid fa-play text-[12px] text-slate-700 group-hover:text-amber-400 animate-pulse"></i>
                </button>
              ))}
              {profiles.length === 0 && <div className="text-center py-10 border border-dashed border-slate-800 rounded text-[10px] text-slate-600 font-retro">NO USERS DETECTED</div>}
            </div>
            <form onSubmit={handleCreateProfile} className="mt-8 pt-6 border-t border-slate-800 space-y-4">
              <h2 className="text-[11px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-2">
                <i className="fa-solid fa-plus text-amber-500"></i> Register New Pilot
              </h2>
              <div className="flex gap-2">
                <input type="text" placeholder="INPUT CALLSIGN" value={newProfileName} onChange={(e) => setNewProfileName(e.target.value.toUpperCase())} maxLength={12} className="flex-1 bg-black/60 border border-slate-800 px-4 py-3 text-sm font-orbitron font-bold tracking-widest focus:border-amber-500 focus:outline-none placeholder:text-slate-700 text-amber-400" />
                <button type="submit" className="bg-amber-600 text-white px-6 py-3 text-xs font-black uppercase tracking-widest hover:bg-amber-500 active:scale-95 shadow-[0_0_20px_rgba(245,158,11,0.4)]">LINK</button>
              </div>
            </form>
          </div>
        </div>
      </ViewContainer>
    );
  }

  if (currentView === 'hub') {
    return (
      <ViewContainer>
        <div className="w-full max-w-lg space-y-8 z-10 pt-4 overflow-y-auto custom-scrollbar">
          <header className="flex justify-between items-center bg-slate-900/40 backdrop-blur-md p-4 border-l-4 border-amber-500 rounded-r-lg shadow-xl shrink-0">
            <div className="space-y-1">
              <h1 className="text-2xl font-black italic tracking-tighter text-white font-orbitron uppercase">COMMAND HUB</h1>
              <div className="flex items-center gap-3">
                <div className="flex gap-1"><span className="w-2 h-2 bg-green-500 rounded-full animate-ping"></span><span className="w-2 h-2 bg-green-500 rounded-full"></span></div>
                <span className="text-[10px] text-amber-400 font-retro uppercase">USER: {activeProfile?.name}</span>
              </div>
            </div>
            <button onClick={logout} className="text-[10px] font-black text-slate-500 hover:text-red-500 font-orbitron uppercase tracking-widest px-4 py-2 border border-slate-800 hover:border-red-500/40 transition-all">TERMINATE</button>
          </header>

          <div className="grid grid-cols-2 gap-4 pb-10">
            <button onClick={() => setCurrentView('tetris')} className="group relative aspect-square border border-slate-800 hover:neon-border-gold transition-all flex flex-col p-6 bg-slate-950/80 hover:bg-amber-500/5 rounded-xl">
              <i className="fa-solid fa-shapes text-5xl mb-auto text-amber-500/20 group-hover:text-amber-500 transition-all"></i>
              <div className="text-left">
                <h3 className="text-xl font-black italic text-white font-orbitron">TETRIS</h3>
                <div className="text-[8px] font-retro text-amber-400 mt-2">BEST: {activeProfile?.tetrisStats.bestScore}</div>
              </div>
            </button>
            <button onClick={() => setCurrentView('chess')} className="group relative aspect-square border border-slate-800 hover:neon-border-purple transition-all flex flex-col p-6 bg-slate-950/80 hover:bg-purple-500/5 rounded-xl">
              <i className="fa-solid fa-chess text-5xl mb-auto text-purple-500/20 group-hover:text-purple-500 transition-all"></i>
              <div className="text-left">
                <h3 className="text-xl font-black italic text-white font-orbitron">CHESS</h3>
                <div className="text-[8px] font-retro text-purple-400 mt-2">WINS: {activeProfile?.chessStats.wins}</div>
              </div>
            </button>
            <button onClick={() => setCurrentView('snake')} className="group relative aspect-square border border-slate-800 hover:neon-border-pink transition-all flex flex-col p-6 bg-slate-950/80 hover:bg-pink-500/5 rounded-xl">
              <i className="fa-solid fa-worm text-5xl mb-auto text-pink-500/20 group-hover:text-pink-500 transition-all"></i>
              <div className="text-left">
                <h3 className="text-xl font-black italic text-white font-orbitron">SNAKE</h3>
                <div className="text-[8px] font-retro text-pink-400 mt-2">BEST: {activeProfile?.snakeStats.bestScore}</div>
              </div>
            </button>
            <button onClick={() => setCurrentView('diamond-rush')} className="group relative aspect-square border border-slate-800 hover:neon-border-gold transition-all flex flex-col p-6 bg-slate-950/80 hover:bg-cyan-500/5 rounded-xl">
              <i className="fa-solid fa-gem text-5xl mb-auto text-cyan-500/20 group-hover:text-cyan-400 transition-all"></i>
              <div className="text-left">
                <h3 className="text-xl font-black italic text-white font-orbitron">GEMS</h3>
                <div className="text-[8px] font-retro text-cyan-400 mt-2">BEST: {activeProfile?.diamondRushStats?.bestScore || 0}</div>
              </div>
            </button>
            <button onClick={() => setCurrentView('memory')} className="group relative aspect-square border border-slate-800 hover:neon-border-purple transition-all flex flex-col p-6 bg-slate-950/80 hover:bg-purple-500/5 rounded-xl">
              <i className="fa-solid fa-brain text-5xl mb-auto text-purple-500/20 group-hover:text-purple-400 transition-all"></i>
              <div className="text-left">
                <h3 className="text-xl font-black italic text-white font-orbitron">MEMORY</h3>
                <div className="text-[8px] font-retro text-purple-400 mt-2">SYNC: OK</div>
              </div>
            </button>
            <button onClick={() => setCurrentView('void')} className="group relative aspect-square border border-slate-800 hover:neon-border-pink transition-all flex flex-col p-6 bg-slate-950/80 hover:bg-red-500/5 rounded-xl">
              <i className="fa-solid fa-jet-fighter-up text-5xl mb-auto text-red-500/20 group-hover:text-red-500 transition-all"></i>
              <div className="text-left">
                <h3 className="text-xl font-black italic text-white font-orbitron">VOID</h3>
                <div className="text-[8px] font-retro text-red-400 mt-2">THREAT: HIGH</div>
              </div>
            </button>
            <button onClick={() => setCurrentView('chat')} className="col-span-2 group relative border border-slate-800 hover:neon-border-gold transition-all flex items-center gap-6 p-4 bg-slate-950/80 rounded-xl">
              <i className="fa-solid fa-message text-3xl text-amber-500/20 group-hover:text-amber-500"></i>
              <div className="text-left">
                <h3 className="text-lg font-black italic text-white font-orbitron">NEURAL LINK (AI)</h3>
                <div className="text-[7px] font-retro text-amber-400">STATUS: ONLINE</div>
              </div>
            </button>
          </div>
        </div>
      </ViewContainer>
    );
  }

  if (currentView === 'tetris') {
    return (
      <div className={`h-screen bg-[#050505] text-slate-200 flex flex-col items-center justify-start py-2 px-2 overflow-hidden font-sans relative ${isShaking ? 'animate-shake' : ''}`}>
        <div className="animated-grid opacity-30"></div>
        <header className="w-full max-w-2xl flex items-center justify-between px-1 z-10 shrink-0 mb-2">
          <div className="flex flex-col">
            <h1 className="text-lg font-black tracking-wider text-white uppercase font-orbitron italic">Tetris Prime <span className="text-amber-500">Gold</span></h1>
            <span className="text-[8px] text-amber-400 font-retro uppercase">PILOT: {activeProfile?.name}</span>
          </div>
          <div className="flex gap-2">
            <button onClick={() => setPaused(!paused)} className="w-10 h-10 border border-slate-800 bg-slate-900/40 rounded flex items-center justify-center">
              <i className={`fa-solid ${paused ? 'fa-play' : 'fa-pause'}`}></i>
            </button>
            <button onClick={() => setCurrentView('hub')} className="text-[10px] font-black text-slate-400 hover:text-red-400 border border-slate-800 px-3 py-2 bg-slate-900/40 font-orbitron uppercase">EXIT</button>
          </div>
        </header>

        <div className="flex gap-4 items-stretch justify-center w-full max-w-2xl h-[calc(100vh-180px)] z-10 mb-4 transition-all">
          <div className="flex-1 flex justify-center h-full max-w-[340px]">
            <BoardView board={board} activePiece={activePiece} checkCollision={checkCollisionHelper} bombsCount={bombs} />
          </div>
          <div className="flex flex-col gap-2 w-24 shrink-0">
            <GameUI score={score} highScore={highScore} level={level} lines={lines} bombs={bombs} nextPiece={nextPiece} />
            <div className="mt-auto">
               <AISuggestions board={board} nextPiece={nextPiece} score={score} level={level} />
            </div>
          </div>
        </div>

        <div className="w-full flex flex-col items-center gap-1 z-20 shrink-0 pb-4">
          <Controls 
            onMove={move} 
            onRotate={rotate} 
            onHardDrop={hardDrop} 
            onBomb={() => { if (bombs > 0) { useBomb(); setIsShaking(true); setTimeout(() => setIsShaking(false), 500); }}} 
            bombs={bombs} 
          />
        </div>

        {(!isGameStarted || gameOver || paused) && (
          <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-50 flex flex-col items-center justify-center p-6 text-center">
            {gameOver ? (
              <div className="space-y-6 animate-in zoom-in duration-300">
                <h2 className="text-5xl font-black italic font-orbitron text-red-500 tracking-tighter">GAME OVER</h2>
                <div className="bg-slate-900/50 p-6 border border-slate-800 rounded">
                  <p className="text-[10px] text-slate-500 font-retro uppercase mb-2">Final Performance</p>
                  <div className="text-3xl font-black font-orbitron text-white">{score.toLocaleString()}</div>
                  <div className="text-[8px] text-amber-500 font-retro uppercase mt-4">Level {level} • {lines} Lines</div>
                </div>
                <div className="flex flex-col gap-3">
                  <button onClick={() => startGame(difficulty)} className="w-64 py-4 bg-white text-black font-black font-orbitron uppercase italic tracking-widest hover:bg-amber-500 transition-all">REBOOT SYSTEM</button>
                  <button onClick={() => setCurrentView('hub')} className="text-xs font-bold text-slate-500 uppercase tracking-widest py-2">RETURN TO HUB</button>
                </div>
              </div>
            ) : paused ? (
              <div className="space-y-6">
                <h2 className="text-4xl font-black italic font-orbitron text-amber-500 tracking-tighter">PAUSED</h2>
                <button onClick={() => setPaused(false)} className="w-64 py-4 bg-white text-black font-black font-orbitron uppercase italic tracking-widest hover:bg-amber-500 transition-all">RESUME LINK</button>
              </div>
            ) : (
              <div className="space-y-8 animate-in zoom-in duration-300">
                <div className="space-y-2">
                  <h2 className="text-4xl font-black italic font-orbitron text-white tracking-tighter">TETRIS PRIME</h2>
                  <p className="text-[10px] text-amber-500 font-retro uppercase tracking-widest animate-pulse">Select Difficulty Protocol</p>
                </div>
                <div className="flex flex-col gap-3">
                  {(Object.keys(Difficulty) as Array<keyof typeof Difficulty>).map((diff) => (
                    <button 
                      key={diff} 
                      onClick={() => startGame(Difficulty[diff])}
                      className="w-64 py-4 border border-slate-800 bg-slate-900/40 text-white font-black font-orbitron uppercase italic tracking-widest hover:neon-border-gold hover:bg-amber-500/10 transition-all"
                    >
                      {diff}
                    </button>
                  ))}
                  {hasSave && (
                    <button onClick={resumeGame} className="w-64 py-4 bg-amber-600 text-white font-black font-orbitron uppercase italic tracking-widest hover:bg-amber-500 transition-all mt-4">RESUME SESSION</button>
                  )}
                </div>
              </div>
            )}
          </div>
        )}
      </div>
    );
  }

  if (currentView === 'chess') {
    return (
      <ViewContainer>
        <ChessGame onExit={() => setCurrentView('hub')} onUpdateStats={handleUpdateChessStats} />
      </ViewContainer>
    );
  }

  if (currentView === 'snake') {
    return (
      <ViewContainer>
        <SnakeGame onExit={() => setCurrentView('hub')} onGameOver={handleSnakeGameOver} highScore={activeProfile?.snakeStats.bestScore || 0} />
      </ViewContainer>
    );
  }

  if (currentView === 'diamond-rush') {
    return (
      <ViewContainer>
        <DiamondRush onExit={() => setCurrentView('hub')} onGameOver={handleDiamondRushGameOver} highScore={activeProfile?.diamondRushStats?.bestScore || 0} />
      </ViewContainer>
    );
  }

  if (currentView === 'chat') {
    return (
      <ViewContainer>
        <ChatRoom userName={activeProfile?.name || 'Unknown'} onExit={() => setCurrentView('hub')} />
      </ViewContainer>
    );
  }

  if (currentView === 'memory') {
    return (
      <ViewContainer>
        <MemoryMatch 
          onExit={() => setCurrentView('hub')} 
          onGameOver={handleMemoryGameOver} 
          bestTime={activeProfile?.memoryStats?.bestTime || 0} 
        />
      </ViewContainer>
    );
  }

  if (currentView === 'void') {
    return (
      <ViewContainer>
        <VoidShooter 
          onExit={() => setCurrentView('hub')} 
          onGameOver={handleVoidGameOver} 
          highScore={activeProfile?.voidStats?.bestScore || 0} 
        />
      </ViewContainer>
    );
  }

  return null;
};

export default App;

